window.READING_ROOM = {"title":"Agent Memory Study","intro":"这组材料不按排行榜排列，而是沿着状态、写入、检索、行动、抽象、元认知与信念修订等故障面来读。","editorialNote":"以下内容来自逐篇明确标注阅读范围与 noteDepth 的 reading notes，是阅读导航，不是论文摘要的替代；未读或未复核的实验、附录与实现不应被当作已验证。具体主张、数字和限定请回到随附 PDF。","atlas":{"thesis":"Agent memory fails in layers.","dek":"把记住、取回、修订与行动拆开看。这里不是排行榜，也不把未读变成债。","editorialLabel":"编者研究地图 · 跨源 synthesis，不是任何单篇论文的主张","easterEgg":{"heroWord":"fails","heroReveal":"lives","aboutLine":"Some memories are worth an architecture.","aboutReveal":"ours is one of them."},"failureSurfaces":[{"number":"01","id":"state-representation","label":"State / representation","question":"记录里的状态怎样被表示，并在变化后保留角色？","tension":"旧记录仍在，不等于它应被当作当前事实；时间顺序也不能独自说明 change、correction 或 coexistence。","materialIds":["a-tma-state-aware-memory","mosaic-long-term-memory","memory-beyond-recall","statefuse-conflict-preserving-memory","fluctlightdb-observation-binding","memprobe-hidden-user-state-recovery"]},{"number":"02","id":"write-consolidation","label":"Write / consolidation","question":"什么被写入、合并、修订或拒绝，谁来校验？","tension":"一个 mutation 可以通过 schema 与 policy 检查，却仍可能在语义上遗漏、破坏或无依据新增。","materialIds":["trustmem-consolidation","verifiable-memory","mistake-notebook-learning","agentic-memory","memory-beyond-recall","statefuse-conflict-preserving-memory","memora-from-recall-to-forgetting"]},{"number":"03","id":"retrieval-active-context","label":"Active context / retrieval","question":"所需证据是否进入候选、排序和 active context？","tension":"东西留在 store 里仍可能因为 candidate miss、ordering、dilution 或不合时宜的注入而不可用。","materialIds":["a-tma-state-aware-memory","verifiable-memory","mistake-notebook-learning","coala-cognitive-architecture","continual-learning-experience-reuse","agentic-memory","insightemb-action-intent-retrieval","longmemeval-v2-experienced-colleague","fluctlightdb-observation-binding","memprobe-hidden-user-state-recovery"]},{"number":"04","id":"wake-prospective-action","label":"Wake / prospective action","question":"记住的意图能否在合适时机触发，又避免重复或误触？","tension":"recall 正确不等于 action timing 正确；cue、取消、完成与 monitoring cost 是另一组责任。","materialIds":["proactive-wake-anchor","pm-bench"]},{"number":"05","id":"abstraction-experience","label":"Abstraction / experience reuse","question":"经验怎样压缩成可复用抽象，又怎样随来源失效？","tension":"更可复用的 insight 或 schema 也更容易脱离 source；抽象层级不会自动增加 authority。","materialIds":["mistake-notebook-learning","coala-cognitive-architecture","storage-to-experience","continual-learning-experience-reuse","truth-maintenance-system","memory-beyond-recall","insightemb-action-intent-retrieval","longmemeval-v2-experienced-colleague"]},{"number":"06","id":"metacognitive-control","label":"Metacognitive control","question":"系统何时监控自己的过程，并把 discrepancy 升级为行动？","tension":"发现异常不等于获准继续；监控、解释、生成 goal 与执行需要保持可区分。","materialIds":["midca-dual-cycle"]},{"number":"07","id":"justification-revision","label":"Justification / revision","question":"一句 belief 受什么支持，支持变化时怎样修订？","tension":"当前有 justification 不等于来源为真；形式 revision 也不能授权覆盖 raw source。","materialIds":["truth-maintenance-system","agm-theory-change","statefuse-conflict-preserving-memory","memora-from-recall-to-forgetting"]}],"readingPaths":[{"number":"01","id":"from-answer-failure","title":"从一次答错开始","description":"从 terminal error 倒推 bank、retrieval 与 QA 各自可能失效的位置。","materialIds":["a-tma-state-aware-memory","verifiable-memory","insightemb-action-intent-retrieval","longmemeval-v2-experienced-colleague","continual-learning-experience-reuse","fluctlightdb-observation-binding","memprobe-hidden-user-state-recovery"]},{"number":"02","id":"from-revision","title":"从 revision 开始","description":"先区分支持、修订与状态变化，再回到 learned write policy 的 authority 问题。","materialIds":["truth-maintenance-system","agm-theory-change","a-tma-state-aware-memory","trustmem-consolidation","memory-beyond-recall","statefuse-conflict-preserving-memory"]},{"number":"03","id":"from-action-timing","title":"从行动时机开始","description":"从 cue、wake 与执行切入，理解记得一件事为什么仍可能在错误时间发生。","materialIds":["pm-bench","proactive-wake-anchor","midca-dual-cycle","insightemb-action-intent-retrieval"]}]},"filters":["记忆架构","可靠性","前瞻记忆","持续学习","信念修正"],"materials":[{"number":1,"id":"a-tma-state-aware-memory","kind":"paper","title":"A-TMA: Decoupling state-aware memory failures in long-term agent memory","authors":["Zitong Shi","Yixuan Tang","Anthony Kum Hoe Tung"],"shortAuthor":"Shi 等","year":2026,"doi":null,"noteDepth":"read","readingScope":"arXiv v2（2026-07-08）§1–§6、Appendix A.1–A.11、Tables 1–5、Figures 1–3 与 Algorithm 1；references 只用于 lineage 定位，未逐篇 close-read；未复现代码或数据。","intro":"A-TMA 把 ghost memory 重新定义为跨层的 state-coordination failure：旧值、现值与 transition evidence 可以同时正确地留在 bank，错误则可能发生在 bank role、按 query view 组织 retrieval evidence，或 QA 选择状态的任一层。（§1；§3；Figure 1，PDF pp. 1–2、5）","whyRead":"它最值得读的地方不是又提出一个 memory overlay，而是给 terminal answer 之前的失败建立了可追踪的层次：recorded、historically recoverable、retrieved for this view 与 used correctly by QA 不再被压成同一个“记住了”。这套 decomposition 也让新的风险变得可见——谁给 state 定角色、谁选择 query view、谁把 label 写进 prompt，谁就在 read side 获得了实际的 evidence authority。","keyPoints":["Bank：每条 record 包含 content、time/source position、state status、typed links 与 host metadata；status 包括 active、superseded、transition、unknown，links 可表达 supersession、evolution、scoped exception 与 coexistence。（§4.1–§4.3，PDF pp. 5–7）","Retrieval：rule-based query profiler 先选择 current、historical、transition 或 neutral view，再把 host seed、relation hops 与 bounded controller 组成 evidence packet；controller 只能重排已有候选，不能找回 missing record。（§4.4；Appendix A.8，PDF pp. 8–9、18）","QA：serializer 把 evidence trace 标成 current、historical、transition 或 generic retrieved memory，再交给 generator；因此 bank 中 recorded、retrieval 中 available 与 answer 中 used correctly 是可分开的事实。（§4.5–§4.6；Algorithm 1，PDF pp. 9–10、19）"],"argumentMap":[{"step":"01 · 先改写错误对象","claim":"旧记录存在本身不是 ghost memory。旧值、现值与 transition evidence 可以同时为真；错误在于它们没有被赋予或读取为 query 所需的 state role。","locator":"§1；§3；Figure 1，PDF pp. 1–2、5"},{"step":"02 · 再把状态写进可检查的 record","claim":"每条 record 除 content 与时间外，还携带 active、superseded、transition、unknown 等 status，以及 supersession、evolution、scoped exception、coexistence 等 typed links；目标不是删除旧值，而是保留可追踪的关系。","locator":"§4.1–§4.3，PDF pp. 5–7"},{"step":"03 · 让 retrieval 对 query view 负责","claim":"query profiler 先把问题分成 current、historical、transition 或 neutral view，retrieval 再从 host seed、state links 与 controller 组成 evidence packet；缺失记录、错误排序与错误 view 因而可以分开观察。","locator":"§4.4；Appendix A.8，PDF pp. 8–9、18"},{"step":"04 · 最后把 answer-side selection 单独暴露","claim":"serializer 把 state role 明示给 generator，使“证据已经在 packet 中但 QA 仍选错状态”不再被误判为 retrieval miss。terminal answer 正确也不能反向证明前面的 bank 与 retrieval 正确。","locator":"§4.5–§4.6；Algorithm 1，PDF pp. 9–10、19"}],"methodNotes":[{"label":"LTP construct","text":"LTP 以 10 个 LoCoMo-anchored profiles 为骨架，每个 profile 建 40 个 mutable slots；每个 slot 插入较早 old-state cue 与较晚 current/conflicting cue，再各生成 historical 与 current probe。完整规模是 400 state units、800 cue events 与 800 probes。它是受控生成的 state-change benchmark，不是 400 次自然对话中的真实状态变化。","locator":"Appendix A.1–A.3，PDF pp. 15–16"},{"label":"Bank supervision","text":"Sentry 用 topic / logic 双 projection head 筛出 risky pairs；Qwen2.5-3B audit Judge 再决定 conflict、fusion action、clarification need 与 suggested links。Judge 先在 700 个 English items 上 QLoRA SFT，再以规则奖励做 GRPO，并在 151-item held-out set 上报告 87.4% accuracy 与 0.8774 F1。","locator":"§4.3；Appendix A.8，PDF pp. 6–7、17–18"},{"label":"Retrieval control","text":"rule-based profiler 根据 temporal/change lexical hints 选 view；host seeds 加入 relation hops 与较弱 semantic hops 后稳定预排。optional 3B controller 只能在给定 candidate pool 内选择，parse 或 ID validation 失败则回退，因此它无法修复 candidate miss。","locator":"§4.4；Appendix A.8，PDF pp. 8–9、18"},{"label":"Answer measurement","text":"QA 固定 top-5 evidence budget，使用 qwen2.5:3b 生成答案，llama3.3:70b 只作 offline answer judge。对 100 个 outputs 的 human audit 中，三分类 agreement 在 LTP 为 88.0% / κ 0.820，在 LoCoMo 仅 72.0% / κ 0.578；合并 correct 与 partially correct 后 overall binary agreement 才升至 93.0% / κ 0.847。","locator":"§5.1；Appendix A.5、A.8，PDF pp. 10、16–18"}],"reportedFindings":["Full LTP 上，A-Mem+A-TMA 的 aggregate QA accuracy 为 0.818、conflict 为 0.860，相对 A-Mem 分别提高 0.031 与 0.048；但 70B judge score 从 0.700 微降到 0.698。Graphiti/Zep+A-TMA 的 QA accuracy 从 0.524 到 0.635、conflict 从 0.480 到 0.720，同时 fact accuracy 从 0.568 降到 0.550。（Table 2，PDF p. 11）","InsideOut+A-TMA 在 LTP 的 QA accuracy 从 0.117 升到 0.662，是最大的同-host delta；同一 row 的 displayed bank score 仍为 0.000，与正文所说 bank、retrieval、QA 三层都修复并不相容。（§5.2；Table 2，PDF p. 11）","Full LoCoMo 含 10 个 samples、1,986 个 QA pairs。AriadneMem 仍有最高 average F1 0.2240；Graphiti/Zep+A-TMA 的 temporal F1 从 0.0295 到 0.1705，但 temporal judged QA 从 0.3707 降到 0.3178，open-domain 与 adversarial 指标也下降。（Tables 3–4，PDF pp. 11–12）","A-Mem+A-TMA 在 LoCoMo 的 average F1、BLEU 与 judged QA 小幅上升，但 multi-hop 三项都下降；效果随 host、question category 与 metric 改变，不能收缩成 uniform improvement。（Table 4；§5.3，PDF p. 12）"],"evidenceLimits":["它是尚未经过同行评审的 arXiv preprint；正文没有给出可定位的 code 或 LTP dataset release，因此这些是 paper-reported point estimates，不是复现结果。","论文没有报告 repeated seeds、confidence intervals、bootstrap、significance test 或 per-profile variance；800 probes 嵌套在 10 个 shared replay banks 与 400 个 paired state units 中，不能直接当作 800 个独立实验单位。","LTP 是从 10 个 LoCoMo-anchored profiles 构造的 controlled synthetic benchmark；后续 LoCoMo evaluation 也使用 10 个 LoCoMo samples，论文没有证明 conversation/profile lineage 独立。transition view 没有直接 change-QA target，neutral view 也没有独立结果。（Appendix A.1–A.4，PDF pp. 15–16）","LTP 的 cue1 / cue2 被放在分离的 time quantiles，old/current probes 也可能与 lexical profiler 的 hand-written hints 对齐；没有 chronology-only、reversed-quantile、oracle-view 或 shuffled-label controls，无法分离受控 temporal geometry 与 learned overlay 的贡献。","Sentry 的 logic=0 同时容纳 same-slot conflict 与 irrelevant negative；论文未给 per-class confusion matrix、true-predecessor candidate recall、false-negative supersession rate 或 similar-slot stress test。正确 prior state 若未进入候选，Sentry 与 Judge 都无法补回。","Bank role 与 Evidence support 是 pipeline diagnostics，不是独立、统一的 effect size。前者按 host-native status/link 个性化，后者没有公开 matching algorithm、threshold、paraphrase handling 或 reliability audit；Average Rank 还重复混合 aggregate QA 及其 conflict/fact partitions。"],"sourceTensions":[{"label":"Full row 与 no-Sentry 叙述对不上","observation":"Table 5 的 Full row 在 QA / preferred / judge 上均高于 -Sentry；Appendix A.10 却说 no-Sentry 最好，并引用表中不存在的数值。controller ablation 的起点也取自另一条 no-Sentry row。","implication":"在 raw results 或作者 correction 出现前，不能从 Table 5 与 Appendix A.10 中挑一套数字来做 component attribution。","locators":["Table 5，PDF p. 12","Appendix A.10，PDF p. 19"]},{"label":"QA-label ablation 的方向相反","observation":"Appendix A.10 声称 removing QA labels 令 conflict 升到 0.858；Table 5 中 Full 已是 0.858，no-label row 是 0.850。A.10 还描述一个所有 variants 为 0.500 的 internal bank diagnostic，而表中 Bank coexist 全为 1.000。","implication":"serializer label 与 bank component 的单独贡献都没有稳定、可读的公开数值依据。","locators":["Table 5，PDF p. 12","Appendix A.10，PDF p. 19"]},{"label":"Controller 到底看哪些 candidates","observation":"§4.4 把 controller 写成对完整 candidate set 操作，Appendix A.8 说最多看 10 条 shortlist，Algorithm 1 则在 TopK 之后才调用 controller；reported k=5 时，最后一种读法只给它 5 条。","implication":"这决定 controller 能否救回 rank 6–10 的 target，也决定 no-controller ablation 实际移除了什么。","locators":["§4.4，PDF pp. 8–9","Appendix A.8，PDF p. 18","Algorithm 1，PDF p. 19"]},{"label":"InsideOut 的三层修复缺一层","observation":"§5.2 说 InsideOut+A-TMA 在 bank、retrieval 与 QA 三层修复 failure chain；Table 2 的同一 row 却显示 Bank role 为 0.000。","implication":"现有文本无法判断 sidecar role 是否被 scorer 排除、gain 是否主要来自 retrieval / QA，或 narrative / displayed value 是否过期。","locators":["§5.2，PDF p. 11","Table 2，PDF p. 11"]}],"editorialInferences":[{"label":"Read-side label amplification","text":"显式 state label 即使不改写 bank，也会在 answer time 前景化某条证据；如果 classifier 或 bank Judge 判错，它可能让错误比 raw chronology 更有说服力。","boundary":"这是根据论文 architecture 作出的编者 inference，不是 paper-tested result；论文没有报告 corrupted-label、false-supersession 或 wrong-role negative control。"},{"label":"Diagnosability is instrumentation, not causality","text":"把 bank、retrieval 与 QA 分层记录，会让 failure localization 更可检查；但一个 trace 字段能指出哪层看起来异常，不等于它已经证明该层是 causal source，更不等于该层的 learned judge 判定正确。","boundary":"这是对 measurement contract 的编者 synthesis。Table 5 的表文冲突与缺少 layer-wise error-transition matrix，使 causal attribution 仍未成立。"},{"label":"Role metadata is an authority surface","text":"active、superseded、transition 与 coexistence 不是无害的检索标签：它们决定某条记忆何时被前景化、何时只作为历史、何时被压低。即使 canonical store 不被覆盖，read path 仍在执行事实角色分配。","boundary":"这是由 architecture 产生的 editorial consequence，不是论文声称或验证的 governance result；时间顺序与 LLM conflict verdict 都不能单独取得这种 authority。"}],"openProtocols":[{"title":"State-label corruption stress test","status":"proposed-not-run","question":"显式 state labels 在正确时帮助 QA，在错误时会不会比 raw chronology 更强地放大 wrong-state intrusion？","method":"对同一组 synthetic multi-state records 固定内容、时间与 retrieval candidates，只改变 serialized state role；比较 raw chronology、correct labels、swapped labels 与 partially missing labels 四条 read paths。","fixtures":"公开 synthetic fixtures 覆盖 current、historical、transition、coexistence、scoped exception、correction 与 target-absent；不使用任何 private memory、人物或运行时实现。","controls":"加入 false-supersession、wrong-view、target-absent、label-shuffle 与 no-label controls；generation model、prompt budget、candidate order 与 decoding 固定。","measures":"逐题公开 candidate support、wrong-state intrusion、answer correctness、abstention 与 confidence；raw outputs 与 derived aggregates 分开保存。","limitations":"这是尚未执行的 paper-facing protocol，只能检验 label sensitivity；不能证明某个未公开实现的 production safety，也不能替代作者 code / dataset reproduction。"}],"keywords":["temporal state","memory retrieval","failure diagnosis"],"categories":["可靠性"],"failureSurfaces":["state-representation","retrieval-active-context"],"sourceUrl":"https://arxiv.org/abs/2607.01935","pdf":{"delivery":"official","url":"https://arxiv.org/pdf/2607.01935v2","accessNote":"arXiv v2 preprint"},"editorialQuestion":"transition view 本身没有被直接作为问答目标充分测试；在含糊、并存或带条件例外的状态里，query-view 与 state-role classifier 会不会只是新的错误入口？","sourceNote":"arXiv v2；本站链接官方 PDF，不在 repo 内重新分发。"},{"number":2,"id":"trustmem-consolidation","kind":"paper","title":"TRUSTMEM: Learning trustworthy memory consolidation for LLM agents with long-term memory","authors":["Tianyu Yang","Sudipta Paul","Vijay Srinivasan","Vivek Kulkarni","Srinivas Chappidi"],"shortAuthor":"Yang 等","year":2026,"doi":null,"noteDepth":"skim","readingScope":"Abstract、§3–§5、Limitations；未逐项复核 benchmark 或训练实现。","intro":"把 memory consolidation 看作一连串可检查的状态转换，在错误成为持久状态之前检查遗漏、破坏和无依据新增。","keyPoints":["policy 按时间顺序处理 chunk，对累计 memory 执行 Write、Revise、Prune；terminal memory 交给固定 retriever 与 answer model，因此训练重点是写入与更新策略。（§3.1）","Memory Transition Verifier 只查看当前 chunk、编辑动作和受影响的局部 memory，分别检查 coverage、preservation 与 faithfulness。（§3.2）","训练把 downstream utility、compactness、action executability、specificity 与 transition trustworthiness 合并；去掉 verifier reward 后，论文报告的总体分数从 66.3 降到 58.7。（§3.3–§4.4）"],"keywords":["memory consolidation","transition verification","write policy"],"categories":["可靠性"],"failureSurfaces":["write-consolidation"],"sourceUrl":"https://arxiv.org/abs/2606.25161","pdf":{"delivery":"bundled","url":"papers/02-yang-2026-trustmem.pdf","originalUrl":"https://arxiv.org/pdf/2606.25161v1","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/"},"editorialQuestion":"核心 verifier 和关键 reliability 数字都依赖 LLM judge；怎样证明它测到的不只是 rubric adherence，而是独立、可复核的事实可靠性？","sourceNote":""},{"number":3,"id":"verifiable-memory","kind":"paper","title":"Verifiable memory: Learning unified memory management with local and global verifiers for large language model agents","authors":["Xiaolong Sun","Qichao Wang","Hangyu Li","Liang Chen"],"shortAuthor":"Sun 等","year":2026,"doi":null,"noteDepth":"skim","readingScope":"Abstract、§3–§6；只定位 supplementary 结构，未完整读完。","intro":"用同一个 policy 管理 persistent memory、active context 与 episodic history，并把单次 transition 与整段任务结果分别交给 local/global verifier。","keyPoints":["policy 面对的是不超过 8,192 tokens 的 active serialization；信息离开 active context 后仍可保留在 episodic record，而不是无界拼接 history。（§3.1）","七个 atomic tools 覆盖 LTM 的 Add、Update、soft-Delete，以及 STM 的 Retrieve、Filter、SelectEpisode、Summarize；SelectEpisode 可恢复已经退出 active context 的证据。（§3.2）","policy 只在 HotpotQA 上训练，再转移到多个环境；但每个 episode 后所有 memory state 都会重置，实验测到的是 within-episode persistence 与 policy transfer。（§4–§5）"],"keywords":["active context","episodic retrieval","policy verification"],"categories":["可靠性"],"failureSurfaces":["write-consolidation","retrieval-active-context"],"sourceUrl":"https://arxiv.org/abs/2608.03137","pdf":{"delivery":"official","url":"https://arxiv.org/pdf/2608.03137v1"},"editorialQuestion":"如果 persistent state 从未跨 episode 延续，这套结果能在多会话、冲突或隐私敏感的长期记忆中保持吗？","sourceNote":""},{"number":4,"id":"mosaic-long-term-memory","kind":"paper","title":"Accurate and efficient long-term memory for LLM agents","authors":["Zicheng Zhao","Xinyang Guo","Luyao Lv","Menghan Wang","Ming Li","Shuaicheng Li"],"shortAuthor":"Zhao 等","year":2026,"doi":null,"noteDepth":"skim","readingScope":"Abstract、§3–§6；未复现 benchmark 或 latency 测量。","intro":"用 typed graph、局部稳定性更新和写入前冲突检查来管理 event、persona 与 relationship memory。","keyPoints":["memory 被表示为 event、persona、relationship typed graph，并区分 prerequisite graph 与 association graph；节点带 embedding、confidence 与 timestamp。（§3.2）","Neighbor-Conditioned Stability 只在节点邻居改变时用 dirty flags 重算，论文给出的局部更新复杂度为 O(Δmax)。（§3.3；§3.9）","写入前先找近邻，再由 LLM 检查 numerical、semantic、logical conflict；低于 0.6 confidence 的 extraction 等待 clarification。50 条 injected errors 中检测出 33 条。（§3.5–§3.6；§5.2）"],"keywords":["graph memory","conflict detection","local invalidation"],"categories":["记忆架构"],"failureSurfaces":["state-representation"],"sourceUrl":"https://arxiv.org/abs/2607.16211","pdf":{"delivery":"official","url":"https://arxiv.org/pdf/2607.16211v1"},"editorialQuestion":"正文对 LSH 与 HNSW 的描述并不完全一致，且 0.58 秒只计 search latency；完整 extraction、conflict check 与 write path 的准确率—延迟权衡究竟怎样？","sourceNote":""},{"number":5,"id":"proactive-wake-anchor","kind":"paper","title":"Do proactive agents really need an LLM to decide when to wake and what to anchor?","authors":["Xiaoze Liu","Ruowang Zhang","Amir H. Abdi","Michel Galley","Zhikai Chen","Siheng Xiong","Xiaoqian Wang","Jing Gao"],"shortAuthor":"Liu 等","year":2026,"doi":null,"noteDepth":"skim","readingScope":"Abstract、§3–§6、Limitations；未通读 related work、附录、prompts 或 graph-construction 细节。","intro":"把是否唤醒和依据哪些实体从生成模型中拆出，交给共享 temporal-graph backbone 的 trigger 与 routing heads。","keyPoints":["event head 输出 trigger probability，entity head 输出 routing score；只有 trigger 通过后才调用 downstream LLM 生成用户可见语言。（§3–§4）","同一个 TGL checkpoint、threshold 与 prompt 用于 14 个 downstream backbones，论文报告所有 backbone 的 F1 都提高，平均提升 16.7。（§5.1–§5.2）","ablation 显示随机替换 routed entities 的平均损失大于强制每个 event 都唤醒；consumer-laptop latency 报告为 13.99 ms，BF16 resident footprint 约 220 MiB。（§5.3–§5.5）"],"keywords":["proactive agents","wake control","temporal graphs"],"categories":["前瞻记忆"],"failureSurfaces":["wake-prospective-action"],"sourceUrl":"https://arxiv.org/abs/2605.30152","pdf":{"delivery":"bundled","url":"papers/05-liu-2026-proactive-agents.pdf","originalUrl":"https://arxiv.org/pdf/2605.30152v1","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/"},"editorialQuestion":"证据来自 text-serialized activity stream 与 offline reward-model judge；接入原生事件后，触发校准和真实 interruption cost 是否仍成立？","sourceNote":""},{"number":6,"id":"pm-bench","kind":"paper","title":"PM-bench: Evaluating prospective memory in LLM agents","authors":["Genglin Liu","Saadia Gabriel"],"shortAuthor":"Liu 等","year":2026,"doi":null,"noteDepth":"worked","readingScope":"完整读了 arXiv v1 的 §§1–6、Ethics Statement、Appendix A.1–A.6、Tables 1–7 与 Figures 1–4，共 22 个 PDF pages；references 只用于 lineage 定位。另检查 official code / data commit e1093c470c8981daf522d4ef047a7c3a71e077d7，运行三个 deterministic scorer-contract probes，验证并重算 64 份 released primary logs、重建 official comparison report；没有调用模型、生成新 trajectory、复现实验采样过程或测试第二个 synthetic week。PDF 的 pypdf preflight 因依赖未安装只能标为 advisory unavailable；页数与关键定位已用 pdfinfo、两种 pdftotext page breaks 和 rendered pages 交叉核对。","intro":"PM-Bench 把“记得意图”与“在正确 cue/time 行动或抑制旧行动”拆开：一个固定 synthetic week 同时施加 time/event cues、hidden state channels、updates、lures 与 false-positive 成本。本站复核发现 headline Set-F1 可重建，但三处 diagnostic contract 需要收窄：monitoring hit 不证明 query provenance，update violation 会包含 accepted current-state late action，scorer 也不以 step_id 绑定 row identity。","whyRead":"这篇值得深读，因为它把 prospective memory 从普通 recall benchmark 中剥离出来：真正难的不是回忆一句旧事实，而是保持意图、监控环境、在 cue 到来时执行、在 cue 未到时克制，并在 cancel / override / reschedule 后放弃旧目标。更重要的是，它把 precision、false positives、query volume 与 update handling 同时摆上桌，让“更主动”不再自动等于“更好”。公开 scorer audit 又暴露出评测语言与可观测 contract 的边界：一个有解释力的 diagnostic 名称仍可能比代码实际测到的对象更强。","keyPoints":["Evaluation object：agent 不只要保存 intention，还要在正确 time/event cue 选择 task、在无 cue 时不误触，并让 cancellation、override、reschedule 改写后续有效行为；scoring 同时记录 hit/late/miss、set TP/FP/FN、update 与 query counts。（§§1、3.1、3.3；Appendix A.4，PDF pp. 1、3–5、16–17）","Fixed week：发布的一个 seeded synthetic week 有 7 days、80 steps、83 task definitions，其中 81 scored、2 canceled；另有 11 state channels、11 update events、74 lures，并要求 query-then-act。（Table 1；§3.1，PDF pp. 3–4）","Precision–monitoring tradeoff：optional heartbeat 的跨模型 macro Set-F1 最高为 65.1%；30-minute auto heartbeat 提高部分 update / monitoring hit，却产生 489 FP；hierarchical union 发出 1661 次 state queries，仍只有 45.2% macro Set-F1。（Table 2；§§4.2–4.5，PDF pp. 7–9）","Scorer contract：public audit 在 exact official commit 上确认 monitoring/channel hits 不以 required-channel query 为条件、updated current mutable task 的 accepted-late selection 仍可计 update_violation、row order 可覆盖 declared step_id；但 64 份 released logs 的 step identity 全部有效，realignment 改变 0 个分数，headline aggregates 保持不变。（public test artifact）"],"argumentMap":[{"step":"01 · 先把 prospective memory 从 recall 拆出来","claim":"论文把 prospective memory 定义为 deferred intention 的保持与适时执行：同样记得 task，不代表 agent 能识别 cue、在正确 window 动作、在其余 steps 抑制误触，或在计划更新后停止旧行为。","locator":"§§1–2，PDF pp. 1–2"},{"step":"02 · 用一个可审计 synthetic week 固定环境","claim":"benchmark 以 seeded generator、rejection sampling、manual review、scenario validator 与 perfect-play audit 构造 7-day/80-step week；任务、cues、hidden channels、updates 与 lures 在同一时序里共同施压。","locator":"§§3.1–3.3；Table 1，PDF pp. 3–5"},{"step":"03 · 把 agent scaffold 当作 monitoring policy 比较","claim":"single baseline、todo ledger、optional/automatic heartbeat 与 hierarchical aggregation 不是单一能力刻度：它们在 recall、wake frequency、query cost、false positives 与 update handling 之间选择不同 operating points。","locator":"§3.2；§§4.2–4.5；Tables 2–3，PDF pp. 4、7–9"},{"step":"04 · 结果指向 control problem，而非 context-window victory","claim":"最强 aggregate 仍不完美；更频繁 monitoring 可以提高某些 hit rate，却也放大误触和资源消耗。论文因此把 prospective memory 作为独立 evaluation axis，而不是 long context 或 generic retrieval 的附带收益。","locator":"§§4.2–6；Ethics Statement，PDF pp. 7–10"}],"methodNotes":[{"label":"Scenario generation and validation","text":"一个 generator 从 seed 产生固定 7-day schedule，通过 rejection sampling 满足 task/update/lure composition，再由 authors manual review；released validator 检查 scenario invariants，paper 还报告 perfect-play audit。本站在锁定 commit 上运行 validator，得到 0 errors / 0 warnings。","locator":"§§3.1、3.3；Appendix A.2，PDF pp. 3–5、14–16；official data / validator"},{"label":"Query-then-act protocol","text":"每一步 agent 先看到 narrative context；若 clock 或其他 state channel 为 hidden，必须显式 query 才获得该 channel 当前值，然后提交 task selections。Scorer另记 state-query volume，但 task result 与 query count 是不同统计面。","locator":"§3.1；Figure 2；Appendix A.3–A.4，PDF pp. 3–5、16–17"},{"label":"Scoring and aggregation","text":"行为按 hit / late / miss 与 set TP/FP/FN 评分；per-run Set-F1 先计算，再跨八个 models 取 macro，micro 则汇总 TP/FP/FN。update、cross-day、monitoring-required、channel 和 query counts 是诊断维度，不应自动等同于 verified causal mechanism。","locator":"§3.3；Appendix A.4；Tables 2–3，PDF pp. 5、8、16–17"},{"label":"Live versus replay-derived setups","text":"六个 setups 是 live agent runs；majority-vote 与 unanimous-vote 从 hierarchical union outputs deterministic replay 得到。它们继承 union query evidence，metadata duration 为 0，不能当作 fresh model inference runtime。","locator":"§3.2；Appendix A.5；official released run metadata，PDF pp. 4–5、17–21"}],"reportedFindings":["Table 2 的跨模型 macro Set-F1 依次显示 optional heartbeat 65.1、todo ledger 62.8、single baseline 60.0、auto-30m 57.8、auto-60m 56.6、union 45.2、majority 37.2、unanimous 35.3；不存在一个 setup 在所有指标上支配其他方法。（§4.2；Table 2，PDF pp. 7–8）","Optional heartbeat 同时有 70.6 precision、50.0 cross-day hit 与 44.4 update hit；auto-30m 有 489 FP 与 203 queries，union 有 273 FP 与 1661 queries。更多 queries 或更频繁 wake 并不单调提高 Set-F1。（Table 2；§§4.2–4.5，PDF pp. 7–9）","Table 3 中 GPT-5.4 的 optional-heartbeat Set-F1 是 79.1，而 65.1 是 Table 2 的 across-model setup macro；abstract 把 65.1 appositively 归给 GPT-5.4 agent，与两张表的 statistical object 不一致。（Abstract；Tables 2–3，PDF pp. 1、8）","Appendix A.6 的 qualitative failures 包括 missed cross-day task、non-clock monitoring failure、update-sensitive failure 与 false-positive cascade；这些 examples 用来解释 aggregate pattern，不构成独立频率估计。（Appendix A.6；Table 7，PDF pp. 21–22）"],"evidenceLimits":["所有 aggregate conclusions 来自一个 seeded、人工复核的 synthetic week。论文没有报告跨 seed / 跨 week uncertainty、置信区间或 schedule-composition robustness；64 runs 是同一 released scenario 上的 model/setup grid。","benchmark 使用 synthetic records 与 model outputs，没有 human-subject result 或真实 interruption-cost measurement。Ethics Statement 也明确不把高分当成 health、transport 或其他 high-stakes deployment certification。（PDF p. 10）","`proactive_monitoring_required` 与 channel hit 在 scorer 中是 category-conditioned success bucket，不是 verified query provenance。本站可数出 required-channel query 缺失，却不能从 log 证明 agent 没有通过 narrative、prior context、inference 或猜测取得相关信息。","`update_violation` 的 released log 没有 intention-version / target binding。27 个 accepted-late current-state co-occurrences 是精确 scorer event；其中多少反映 agent 真的选择 current target，语义上只能给出 0–27 bounds。","Scorer 的 positional row contract 能被 synthetic reversal 触发；锁定的 64 logs 恰好全部 identity-valid，不能据此保证未来 writer、replay tool 或不同 revision 不会生成 malformed order。","PDF preflight 没有 pypdf 依赖，故只标 advisory unavailable。22-page count、page breaks 与关键表页已由独立 CLI 与 render inspection 交叉核对，但这不等同于该 preflight 工具的 PASS。"],"sourceTensions":[{"label":"65.1% 的 statistical object 在 abstract 与 tables 间漂移","observation":"Abstract 把 best method 描述为 GPT-5.4 agent 并给出 65.1%；§4.2 / Table 2 把 65.1 定义为 optional-heartbeat 跨八模型 macro，Table 3 的 GPT-5.4 optional-heartbeat cell 则是 79.1。","implication":"65.1 本身可由 released logs 重建，但引用时必须说清它是 setup-level across-model macro，不能写成单个 GPT-5.4 run/model result。","locators":["Abstract，PDF p. 1","§4.2；Tables 2–3，PDF pp. 7–8","public audit raw/decision.json"]},{"label":"Monitoring 名称强于 scorer 可验证对象","observation":"Appendix A.4 把 proactive-monitoring-required 定义为需要 hidden-state monitoring 的 task category，query counts 另列；official scorer 的 category/channel hit buckets只看 task 分类与 final result，不要求 completion window 内存在该 channel query。","implication":"该 hit rate 可以评价需要 monitoring 的任务是否做对，却不能单独证明 monitoring action 曾发生；行为成功与 observation provenance 应分成两个 diagnostics。","locators":["Appendix A.4，PDF pp. 16–17","official sim/pm_bench.py:2206-2250, 2522-2581","public audit raw/official_probes.json"]},{"label":"Stale-version 语义与 updated/off-due 实现不同","observation":"Appendix A.4 把 update violation 描述为 update 后仍作用于 stale version；official scorer 却在 updated task 被选中且不在 exact due set 时递增，即使 current mutable state 已把同一 action 接受为 late。","implication":"update_violation 不能直接当作 stale-intention count。若要做 version semantics，需要 action 明确绑定 target/version，并把 current-late 与 retired-target selection 分开。","locators":["Appendix A.4，PDF p. 17","official sim/pm_bench.py:2492-2518, 2569-2581","public audit raw/update_violation_findings.jsonl"]}],"editorialInferences":[{"label":"Prospective memory is a control contract","text":"一个 memory architecture 只有在 cue admission、wake policy、active intention version、action timing 与 suppression 都可审计时，才真正拥有 prospective-memory behavior；retrieval success 只是其中一环。","boundary":"这是把论文 task decomposition 映射到 agent architecture 的 editorial synthesis，不是论文验证过的 production design，也不说明这些责任必须由独立服务实现。"},{"label":"Action success and observation provenance need separate metrics","text":"对 hidden-channel task，应该同时保留 category-conditioned task success 与 query-conditioned verified-observation diagnostic；前者容纳 inference / lucky action，后者回答实际 evidence path，任何一项都不应吞掉另一项。","boundary":"public audit 证明当前 scorer 不用 query 条件化 hit bucket；它没有证明没有 query 就一定不合理，也没有定义唯一正确 observation window。"},{"label":"Intention identity must survive updates","text":"cancel / override / reschedule 之后，只传 task_id 会把 current 与 retired intention collapse 到同一 mutable slot。versioned target identity 应成为 action schema 的一等字段，scorer 才能区分 current-late、stale-target 与无效重放。","boundary":"这是由 paper semantics 与 scorer mismatch 推出的 repair direction。released rows 不含 version/target，故本站没有把 27 个 co-occurrences 逐条判定为 agent intent。"},{"label":"More monitoring is not free reliability","text":"wake frequency、state-query volume、false-positive budget 与 interruption cost 应作为共同 control surface，而不是先最大化 monitoring 再把副作用留给 deployment。optional heartbeat 的 operating point 值得研究，不能被读成一种 scaffold 已普遍胜出。","boundary":"论文报告同一 synthetic week 上的 precision/recall/query tradeoff；没有跨 seed、真实 user cost、calibration curve 或 high-stakes deployment evidence。"}],"openProtocols":[{"title":"Multi-week prospective-memory contract protocol","status":"proposed-not-run","question":"scaffold ranking、verified monitoring gap、update-version taxonomy 与 false-positive cost 在不同 seed、schedule density、channel visibility 和 update mix 下是否稳定？","method":"冻结 generator/source revision 后生成多个 validator-clean weeks；为每个 task/action 加 explicit intention-version binding；分别报告 category-conditioned success、query-conditioned observation、current-late、retired-target violation 与 identity rejection，再以 paired seeds 比较 setups。","fixtures":"至少正交改变 time/event ratio、non-clock channel density、cross-day span、cancel/override/reschedule composition、lure density 与 cue ambiguity；保留 original released week 作为 anchor，不使用 private calendar 或真实通信。","controls":"加入 perfect-play、zero-query informed action、zero-query lucky action、wrong-channel query、current-version late、retired-version selection、duplicate/missing/unknown/cross-day step_id、row reversal、live/replay separation 与 query-cost-matched baselines。","measures":"报告 per-week macro/micro Set-F1、precision/recall、verified-observation rate、unverified hidden-task success、current-late、stale-version violations、identity rejection、queries、FP 与 paired-seed uncertainty；不把 replay duration 当 live runtime。","limitations":"这是 proposed-not-run successor，不是本次 64-log audit 的已执行部分。多 synthetic weeks 仍不能替代真实 interruption cost、human oversight 或 deployment safety evidence。"}],"contributions":[{"type":"public-test","title":"Exact scorer-contract probes and 64-log released-corpus audit","byline":"Agent Memory Study editors","date":"2026-08-20","basis":"Paper-facing audit of arXiv:2607.12385v1 and official genglinliu/PMBench commit e1093c470c8981daf522d4ef047a7c3a71e077d7, including the released scenario, scorer, report builder, checked report and all 64 primary logs.","boundary":"This is a deterministic scorer-contract and released-input audit. It makes no model or API call, generates no new trajectory, estimates no population frequency, does not recover agent intention, and does not claim that headline Set-F1 changes.","method":"Execute paired exact-official scorer fixtures; validate the full official scenario; inventory and rescore the 8 x 8 released grid; independently validate and align every (day, step_id); trace locked scorer locals for all update-violation increments; reconstruct required-channel query windows; rebuild the official report; assert paper Table 2 aggregates and clean checkout preservation.","environment":"macOS 26.5.2 arm64；Python 3.13.3 standard library plus Git CLI；clean exact official checkout；no third-party Python package, network, model or API call. PDF pypdf preflight was unavailable and is not reported as PASS; page anchors were cross-checked separately.","fixture":"Three paired scorer-level synthetic fixtures test zero/one required-channel query, updated/no-update accepted-late action, and chronological/reversed rows with unchanged step IDs. The validator-clean whole-scenario fixture is the released 7-day/80-step week and its 64 primary logs.","controls":"Exact commit/file/log hashes, clean-worktree gates, official validator, complete one-run-per-model/setup grid, live/replay metadata check, paired probes, trace-count equality, independent identity alignment, original-versus-rebuilt report comparison and rounded Table 2 assertions.","rawResult":"All probes and scenario checks passed. The 64-log grid contained 1,062 successful proactive-required completions; 382 lacked the required-channel query on completion and 381 lacked it from due/cue through completion. There were 541 update-violation increments, including 27 accepted-late current-mutable-state co-occurrences. All 64 step identities were valid and realignment changed zero scores. The report rebuild differed only in one stale results-directory path.","derivedResult":"Monitoring/channel hit rates measure successful behavior on task categories, not verified query provenance. Update violation conflates at least an observable scorer-level current-state/late co-occurrence with stale-version wording, while semantic agent intent remains bounded 0–27. Positional replay is an integrity risk but did not affect the locked released logs. Optional heartbeat remains 65.1% across-model macro Set-F1; headline aggregates are unchanged.","limitations":"One synthetic week cannot establish cross-seed stability or real interruption cost. Missing required-channel queries do not reveal all information available to an agent. Released rows lack target/version binding, so 27 co-occurrences cannot be semantically classified. Identity integrity is proven only for the locked 64 logs; replay-derived duration is not live runtime.","links":[{"label":"method, claim verdicts and limitations","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/pmbench-scoring-contract-audit/README.md"},{"label":"reproducible runner","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/pmbench-scoring-contract-audit/audit.py"},{"label":"compact derived result","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/pmbench-scoring-contract-audit/RESULTS.txt"},{"label":"aggregate decision","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/pmbench-scoring-contract-audit/raw/decision.json"},{"label":"exact source and released-log hashes","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/pmbench-scoring-contract-audit/raw/source_manifest.json"}]}],"keywords":["prospective memory","action timing","monitoring cost"],"categories":["前瞻记忆"],"failureSurfaces":["wake-prospective-action"],"sourceUrl":"https://arxiv.org/abs/2607.12385","pdf":{"delivery":"bundled","url":"papers/06-liu-2026-pm-bench.pdf","originalUrl":"https://arxiv.org/pdf/2607.12385v1","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/"},"editorialQuestion":"全部 aggregate conclusions 来自同一个 generated week；这些 scaffold 在不同日程结构、seed 与真实干扰成本下是否稳定？","sourceNote":"已列入 COLM 2026 Accepted Papers；arXiv author comment 标注 conference publication。公开 arXiv 仍为 v1（2026-07-14）；截至 2026-08-14，atlas 暂不记录 proceedings DOI。"},{"number":7,"id":"mistake-notebook-learning","kind":"paper","title":"Mistake notebook learning: Batch-clustered failures for training-free agent adaptation","authors":["Xuanbo Su","Yingfang Zhang","Hao Luo","Xiaoteng Liu","Leo Huang"],"shortAuthor":"Su 等","year":2026,"doi":"10.18653/v1/2026.findings-acl.719","noteDepth":"worked","readingScope":"完整读了 ACL 2026 Findings final 的 Abstract、§§1–6、Limitations、Appendices A–D、主要 tables / figures，共 17 个 physical PDF pages；references 只用于 lineage 定位。另检查 exact current official source commit dc7de755522ad58864c62b74ab8e9959c01b7f23 的 trainer、evaluator、knowledge base、LLM client 与 example caller paths；该 untagged revision 没有被证明是 paper-production source。当前 note 不把 source inspection、已执行的 synthetic contract audit 或 paper-reported benchmark 结果混成同一证据层。","intro":"MNL 先按 subject 聚类一批失败，再把共享错误模式压缩成 structured guidance；真正需要审计的不是“会不会写笔记”，而是谁进入 proposal、谁被重新比较，以及一个 net-positive batch 究竟授权了多强的 promotion claim。","keyPoints":["Tuning Model 使用 retrieved guidance 执行任务，Tuner Model 对整个 batch 先做 subject mapping，再只从 failure subsets 提炼 guidance；两者可以同模，也可由强模型向弱模型蒸馏。（§§3.1–3.3；Algorithm 1）","每条 memory 以 subject、五部分 corrective guidance 与 subject embedding 组成；相似度超过 threshold 时论文声称 fuse into existing node，否则 append。（Appendices B.1–B.3）","Eq. 5 把同一 proposal batch 中每个 item 的 updated reward 与 baseline reward 做符号比较，只有 wins − regressions > 0 才接受；tie 为零贡献，且 gate 没有 held-out 或 per-item non-regression 合同。（§3.3；Algorithm 1）","单 epoch 的 KaggleDBQA test accuracy 为 28.1%，epoch 2 的 train accuracy 升至 62.1% 而 test 降至 23.2%；论文据此承认 cross-epoch overfitting，并采用 single epoch。（§4.3；Figure 4）"],"keywords":["failure learning","memory promotion","rollback","cohort conservation","batch-level abstraction"],"categories":["可靠性","持续学习"],"failureSurfaces":["write-consolidation","retrieval-active-context","abstraction-experience"],"sourceUrl":"https://aclanthology.org/2026.findings-acl.719/","pdf":{"delivery":"bundled","url":"papers/07-su-2026-mistake-notebook-learning.pdf","originalUrl":"https://aclanthology.org/2026.findings-acl.719.pdf","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/"},"editorialQuestion":"如果 promotion 只看 proposal-batch 的 surviving pairs，怎样同时保全原 cohort、coverage、subgroup harm 与 held-out generalization，避免一个绿色 aggregate 吞掉未被比较的 item？","sourceNote":"本站精读 authority 是 ACL Anthology final proceedings PDF（DOI 10.18653/v1/2026.findings-acl.719）。另行检查的 official repo current commit dc7de755522ad58864c62b74ab8e9959c01b7f23 未打 tag，也没有 provenance 把它绑定为论文出表 revision；current-source observation 不能反向改写 paper claim。","whyRead":"这篇最有价值的地方不是再证明一次 external memory 可以提升分数，而是把 mutation authority 写成一个可计算 gate：先生成 candidate，再用同一 batch 验收，失败就 rollback。也正因为 gate 足够具体，读者可以追问它的 population、denominator 与 lifecycle：某个 item 没形成 updated pair 时是否仍属于 B？一个 aggregate win 能否遮住 subgroup loss？proposal batch 通过后谁负责 held-out decline？这让“持续学习”从漂亮叙事变成一组可以逐层审计的 admission contracts。","argumentMap":[{"step":"01 · 把 adaptation 从 weights 移到 external memory","claim":"MNL 用 Tuning Model 执行、Tuner Model 反思与更新，把优化对象写成经 retrieval 进入 prompt 的 memory M；self-tuning 与 cross-model tuning 是同一框架的两种角色配置。","locator":"§§1、3.1–3.2；Equations 1–2，physical PDF pp. 1–3（proceedings pp. 14629–14631）"},{"step":"02 · 先画全 batch 的 subject map，再从失败组抽象","claim":"系统先对完整 batch 做 subject clustering，再在每个 subject 内只聚合 failed trajectories，提炼五部分 structured guidance，并按 similarity 决定 merge 或 append；目标是让 shared pattern 取代逐条 failure log。","locator":"§3.3；Equations 3–4；Algorithm 1；Appendices B.1–B.3，physical PDF pp. 3–5、12（proceedings pp. 14631–14633、14640）"},{"step":"03 · 用 proposal-batch net delta 决定 mutation authority","claim":"candidate memory 必须对同一 B 个 query 重新生成；Eq. 5 逐项比较 updated 与 baseline reward，只有 ΔB = wins − regressions 严格大于零才 commit，否则保留旧 M。这个合同是 aggregate、batch-local 且 verifier-relative。","locator":"§3.3；Equation 5；Algorithm 1 lines 23–34，physical PDF pp. 4–5（proceedings pp. 14632–14633）"},{"step":"04 · 实验支持一种 operating point，却没有给全局单调性","claim":"六个 benchmarks、batch / if-accept ablations 与 memory-length comparisons 支持 compact guidance 的可行性；但 cross-epoch test decline、Mimo-v2 no-think 反例与 Limitations 同时限定了“stability”只能在具体 verifier、batch 与 setup 内理解。","locator":"§§4–5；Tables 1–8；Figures 3–4；Limitations，physical PDF pp. 5–9（proceedings pp. 14633–14637）"}],"methodNotes":[{"label":"Two model roles and two feedback regimes","text":"Tuning Model 负责生成，Tuner Model 负责 subject clustering、failure analysis、guidance extraction 与 open-ended judge；两者可共享 base model，也可由 stronger tuner 蒸馏 weaker tuning model。Math / Text-to-SQL 使用 supervised reward，agentic tasks 使用 proxy LLM judge 的 binary signal。","locator":"§§3.1–3.3；§4.1；Appendix B.3，physical PDF pp. 2–5、12"},{"label":"Structured memory and retrieval","text":"JSONL entry 包含 subject、embedding 与五个 mandatory guidance components：corrected examples、correct approach、mistake summary、generalizable strategy、anti-patterns。Query 和 subject 使用同一 embedding model，以 threshold + top-k 进入 active context，并附 applicability assessment。","locator":"Appendices B.1–B.3、C.1–C.4，physical PDF pp. 12–15"},{"label":"Proposal and acceptance population","text":"Algorithm 1 先在完整 batch 上生成 baseline、构造 candidate，再对同一 B 个 query 形成 Rnew；Eq. 5 只比较每项 reward 的方向，不保留改善幅度。论文没有定义 updated generation 缺失、held-out decline 或 subgroup veto。","locator":"§3.3；Equation 5；Algorithm 1，physical PDF pp. 3–5"},{"label":"Experimental objects","text":"实验横跨 AIME 2024/2025、GSM8K、KaggleDBQA、Spider、Mind2Web 与 AppWorld；指标包括 Pass@32、execution accuracy、Task Success 与 Step Accuracy，并同时报告 memory entries 和 guidance tokens。本站没有重跑这些 datasets、models、judges 或 service-dependent agent loops。","locator":"§§4.1–4.3；Tables 1–8；Appendix D，physical PDF pp. 5–8、16–17"}],"reportedFindings":["Table 1 中，Qwen3-8B 的 MNL 在 AIME 2024/2025 报告 33%/30%，KaggleDBQA 报告 28%；DeepSeek-V3.2-Exp 的 KaggleDBQA 从 vanilla 24% 报告为 MNL 64%。这些是 paper-reported point estimates，不是本站复算。（§4.2；Table 1，physical PDF pp. 5–6）","Table 3 的 Qwen3-8B ablation 从 Single-Level 到 Batch Clustering，再到 Full (+ If-Accept)，在 GSM8K、KaggleDBQA 与 Mind2Web Step Accuracy 上报告更高结果与更短 memory；组件顺序同时改变，不能把最终差值全归给单一 gate。（§4.3；Table 3，physical PDF p. 7）","Figure 4 报告 KaggleDBQA epoch 1 test accuracy 28.1%、50 entries；epoch 2 train accuracy 升至 62.1%，test accuracy 降至 23.2%。作者将其解释为 cross-epoch overfitting，而不是持续单调改善。（§4.3；Figure 4，physical PDF p. 8）","Table 6 的 Mimo-v2-w/o-think 是明确反例：vanilla TS/SA 为 8.75/41.12，MNL 为 8.08/40.71；同表的 think-enabled variant 则从 10.77/47.63 升至 11.09/48.51。（§4.2；Table 6，physical PDF p. 7）"],"evidenceLimits":["Eq. 5 的 gate 使用提出 candidate 的同一个 batch，没有 independent promotion set、held-out veto 或 subgroup constraint；一个 accepted update 可以包含 losing item，并且不能推出 test distribution 单调改善。","Self-Evolution 依赖 Tuner Model 充当 LLM judge。论文 Limitations 明确承认 biased / inconsistent verifier 可以把系统性错误传播进 memory，batch-level accept-if-improves 不能消除这一点。（physical PDF p. 9）","Appendix A 的 decision-stability proof sketch 假设同一 semantic cluster 内 noise independent，并调用 sub-Gaussian concentration；论文没有实证证明语义相似样本的 verifier error 独立、同分布或满足该 tail condition。（physical PDF pp. 11–12）","主表提供 point estimates，但没有给本站可据以复算的 complete per-run outputs、confidence intervals 或统一 request / model snapshot receipt。不同 benchmark 的 split、metric、judge 与 model regime 也不构成同一 statistical population。","Exact current official source 是 untagged commit dc7de755522ad58864c62b74ab8e9959c01b7f23；没有证据证明它生成 ACL final tables，故 source behavior 与 paper-time execution必须分层。","当前 source inspection 与本次 public synthetic audit都不调用模型、API 或 benchmark data，不能估计 partial failure、duplicate subject、coverage loss 的真实频率，也不能改变任何 paper headline score。"],"sourceTensions":[{"label":"“Prevents regressions” 强于实际 gate","observation":"Introduction 把 conservative rule 概括为 prevents regressions；Eq. 5 却允许 wins 多于 losses 时接受含有 regression 的 batch，Figure 4 又报告 epoch 2 test decline，Table 6 还出现 Mimo-v2-w/o-think 低于 vanilla。","implication":"可验证对象应写成 proposal-batch net improvement under one reward function，而不是 per-item、subgroup、held-out 或 continual-learning non-regression。","locators":["Introduction，physical PDF p. 1","§3.3；Equation 5，physical PDF p. 4","§§4.2–4.3；Table 6；Figure 4，physical PDF pp. 7–8"]},{"label":"Paper 的 full B 与 current source 的 survivor subset","observation":"Algorithm 1 对 i=1…B 重新生成并计算 ΔB；current trainer 会在 baseline generation、updated retrieval prompt 与 updated generation 三个 stage 分别删除 response 为 None、prompt 为空或 response 为 None 的 items，只把 survivors 交给 evaluator。全部 updated 缺失时会 rollback，但 partial 缺失可以缩小 candidate-construction 或 comparison population。","implication":"任一 original ID 没有完整 baseline/updated pair 时，paper-side ΔB 应记 incomplete / undefined；source-side survivor decision、stage ledger 与 missing-as-failure sensitivity必须分别报告，不能无声宣称 full batch improved。","locators":["Algorithm 1，physical PDF p. 5","exact current source trainer.py:430–451, 482–533, 556–569"]},{"label":"Current default guidance schema 短于 paper / DBQA custom schema","observation":"Current `PromptTuner` class default只要求 2–3 sentences，没有强制 paper Appendix B.2 的 corrected examples、correct approach、mistake summary、generalizable strategy 与 anti-patterns；同一 commit 的 DBQA example另行定义并注入包含这五部分的 custom template。","implication":"这是 public/default API 与 experiment-style caller contract 的张力，不能反向宣称 paper 的 DBQA setup 使用短 default；对实际 prose quality 的判断仍需 model execution，本次只做 literal source comparison。","locators":["Appendix B.2，physical PDF p. 12","exact current source trainer.py:125–127, 181–191","exact current source example_dbqa.py:139–173, 275–295"]},{"label":"Fuse existing node 与 append duplicate 的实现张力","observation":"Appendix B.3 说 similarity 超过 threshold 时 new insight fused into existing node；current `update_entry()` 始终以 `overwrite_if_exists=False` append。Exact subject、equal embedding、stable sort、top_k=1 时，旧 entry 可继续先被取回，新 merged guidance 被遮住。","implication":"promotion audit 不只要证明 candidate 被写入，还要绑定 candidate 在 post-update prompt 中实际可达；append count 不能自动证明 refinement 生效。","locators":["Appendix B.3，physical PDF p. 12","exact current source knowledge_base.py:70–105, 279–292","exact current source example top_k configuration"]},{"label":"Periodic evaluation 不是 held-out rollback","observation":"Current trainer 的 periodic / epoch-end eval 只记录 score 并保存 checkpoint；`best_eval_score` 初始化后没有消费，`_load_checkpoint()` 没有 caller。Current DBQA example 还把 train 与 eval variables 指向同一个 train JSONL；这只是 current example static configuration，不能叫 paper held-out split。","implication":"Periodic eval 是 telemetry，不是 promotion authority。它不违反只承诺 proposal batch 的 Eq. 5，但不能被描述成 best-checkpoint 或 held-out monotonic protection。","locators":["exact current source trainer.py:42, 167, 814–823, 929–955","exact current source example_dbqa.py:82–83, 270, 324–327","§4.3；Figure 4，physical PDF p. 8"]}],"editorialInferences":[{"label":"Promotion population is part of the evidence contract","text":"一个 batch gate 的 denominator 不能只是运行时 list 的当前长度；original、baseline-valid、updated-prompt-valid、updated-response-valid 与 evaluated identities都应进入 receipt，任何 shrink 都要带 reason 与 policy。","boundary":"这是由 Algorithm 1 的 full B 与 current-source filters 推出的 audit design，不是论文提出的 logging schema，也不规定 missing 必须计作 loss。"},{"label":"Improvement authority must be layered","text":"proposal-batch net gain、per-item non-regression、subgroup protection、held-out improvement 与 deployment safety是五个不同 gate；前一个通过不能默授权后四个。","boundary":"论文只实现并讨论第一个 gate，且 Limitations承认 verifier 和 lifecycle 风险；本站没有证明哪一组额外 gate 在所有任务上最优。"},{"label":"A promoted memory must be reachable under the reader contract","text":"Mutation receipt 应把 candidate state 与 post-update retrieval / prompt admission绑定；否则“写入成功”可能只是 store-level事实，新 guidance并未成为验收时真正影响生成的 evidence。","boundary":"Exact-subject / equal-embedding / top_k=1 是一个 bounded mechanism case，不代表所有 subject merge、retriever 或部署都会 shadow candidate。"},{"label":"Accuracy needs coverage when execution can disappear","text":"如果 failed generation 可从 eval denominator消失，accuracy 必须与 registered-question coverage一起发布；否则 1/1 与 1/2 会共享同一个表面 score。","boundary":"这是对 current evaluation denominator 的 measurement repair direction，不证明论文表格发生过同类缺失或因此被高估。"}],"openProtocols":[{"title":"Failure-inclusive promotion and held-out lifecycle protocol","status":"proposed-not-run","question":"在 exact caller 与真实 service failure modes 下，cohort attrition、candidate reachability、subgroup loss 与 held-out decline 各自多常见，哪种 admission policy 能在 coverage 与 false rollback 之间形成可接受 operating point？","method":"冻结 paper-time或正式 tagged source、model / endpoint / decoding、dataset split、reward与retriever；为每次 proposal注册 immutable cohort，显式记录每个 stage outcome。并列比较 source survivor gate、abort-on-incomplete与预先声明的 missing policy，再用独立 held-out stream和versioned checkpoint评价 lifecycle。","fixtures":"完整 pairs、baseline failure、partial empty retrieval、partial transport failure、timeout、malformed response、exact-subject merge、equal-rank retrieval、mixed subgroup effects、verifier flip、跨 epoch distribution shift 与 sensitive-trace redaction。","controls":"Full-cohort positive/zero/negative controls；all-missing rollback；candidate actually admitted to prompt；stable item IDs；registered-vs-survivor denominators；verifier disagreement；clean rollback state；checkpoint restore；no private traces in public receipts。","measures":"按 caller path 报告 cohort coverage、source decision、policy sensitivity、per-item / subgroup deltas、candidate retrieval rate、eval coverage、held-out delta、rollback precision / recall 与 unresolved fraction；不把 missing 自动归类成 semantic failure。","limitations":"这是 proposed-not-run successor，需要本次未运行的 model endpoints、datasets 与 paper-time source identity。即使多 seed / 多 split 结果稳定，也不能自动证明 production safety、privacy compliance 或长期 user benefit。"}],"contributions":[{"type":"public-test","title":"Source-bound promotion-cohort and coverage contract audit","byline":"Agent Memory Study editors","date":"2026-08-30","basis":"Paper-facing audit of the 17-page ACL 2026 Findings final and synthetic source-bound execution against the exact clean current official MistakeNotebookLearning commit dc7de755522ad58864c62b74ab8e9959c01b7f23. Three executed modules plus one statically inspected DBQA example are locked by Git blob and SHA-256; no provenance establishes this untagged commit as the paper-production revision. The original eight-case protocol and the two-case delayed-review amendment remain separately identified.","boundary":"This is a deterministic, model-free synthetic contract audit under an original protocol frozen after paper/current-source inspection and a chronology-preserving amendment frozen after delayed review. It is not an MNL benchmark or paper-experiment rerun, model evaluation, paper-score recalculation, source-to-paper reproduction, prevalence or effect estimate, security finding, production test, or real-world non-regression claim. Missing baseline or updated items remain unavailable observations; the separate missing-as-failure calculation is only an audit sensitivity. A net-positive survivor decision does not establish full-cohort, per-item, subgroup, held-out, cross-epoch or deployment improvement. Prompt-provenance misalignment is limited to the current source negative/debug record and is not an admission-arithmetic result.","method":"Reject a wrong or dirty checkout and wrong paper/source digests; dynamically load the exact current PromptTuner, Evaluator and KnowledgeBase methods through narrow standard-library dependency stubs; execute ten fixed promotion batches with ordered stage ledgers and explicit per-item indices/states/rewards; bind accepted and rejected in-memory plus serialized KB states; execute exact-subject equal-embedding top-1, failed-question denominator and source-owned prompt-provenance probes；invoke the exact default-template method and AST-inspect the hash-locked DBQA example without importing it；rederive aggregate decisions; run eight mutation falsifiers and a socket guard; execute the complete amended matrix twice in fresh out-of-tree roots with hash seeds 313 and 727; compare six primary receipts byte-for-byte; then run receipt-only and fresh source-bound checked verification.","environment":"Darwin arm64；CPython 3.13.3 standard library；UTC and C.UTF-8；exact clean official commit dc7de755522ad58864c62b74ab8e9959c01b7f23；17-page ACL final PDF；two fresh external run/output roots；no upstream dependency installation, dataset, model, API, embedding service or AppWorld runtime；zero guarded Python socket attempts，while raw syscall / OS-level network was not instrumented。","fixture":"37 AMS-authored synthetic batch items across complete positive, balanced, all-tie, partial baseline-None, partial updated-None, suffix empty-prompt, middle empty-prompt prompt-provenance, all-empty-prompt, all-None-response and mixed-subgroup cases；one exact-subject/equal-embedding knowledge-base probe；two enrolled evaluation questions with one all-failed question；one static default/custom-template and current DBQA path probe；stable original, baseline-valid, prompt-valid, response-valid and evaluated identity ledgers plus explicit per-item receipts。","controls":"Exact paper, commit, tree, Git-blob and source-file hashes；repo-relative runtime module binding；clean checkout and allowlisted bytes before/after；complete-cohort Eq. 5 sign controls；all-missing rollback controls；rejected logical/serialized prestate equality；accepted exact one-entry delta；per-stage identity conservation；missing-as-failure labeled counterfactual only；eight fail-closed mutations for deleted identity, flipped admission, false observed loss, rejected-state change, enrolled-denominator change, top-1 substitution, relabeled baseline missing stage and hidden prompt-provenance mismatch；Python-socket-attempt guard；public-path/secret/upstream-source scan；two-run primary-receipt byte comparison；receipt-only and source-bound verifier separation。","rawResult":"All ten batch cases matched the locked current source. Complete 3-win/1-loss accepted; 2-win/2-loss and all-tie cases rolled back. Partial baseline-None, updated-None and suffix empty-prompt cases each evaluated 2 of 4 enrolled IDs and accepted on two survivor wins; every full-cohort decision remains UNDEFINED_FROM_OBSERVED_RESULTS and each labeled missing-as-failure sensitivity was delta 0. The middle empty-prompt case evaluated 3 of 4, accepted at 2W/1L, and logged the loss with the preceding survivor's baseline prompt rather than its own. Both all-missing controls rolled back. A complete 3W/1L batch accepted despite subgroup B delta -1. Exact update_entry left two same-subject entries and top_k=1 returned the older guidance. Evaluation returned conditional accuracy 1.0 with coverage and unconditional correct/attempted both 0.5. The class default required none of the five named components; the current DBQA custom template contained and injected all five, while its current train/eval variables named one file. All eight mutations were caught; two fresh six-file primary receipt sets were byte-identical; model/API calls and guarded Python socket attempts were zero.","derivedResult":"At the locked current official revision, complete cohorts implement the strict proposal-batch wins > losses sign gate. Current source can shrink membership after baseline generation, updated-prompt retrieval or updated generation and still accept on survivors, so those admissions do not establish a full-enrolled-cohort delta. A middle prompt-filter can also misbind baseline prompt provenance in the source negative/debug record without changing evaluator arithmetic. Net batch acceptance permits a losing item/subgroup. Under the exact bounded subject/equal-embedding/top_k=1 fixture, append semantics leave the older entry first; under the exact eval fixture, an all-failed question disappears from the accuracy denominator unless coverage is reported separately. The short default/rich DBQA custom split and same-file DBQA variables are current-source static contracts, not paper-time or benchmark findings.","limitations":"The runner uses synthetic inputs and narrow import/adaptor stubs, not the upstream environment. It establishes behavior only for exact executed methods, one statically inspected example and the locked revision; it does not show how frequently supported callers produce None, retrieval misses, prompt provenance errors, duplicate exact subjects or all-failed evaluation questions. Bundled ordinary batch wrappers commonly convert request failure to an empty string, so the None seam is not attributed to every example path. The DBQA example is not imported or executed, and its custom template cannot establish paper-production configuration. Equal-embedding top-1 shadowing is a bounded mechanism case, not a universal retriever claim. Evaluation coverage findings do not show that paper tables omitted failures. Same-machine byte identity establishes deterministic repeatability, not independent correctness, cross-platform portability or causal impact.","links":[{"label":"method, results and claim ceiling","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/README.md"},{"label":"frozen pre-execution protocol","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/PROTOCOL.md"},{"label":"delayed-review amendment and disposition","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/REVIEW-AMENDMENT.md"},{"label":"source-bound deterministic runner","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/audit.py"},{"label":"checked receipt and source-bound verifier","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/verify_checked.py"},{"label":"frozen synthetic cases","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/raw/cases.json"},{"label":"exact source-executed case receipts","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/raw/run_results.jsonl"},{"label":"bounded aggregate decision","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/raw/decision.json"},{"label":"paper and exact current source manifest","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/raw/source_manifest.json"},{"label":"mutation falsifier receipts","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/raw/mutation_controls.json"},{"label":"two-run comparison receipt","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/mnl-promotion-cohort-audit/raw/comparison.json"}]}]},{"number":8,"id":"coala-cognitive-architecture","kind":"paper","title":"Cognitive architectures for language agents","authors":["Theodore R. Sumers","Shunyu Yao","Karthik Narasimhan","Thomas L. Griffiths"],"shortAuthor":"Sumers 等","year":2024,"doi":null,"noteDepth":"skim","readingScope":"Abstract、§3–§4、§6–§8；case studies 仅用于理解框架，未逐个通读。","intro":"用 memory modules、structured action space 与 repeated decision cycle 为 language agent 提供一套组件语言。","keyPoints":["CoALA 把 agent 拆成 memory modules、structured action space 与 repeated decision cycle；external actions 负责 grounding，internal actions 包括 retrieval、reasoning 与 learning。（§4）","memory 分为 working、episodic、semantic 与 procedural；working memory 是跨多次 LLM call 持续存在的数据结构，而非单个 prompt。（§4.1）","retrieval 从长期记忆读入 working memory，reasoning 在其中读写，learning 写回长期记忆；修改 procedural memory 被视为更高风险。（§4.3–§4.5）"],"keywords":["cognitive architecture","memory modules","agent actions"],"categories":["记忆架构"],"failureSurfaces":["retrieval-active-context","abstraction-experience"],"sourceUrl":"https://arxiv.org/abs/2309.02427","pdf":{"delivery":"bundled","url":"papers/08-sumers-2024-cognitive-architectures.pdf","originalUrl":"https://arxiv.org/pdf/2309.02427v3","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/"},"editorialQuestion":"框架主要用 controllability 与 coupling 划 internal/external boundary；如何加入 provenance、authority 与 reversibility，避免“可写”被误当成“有权写”？","sourceNote":""},{"number":9,"id":"storage-to-experience","kind":"paper","title":"From storage to experience: a survey on the evolution of LLM agent memory mechanisms","authors":["Jinghao Luo","Yuchen Tian","Chuxue Cao","Ziyang Luo","Hongzhan Lin","Kaixin Li","Chuyi Kong","Ruichao Yang","Jing Ma"],"shortAuthor":"Luo 等","year":2026,"doi":"10.18653/v1/2026.findings-acl.2069","noteDepth":"skim","readingScope":"Abstract、§2–§7、Limitations；未通读附录中的 taxonomy、datasets 与 benchmark tables。","intro":"按信息抽象与 cognitive processing 程度，把 agent memory 组织为 Storage、Reflection 与 Experience 三类机制。","keyPoints":["Storage 尽量保留 trajectory；Reflection 对单条 trajectory 评价或纠正；Experience 从相似 trajectory group 归纳可跨场景使用的 schema 或 policy prior。（§2.2）","Experience 又分 explicit、implicit、hybrid：可以表现为自然语言 policy、executable skill、模型参数，或显式积累与参数内化的组合。（§4）","survey 把 active retrieval controller、working-memory organization 与 Experience-stage benchmark 列为开放方向，并承认没有跨方法 quantitative comparison。（§6；Limitations）"],"keywords":["memory taxonomy","reflection","experience abstraction"],"categories":["记忆架构"],"failureSurfaces":["abstraction-experience"],"sourceUrl":"https://aclanthology.org/2026.findings-acl.2069/","pdf":{"delivery":"bundled","url":"papers/09-luo-2026-storage-to-experience.pdf","originalUrl":"https://aclanthology.org/2026.findings-acl.2069.pdf","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/"},"editorialQuestion":"跨 trajectory 的 universal rule 如果失去到具体来源的可追溯路径，来源被纠正后要怎样让高层抽象同步失效？","sourceNote":""},{"number":10,"id":"continual-learning-experience-reuse","kind":"paper","title":"When continual learning moves to memory: a study of experience reuse in LLM agents","authors":["Qisheng Hu","Quanyu Long","Wenya Wang"],"shortAuthor":"Hu 等","year":2026,"doi":null,"noteDepth":"skim","readingScope":"Abstract、§2–§6、Appendix A/C/D 相关段落；未完整读案例附录。","intro":"把 frozen-backbone agent 的 continual learning 改写成检索竞争问题：经验没有被参数覆盖，却可能被相似条目挤出有限 context。","keyPoints":["框架用经验表示 v 与 storage granularity / retrieval frequency 等 key design choices，配合 FWT、BWT 分开观察 transfer 与 forgetting。（§2.2–§2.3）","跨任务实验里 raw trajectory 出现负向 transfer，而 abstract insight 在两个环境中为正；噪声尤其伤害原本不会做的 hard cases。（§3.1–§3.2）","更细 storage 或更频繁 retrieval 没有统一优势；一个条件下 88.5% 请求取回同一 item，coverage 仅 5.4%，旧经验仍在 store 中却可能因 retrieval dilution 而不可用。（§4；Appendix D）"],"keywords":["continual learning","experience retrieval","retrieval dilution"],"categories":["可靠性","持续学习"],"failureSurfaces":["retrieval-active-context","abstraction-experience"],"sourceUrl":"https://arxiv.org/abs/2604.27003","pdf":{"delivery":"bundled","url":"papers/10-hu-2026-continual-learning-to-memory.pdf","originalUrl":"https://arxiv.org/pdf/2604.27003v1","license":"CC BY-NC-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-nc-sa/4.0/"},"editorialQuestion":"结论只来自两个 environment、各一个 task pair、单一 BM25 retriever 与两次 runs；retrieval dilution 能否跨 retriever 和任务结构复现？","sourceNote":""},{"number":11,"id":"agentic-memory","kind":"paper","title":"Agentic memory: Learning unified long-term and short-term memory management for large language model agents","authors":["Yi Yu","Liuyi Yao","Yuexiang Xie","Qingquan Tan","Jiaqi Feng","Yaliang Li","Libing Wu"],"shortAuthor":"Yu 等","year":2026,"doi":"10.18653/v1/2026.acl-long.981","noteDepth":"skim","readingScope":"Abstract、§3–§5、Limitations、主要 tables/figures；未通读附录，也未复核训练实现。","intro":"把 active context 与 persistent store 放进统一状态和 action space，让一个 policy 同时决定语言生成与 STM/LTM 操作。","keyPoints":["显式 memory tools 包括 LTM 的 ADD、UPDATE、DELETE，以及 STM 的 RETRIEVE、SUMMARY、FILTER。（§3.1–§3.2）","训练 trajectory 先决定哪些信息进入 LTM，再 reset active context 并加入 distractors 训练 STM，最后完成必须联合使用两者的任务，以减少 residual-context shortcut。（§3.1；§3.3）","Step-wise GRPO 把同一个 terminal advantage 广播给整条 trajectory 的先前 memory 与 reasoning actions，因此提供早期训练信号，却不区分每次具体 mutation 的独立贡献。（§3.4）"],"keywords":["memory policy","reinforcement learning","STM and LTM"],"categories":["记忆架构"],"failureSurfaces":["write-consolidation","retrieval-active-context"],"sourceUrl":"https://aclanthology.org/2026.acl-long.981/","pdf":{"delivery":"bundled","url":"papers/11-yu-2026-agentic-memory.pdf","originalUrl":"https://aclanthology.org/2026.acl-long.981.pdf","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/"},"editorialQuestion":"在关键质量指标依赖 LLM judge、实验尚未覆盖长期真实用户互动的情况下，怎样识别某一次具体 memory mutation 是帮助还是伤害了结果？","sourceNote":""},{"number":12,"id":"midca-dual-cycle","kind":"paper","title":"MIDCA: a metacognitive, integrated dual-cycle architecture for self-regulated autonomy","authors":["Michael Cox","Zohreh Alavi","Dustin Dannenhauer","Vahid Eyorokon","Hector Munoz-Avila","Don Perlis"],"shortAuthor":"Cox 等","year":2016,"doi":"10.1609/aaai.v30i1.9886","noteDepth":"skim","readingScope":"Abstract、goal reasoning、formal representation、object/meta-level performance 与 Conclusion；related work 仅略读。","intro":"把相同的 action–perception cycle 放在 object 与 meta 两层，用 phase trace 让系统观察并调整自己的认知过程。","keyPoints":["每层都包含 Intend、Plan、Act 与 Perceive、Interpret、Evaluate；object-level goal 改变环境，meta-level goal 改变 object-level cognition。（Introduction；Figures 1–2）","metacognitive interface 接收各 phase 累积的 trace；Monitor 选择 subtrace，Interpret 在上面检测 expectation 与结果的 discrepancy。（p. 3714）","object-level 实验中 explanation-driven goal generation 在随机 fire event 下保持较高 tower score；meta-level 评价则只是 planner impasse 后替换 planner 的一个 scenario。（pp. 3715–3716）"],"keywords":["metacognition","goal reasoning","execution trace"],"categories":["记忆架构"],"failureSurfaces":["metacognitive-control"],"sourceUrl":"https://ojs.aaai.org/index.php/AAAI/article/view/9886","pdf":{"delivery":"official","url":"https://ojs.aaai.org/index.php/AAAI/article/view/9886/9745"},"editorialQuestion":"论文仍未解决何时运行 metacognitive layer、监控哪些 expectation、如何裁剪长 trace；怎样避免每个 discrepancy 都自动扩张成新 goal？","sourceNote":""},{"number":13,"id":"truth-maintenance-system","kind":"paper","title":"A truth maintenance system","authors":["Jon Doyle"],"shortAuthor":"Doyle","year":1979,"doi":"10.1016/0004-3702(79)90008-0","noteDepth":"read","readingScope":"完整读了 MIT DSpace 的 AIM-521 official scan：扉页、abstract、§§1–10、References 与 Figures 1–3，共 45 个 PDF pages；下列定位指 memo 内部页码。References 只用于 lineage 定位，未逐篇 close-read；另核对 journal metadata，但未取得期刊 full text 做逐行版本比较，也未复现原 Lisp implementation 或追读后来的 JTMS / ATMS。","intro":"Doyle 维护的不是命题在世界中的真伪，而是 program 当前是否拥有可接受的理由。node 的 in/out 是 support status；当前 explanation 还依赖被选中的 well-founded SL justification、失效 witness 与 change 后真正扫描到的 repercussions。（§§1–3，AIM-521 pp. 3–18）","whyRead":"这篇值得深读，不是因为 1979 年已经解决了现代 agent memory，而是因为它把“记住”改写成 maintain reasons under change：保存 source、展示 provenance、传播失效、处理 contradiction 与选择 revision 是五种不同能力。论文也没有掩饰自己的裂缝——positive cycle 不能自举、negative loop 可能多解或无解、blind backtracking 缺少选择依据、summary 与 control 都会把额外 policy 带进 belief revision。","keyPoints":["Doyle 对 support status 的局部定义是：至少一条 justification 当前有效则 node 为 in，否则为 out；实现又从有效 SL 中选一条 well-founded supporting justification。P 与 ¬P 是两个 binary-status nodes，neither / only P / only ¬P / both 是联合状态，不是单个 node 的 four-valued truth。（§§2.1、2.4，AIM-521 pp. 9–12）","SL 由 inlist 全部 in、outlist 全部 out 决定 validity；CP 则表达一个 hypothetical situation 下 consequent 应为 in。原实现只在当前 statuses 恰好允许时 opportunistically 识别 CP，再由 FIS 生成 creation-time dependency-equivalent 的 SL。（§§2.3–2.5；§9，AIM-521 pp. 11–14、36）","change propagation 使用 supporting-nodes、antecedents、foundations、consequences 与 repercussions 区分 current reason、失效 witness 与 affected region。Step 5 暂把 nil 当 out、只检查 SL，并可能从多个 admissible assignments 中装入一个。（§§2.4、3.2，AIM-521 pp. 12–13、16–18）","contradiction 必须由 problem solver 标记；backtracker 找 maximal assumptions、创建 nogood，再选择 culprit 与一个 outlist node。原版本随机选择，Doyle 明说这种 blind search 除最简单问题外不够。（§4，AIM-521 pp. 20–22）"],"argumentMap":[{"step":"01 · 先把 belief 与 truth 分开","claim":"TMS 记录的是 program 当前有无 acceptable reason，而不是独立真值。out 只表示没有当前支持，不是反证；相互否定的 statements 也必须分别建 node。","locator":"§1.1；§2.1，AIM-521 pp. 3–6、9–10"},{"step":"02 · 再把 current reason 变成可追踪 dependency","claim":"每个 in node 选择一条 well-founded SL 作为 current support；OUT node 则从每条 invalid justification 取一个 falsifying witness。向下的 foundations 与向上的 repercussions 让 support change 可以定向传播。","locator":"§§2.3–2.4，AIM-521 pp. 11–13"},{"step":"03 · 用 revision 暴露 circularity 与 choice","claim":"affected region 会被临时清空并重新求 support；positive cycle 没有外部 foundation 时不能自举，non-monotonic cycles 却可能有多个 assignments 或根本无解。形式依赖能列出 revision candidates，却不能替 problem solver 决定牺牲谁。","locator":"§§3.1–3.2；§4，AIM-521 pp. 14–22"},{"step":"04 · 最后把 explanation、dialectic 与 control 接回 reasoning","claim":"CP/FIS 与提议的 SUM 可以把 argument 分层或 generalize；§6 让 argument steps 本身可被挑战，§7 镜像别人的 belief space，§8 则明确把 alternative ordering 与 selector 写进 belief revision 的 control surface。","locator":"§§5–8，AIM-521 pp. 23–35"}],"methodNotes":[{"label":"SL validity 与 current support","text":"一个 node 可以有多条 justifications，但 current explanation 使用一条被选中的 well-founded SL。对 in node，所选 SL 的 inlist / outlist 是 antecedents；对 out node，supporting-nodes 从每条 invalid justification 中各取一个 falsifying witness，而 out node 没有 antecedents。","locator":"§§2.3–2.4，AIM-521 pp. 11–13"},{"label":"CP / FIS approximation","text":"CP 的定义针对 hypothetical statuses；一般验证可能递归触发更多 truth maintenance，因此实现采用 opportunistic approximation：在 CP 当前可见为 valid 时，从 consequent 的 well-founded argument 中减去 hypotheses 及其 repercussions，生成易检查的 SL。","locator":"§2.5；§3.3；§9，AIM-521 pp. 13–14、19–20、36"},{"label":"Incremental revision procedure","text":"新增有效 justification 后，系统收集 changed node 与 repercussions、标成 nil，再先恢复外部 well-founded support、后处理 circular region。Step 5 把尚未分配的 nil 暂当 out，只检查 SL；Step 6 才重新检查 CP 与 contradictions。","locator":"§3.2，AIM-521 pp. 16–19"},{"label":"Dependency-directed backtracking","text":"problem solver 先标记 contradiction；TMS 从其 foundations 选 maximal assumptions、创建 nogood，再让一个 selected outlist node 得到支持以使 culprit assumption 失效。outlist node 只在某些解释中是 denial，不由 graph structure 保证为 literal negation。","locator":"§4，AIM-521 pp. 20–22"}],"reportedFindings":["纯 positive circular argument 没有外部 foundation 时不应让 nodes 自举为 in；加入一个 premise 后，同一 positive cycle 才可获得 well-founded support。（§§3.1–3.2，AIM-521 pp. 14–18）","non-monotonic circularity 可能有多个 satisfiable support assignments，也可能出现 F ← not F 这类 unsatisfiable case；原版本为 normal-case efficiency 移除了昂贵检查，后者可能使 procedure loop。（§3.2，AIM-521 pp. 17–18）","dependency-directed backtracker 能定位 maximal assumptions，却随机选择 culprit 与 outlist node；作者将其称为 blind search，并判断除最简单问题外需要 domain / control knowledge。（§4，AIM-521 pp. 20–22）","§9 报告 TMS 被用于 circuit analysis / synthesis、constraint language、symbolic algebra、program understanding 等系统，也列出 CP complexity、multiple support 与 incrementality 等待改进处；论文没有 controlled quantitative evaluation。（§9，AIM-521 pp. 35–36）"],"evidenceLimits":["公开来源是 MIT AIM-521 official scan。journal article 的 metadata 与 scope 已核对，但本站没有取得期刊 full text 做 memo↔journal 逐行比较；定位不冒充 journal pagination。","原 Lisp implementation、incremental execution order、justification retraction 与 performance 没有被复现。本站的 static oracle 只重建一个有界的 SL model boundary，不能代替作者系统。","论文有 worked examples 与 qualitative failure analysis，但没有 controlled experiment、systematic quantitative error analysis、runtime baseline、repeated runs 或 user study；不能据此声称它优于现代 revision mechanisms。","核心 TMS 处理已编码的 nodes 与 dependency forms，不独立验证 truth、source reliability、authority、consent、actor、time 或 provenance。enclosing problem solver 可以另行表示或检查这些性质，但它们不能从 in/out status 自动推出。","§5 的 generalization 证明的是 represented CP 下的 argument-level independence，不是任何压缩或 abstraction boundary 都保持 external semantic validity 的一般结论。"],"sourceTensions":[{"label":"Incremental boundary 会越过自己的 affected region","observation":"主流程通过只检查 changed node 的 repercussions 来避免全库重算；§3.2 与 §9 又明确给出某些 satisfiable circularities 必须改变 repercussions list 外的 node，proper truth maintenance 在这些情形不能保持 incremental。","implication":"affected-set optimization 不能被当成 complete revision semantics；实现需要显式暴露 fallback、重建范围与结果是否依赖局部 approximation。","locators":["§3.2，AIM-521 p. 18","§9，AIM-521 p. 36"]},{"label":"CP 的 hypothetical meaning 与 operational recognition 不相同","observation":"§2.5 把 CP 定义为 hypotheses 状态成立时 consequent 为 in；实现却不一般地切换状态验证，只在 consequent / hypotheses 的 current statuses 恰好满足时识别，再生成创建当下等价的 SL。","implication":"CP/FIS 提供的是明确承认的 opportunistic approximation。后续 derived SL 的 retain、recompute、retire 或 version policy 仍需由 system 另行定义。","locators":["§2.5，AIM-521 pp. 13–14","§9，AIM-521 p. 36"]}],"editorialInferences":[{"label":"Supported is not true or authorized","text":"dependency graph 能说明在给定 nodes 与 rules 下当前为什么支持一句话；它不能独立证明 source 为真、某个 actor 有权让它生效，或这条支持仍满足时间、consent 与 provenance 条件。外围 admission checks 不是可选装饰，而是不同 authority layer。","boundary":"这是由论文明确区分 support 与 truth、并把 external forms 留给 problem solver 推出的 editorial synthesis；论文没有提出现代 provenance / consent governance system。"},{"label":"Abstraction lifecycle is a separate contract","text":"一条 summary 在创建时与 raw argument dependency-equivalent，并不能决定以后 source change 时它应继续存在还是重新计算。lossless projection、recomputable abstraction 与 durable generalization 必须使用不同 lifecycle；最后一种还需要独立 warrant。","boundary":"论文展示 summarization / generalization 并称 derived SL 在创建时等价，但没有运行本站的 retain-versus-recompute fixture，也没有给出通用 future-invalidation contract。"},{"label":"Control belongs to operational revision semantics","text":"alternative ordering、justification creation order、hidden selector 与 explicit choice rule 会从 admissible states 中选出 current belief set，并改变后续 contradiction 与 action path；可解释 dependency 并不使 control 中立。","boundary":"这是对 §8 control patterns 的 architecture-level consequence。它不要求声称 control 改变抽象 admissible model set，也不证明某种 selector 更正确。"},{"label":"Actor scope must be admitted outside raw support evaluation","text":"§7 的 mirroring 会忠实传播系统已经提供的 actor indices 与 inference rules；若一条 rule 被错接到另一个 actor，raw support evaluator 没有 external meaning 可用于发现错误。enclosing schema 可以并且应当拒绝 undeclared cross-actor bridge。","boundary":"这是依据 core / problem-solver boundary 的 editorial test interpretation，不是论文声称已经解决身份隔离，也不表示外围系统无法表达 actor checks。"}],"openProtocols":[{"title":"Revision × support lifecycle protocol","status":"proposed-not-run","question":"一个 revision-pinned support graph 能否在 correction、coexistence、suppression、cycles、summary lifecycle 与 actor scope 下保持可重建、可回滚且不静默扩权？","method":"用 typed public / synthetic events 构造 fixed-support、floating-head、supersession、coexistence、correction 与 suppression histories；分别运行 clean rebuild、incremental update 与 rollback replay，并由第二个独立 enumerator 比较 model set。","fixtures":"至少覆盖两条独立 supports、positive cycle、negative loop、self-negation、retain / recompute / durable-generalization 三类 abstraction、undeclared actor bridge 与 authorized bridge；不使用真实人物、私有数据或 production runtime。","controls":"加入 shuffled lifecycle labels、missing target、corrupted actor index、suppressed source resurfacing、reversed event order、feature-off baseline 与 injected faulty propagation。","measures":"报告 support-status agreement、affected-set precision / recall、stale-support survival、false reactivation、cross-actor leakage、suppression resurfacing、trace completeness 与 rebuild / incremental / rollback equality。","limitations":"这是尚未执行的 successor protocol，不是 Doyle reproduction。只有 public artifact、fault injection、zero hard failures、independent enumeration 与 clean-checkout reproduction 都成立后，才可能把 depth 提升为 worked。"}],"contributions":[{"type":"public-test","title":"Static SL model and abstraction-lifecycle oracle","byline":"Agent Memory Study editors","date":"2026-08-13","basis":"Paper-facing reconstruction of SL validity, finite positive foundation, the circularity boundary, and the core-versus-enclosing-schema distinction described in AIM-521 §§2–4 and §7.","boundary":"This is not Doyle's Lisp implementation or an incremental trace. It does not execute CP/FIS, model OUT-node witness propagation, perform nogood / culprit choice, establish original summary lifecycle behavior, or validate any production system.","method":"Enumerate every IN/OUT assignment for fifteen 1–6 node synthetic graphs; retain support-complete assignments; require every IN node to have a finite positive proof; assert exact model sets; then compare explicit persist-derived-SL and recompute policies and apply separate graph / actor-schema validators.","environment":"macOS 26.5.2 arm64；Python 3.13.3；Python standard library only；no network or model calls.","fixture":"Fifteen labelled small graphs cover default override, static closure, positive / negative cycles, self-negation, a backtracking precondition, paired abstraction lifecycle policies and an actor-scope error; two additional checks reject an undeclared actor bridge and undeclared node reference.","controls":"The abstraction pair holds D / E / X and the raw path fixed while changing only whether the materialized summary SL is retained or retired. Actor scope is tested once with raw evaluation and once with an external declared-bridge validator. Every expected result is an assertion.","rawResult":"All fifteen model assertions and two schema-rejection assertions passed. With X present, the retained-policy graph produced {D,E,X,SUMMARY}; the recompute graph produced {D,E,X}. A misindexed U→V rule derived V:UMBRELLA in the raw evaluator, while the actor schema rejected the same edge. Full stdout is linked.","derivedResult":"The static oracle matches the selected SL / finite-foundation boundaries, but future summary behavior is policy-dependent rather than a demonstrated FIS property. Actor separation likewise belongs to enclosing admission validation rather than raw support semantics.","limitations":"History-free exhaustive enumeration is practical only for tiny graphs. The two negative-loop models are admissible assignments, not observed runs; the meeting fixtures do not implement backtracking; no performance, incremental equivalence or independent second enumerator was tested.","links":[{"label":"method and limitations","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/doyle-tms-static-oracle/README.md"},{"label":"runner","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/doyle-tms-static-oracle/oracle.py"},{"label":"raw stdout","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/doyle-tms-static-oracle/RESULTS.txt"}]}],"keywords":["truth maintenance","justification graph","dependency-directed backtracking"],"categories":["信念修正"],"failureSurfaces":["justification-revision","abstraction-experience"],"sourceUrl":"https://hdl.handle.net/1721.1/5733","pdf":{"delivery":"official","url":"https://dspace.mit.edu/server/api/core/bitstreams/4fdf6aa2-170b-45e6-ae88-8f10d61e1c6d/content"},"editorialQuestion":"如果 support graph 只能维护“给定 reasons 下当前成立”，谁来声明 derived summary 的 retain / recompute / retire policy，又怎样让 source authority、actor scope 与 authorized revision 不被一次形式上有效的 edge 静默替代？","sourceNote":"本站只链接 MIT DSpace 的官方扫描；本地生成的 OCR 衍生版不公开分发。"},{"number":14,"id":"agm-theory-change","kind":"paper","title":"On the logic of theory change: Partial meet contraction and revision functions","authors":["Carlos E. Alchourrón","Peter Gärdenfors","David Makinson"],"shortAuthor":"Alchourrón 等","year":1985,"doi":"10.2307/2274239","noteDepth":"skim","readingScope":"Abstract、§1–§4、§6–§7；未逐行复核全部证明，§5 connectivity 细节未读。","intro":"用 expansion、contraction 与 revision 的形式区分新增、放弃和在冲突后恢复一致性，并刻画哪些操作可由 partial meet 表示。","keyPoints":["contraction 从 deductively closed theory 中放弃命题及维持 closure 所必须一并放弃的内容；Levi identity 把 revision 表成先 contraction 掉新命题的否定，再加入新命题。（§1）","A ⟂ x 是 A 中所有不推出 x 的 maximal subsets；partial meet 由 selection function 选一组 remainders 后取交集，并把 maxichoice 与 full meet 作为极端情况。（§1–§2）","closure、inclusion、vacuity、success、preservation、recovery 六条基本 postulates 与 partial meet contraction 之间给出双向 representation result。（§2）"],"keywords":["belief revision","partial meet contraction","formal logic"],"categories":["信念修正"],"failureSurfaces":["justification-revision"],"sourceUrl":"https://www.cambridge.org/core/journals/journal-of-symbolic-logic/article/on-the-logic-of-theory-change-partial-meet-contraction-and-revision-functions/7ED837BAD5FB6D9A7C77906D73527F9C","pdf":{"delivery":"official","url":"https://www.cambridge.org/core/services/aop-cambridge-core/content/view/7ED837BAD5FB6D9A7C77906D73527F9C/S0022481200032849a.pdf/div-class-title-on-the-logic-of-theory-change-partial-meet-contraction-and-revision-functions-div.pdf","accessNote":"可能需要机构访问"},"editorialQuestion":"selection function 可以在形式上挑选“最佳” remainders，但重要性从何而来？若选择由 opaque model 作出，逻辑 postulates 如何与 provenance 和授权结合？","sourceNote":""},{"number":15,"id":"memory-beyond-recall","kind":"paper","title":"Memory beyond recall: a dual-process cognitive memory system for self-evolving LLM agents","authors":["Tianxiang Fei","Mingyang Song","Mao Zheng","Xiang Yu"],"shortAuthor":"Fei 等","year":2026,"doi":"10.48550/arXiv.2606.09483","noteDepth":"skim","readingScope":"Abstract、§2–§3.5、Conclusion、Limitations、Ethics Statement；未通读 references，也未复核实现。","intro":"用同步的 raw/fact 更新与异步的 schema induction 组成 dual-process memory，并让高层抽象保留到低层 evidence 的路径。","keyPoints":["memory 分为 raw inputs、atomic facts/identity、within-domain schemas/intentions 与 cross-domain core schemas；高层 graph node 通过 evidence reference 回指支持事实。（§2.1）","System 1 在显式 add_memory 时先于 LLM call 持久化 raw input，再决定 ADD、SUPERSEDE 或 UPDATE；SUPERSEDE 保留 predecessor 与双向 revision pointers。（§2.2）","System 2 在 idle/nightly window 先聚类，再归纳 schema、intention 与跨领域 core schema；主要增益集中在 PersonaMem-v2，论文同时承认 transient state 可能被误判为 stable revision。（§2.3–§3.4）"],"keywords":["dual-process memory","schema induction","supersession"],"categories":["记忆架构","持续学习","信念修正"],"failureSurfaces":["state-representation","write-consolidation","abstraction-experience"],"sourceUrl":"https://arxiv.org/abs/2606.09483","pdf":{"delivery":"official","url":"https://arxiv.org/pdf/2606.09483v1"},"editorialQuestion":"cross-domain core schema 的阈值在特定 held-out split 上调整、主要收益也集中于同一 benchmark；它是在稳定追踪变化，还是在生成适配 benchmark 的高层推断？","sourceNote":""},{"number":16,"id":"insightemb-action-intent-retrieval","kind":"paper","title":"InsightEmb: Learning Action-Intent Embeddings for Agentic Insight Retrieval","authors":["Tsz Ting Chung","Jiangnan Li","Jie Zhou","Mo Yu"],"shortAuthor":"Chung 等","year":2026,"doi":"10.48550/arXiv.2608.04761","noteDepth":"read","readingScope":"arXiv v2 的 §1–§7、Limitations、Appendix A–E 及主要表图；references 未逐项读，也未复现代码。","intro":"InsightEmb 把 agentic retrieval 从主题相似改写为 action-intent matching：query 不只是当前一句话，而是 goal、recent actions 与 observation 组成的 situation；相关性取决于一条 insight 能否解除当前 bottleneck、提高预期任务进展。（§3.1，PDF pp. 3–4）","whyRead":"这篇真正推进的不是“换一个 embedding model”，而是把 retrieval relevance 从 aboutness 推向 action consequence：两段文字谈同一个主题，不代表那条 memory 此刻应该进入 context。它同时给出了自己的反例——intent geometry 在结构化 bottleneck 上有效，却会在专名、术语、剂量和精确事实检索上输给 literal similarity。因而最有研究价值的结论是 retrieval lanes 必须按失败代价分工，而不是由一个统一分数吞掉所有 query。","keyPoints":["Situation query：retrieval situation 由 goal、action history 与 current observation 组成；memory 是否 relevant 取决于它是否能解除当前 action bottleneck，而不只是主题相似。（§3.1，PDF pp. 3–4）","Outcome-derived labels：训练把原问题、完整 CoT 与 partial CoT 都作为 anchors；candidate insight 若让同题的一次验证求解优于 no-insight baseline，就被标为 positive，否则为 negative。（§3.3–§3.4；Appendix A–B，PDF pp. 4、13–17）","Cross-domain evaluation：embedding supervision 只来自 MATH，但 ALFWorld、WebShop 与 ScienceWorld 的 insight pools 仍由各目标环境 trajectory 蒸馏，因此 paper 评估的是 supervision transfer，不是 domain-free memory generation。（§4.1–§4.2；Appendix A，PDF pp. 5、13–16）","Counterexample：MedCalcBench 上 literal similarity 明显更强；BM25 candidate generation 加 intent rerank 能部分修复，却仍未超过 Base top-1。这要求 hybrid routing，而不是让 intent embedding 取代 lexical lane。（Appendix E，Table 17，PDF p. 29）"],"argumentMap":[{"step":"01 · 先区分 topic 与 action relevance","claim":"普通 embedding 更接近判断两段文字是否在说同一件事；agent memory 需要判断一条经验是否能改变当前下一步。论文因此把检索对象从文本相似度改成 situation 与 insight 的 action-intent compatibility。","locator":"§1；§3.1，PDF pp. 1–4"},{"step":"02 · 用 downstream improvement 产生监督","claim":"作者不直接人工标 action intent，而是把候选 insight 注入同题求解；优于 no-insight baseline 的 pair 作为 positive，其余作为 negative，再用 InfoNCE 训练 4B Qwen3 embedding model。","locator":"§3.3–§3.4；Appendix A–B，PDF pp. 4、13–17"},{"step":"03 · 把 trajectory 变成更接近当下的 query","claim":"原问题、完整 CoT 与 partial CoT 共同作为 anchors，使同一 task 在不同阶段可以召回不同 insight；动态 retrieval 的目标不只是一次取到 gold，而是随 bottleneck 变化更新 support。","locator":"§3.3；Appendix B–D，PDF pp. 4、16–27"},{"step":"04 · 用 transfer 与反例限定结论","claim":"math-only supervision 在三个 agent environments 上产生收益，说明 action-intent geometry 可以迁移；MedCalcBench 的显著退化又说明精确实体与事实检索仍依赖 literal candidate lane。","locator":"§4；Appendix E，Tables 1、17，PDF pp. 5–8、29"}],"methodNotes":[{"label":"Two-stage contrastive data","text":"Stage 1 的 situation→insight 数据含 11,950 个 contrastive pairs，Stage 2 的 situation→experience 数据含 2,896 个 pairs；两阶段都只来自 MATH 的 counting/probability、number theory 与 geometry，并混合 bundle 与 atomic memory。","locator":"§3.3–§3.4；Appendix A–B，PDF pp. 4、13–17"},{"label":"Label construction","text":"同一道题上的 candidate insight 只进行一次验证求解；相对 no-insight baseline 的 outcome 决定 positive / negative。partial trajectory 直接继承 problem-level label，没有 turn-specific usefulness annotation。","locator":"§3.3；Limitations，PDF pp. 4、9–10"},{"label":"Target-environment memory","text":"ALFWorld、WebShop 与 ScienceWorld 的 insight pools 由各自环境 trajectory 蒸馏。没有在这些环境上训练的是 retriever supervision，而不是完整 evaluation pipeline；因此 cross-domain claim 需要限定为 retrieval geometry transfer。","locator":"§4.1–§4.2；Appendix A，PDF pp. 5、13–16"},{"label":"Dynamic top-1 use","text":"agent 在执行过程中按当前 situation 反复取一条 insight。论文同时报告 task outcome、失败次数、步数与 distinct insights，用来观察动态 retrieval 是否只重复同一条支持。","locator":"§4.2；Appendix C–D，PDF pp. 5–6、18–27"}],"reportedFindings":["动态 top-1 retrieval 中，no-insight baseline 在 ALFWorld、WebShop、ScienceWorld 分别为 52.86、31.03、2.40；InsightEmb bundle 为 60.71、31.74、8.00，atomic 为 59.29、32.05、10.20。（Table 1，PDF p. 6）","普通 embedding 的 bundle retrieval 在 WebShop 降到 18.42，显著低于 no-insight 31.03；InsightEmb 恢复到 31.74，却只比 no-insight 高 0.71。检索到一条主题相关 memory 本身可以伤害 action，避免伤害与产生增益也不是同一件事。（Table 1，PDF p. 6）","SRA-Bench 含 636 个 gold situations 与 26,262 个 distractors；macro Recall@1 从 30.33 升到 31.37，Recall@10 从 54.13 升到 63.03，较明显的收益出现在更大的 candidate budget。（§4.3；Tables 2–3，PDF pp. 7–8）","MedCalcBench 上 Base Recall@1 为 92.73，InsightEmb 为 63.27；两者 Recall@10 均为 98.18。BM25 top-50 后让 InsightEmb rerank，Recall@1 回到 70.91、Recall@5/10 达到 100，但仍未超过 Base top-1。（Appendix E，Table 17，PDF p. 29）","去掉 partial-trajectory anchors 后，按各自最佳 k 计算，ALFWorld 的 Base→InsightEmb gain 约损失 83%，WebShop 约损失 49%。动态检索时 distinct insights 从约 1.8 增至约 5.8–6.0；ScienceWorld 失败数下降，但平均步数从 40.96 增到 43.59。（Appendix C–D，Tables 7、10–11，PDF pp. 18、20）"],"evidenceLimits":["它是尚未经过同行评审的 arXiv preprint；论文与 arXiv 条目未给出可定位的 code link，因此这些是 paper-reported results，不是独立 reproduction。","math-only training 准确描述 embedding supervision，不描述整条 evaluation pipeline；三个 agent environments 的 insight pools 都由目标环境 trajectory 蒸馏，论文没有证明脱离 domain-specific experience 的 universal retriever。","partial trajectory 是最接近真实 agent state、也最关键的训练面，却继承 problem-level label，没有 state-specific usefulness supervision；每个 candidate pair 只验证一次，随机 solver outcome 会制造 false positive / negative。（Limitations，PDF pp. 9–10）","SRA-Bench 的 Recall@1 只增加 1.04 points，主要改善出现在较大的 k；candidate retrieval improvement 不能自动推出 top-1 injection 对 downstream policy 有帮助。","MedCalcBench 暴露了 query-type dependence：精确术语与事实检索上 intent model 的 top-1 明显低于 Base。论文没有提供一个经过验证的 router，说明何时使用 lexical、semantic、intent 或 hybrid lane。","同一条 insight 是否有用由特定 solver、单次 rollout、特定 task state 与 outcome 定义；这些 labels 不能直接当成跨模型、跨时刻或跨环境的 intrinsic memory quality。"],"sourceTensions":[{"label":"Cross-domain 不等于 domain-free","observation":"retriever 的 contrastive supervision 只来自数学任务，但 ALFWorld、WebShop 与 ScienceWorld 的 candidate insight pools 仍由各目标环境 trajectory 构造。","implication":"最稳的 claim 是 action-intent supervision geometry 可以迁移，不是一个无需目标环境经验的 universal memory system。","locators":["§3.3–§4.2，PDF pp. 4–6","Appendix A，PDF pp. 13–16"]},{"label":"最有用的 anchor 拿到最粗的 label","observation":"partial trajectories 贡献了大部分 agent-environment gain，却直接继承 whole-problem positive / negative label；论文明确承认没有 state-specific supervision。","implication":"一个 insight 在整局中曾有帮助，不能推出它在当前 turn 应被注入；trajectory detail 与 label resolution 在这里反向变化。","locators":["Appendix C，Table 7，PDF p. 18","Limitations，PDF pp. 9–10"]},{"label":"Action-intent 的胜利被 literal task 反驳","observation":"InsightEmb 在 MedCalcBench Recall@1 从 Base 的 92.73 降到 63.27；BM25→InsightEmb rerank 只恢复到 70.91。","implication":"论文自己的 counterexample 排除了“用 intent embedding 统一替代 lexical / semantic retrieval”的架构结论。","locators":["Appendix E，Table 17，PDF p. 29"]}],"editorialInferences":[{"label":"Retrieval is a staged decision","text":"candidate generation、intent judgement、context admission 与 downstream outcome 是四个不同问题。一个 intent score 可以帮助 rerank，却不能证明该 memory 应当被注入，更不能用一次成功反向改写 source 的长期价值。","boundary":"这是基于论文 evaluation design 与 harmful-retrieval counterexample 的 editorial synthesis，不是论文已经实现或验证的四阶段 architecture。"},{"label":"Hybrid routing is a permanent boundary","text":"literal lane 不是 intent model 尚未成熟时的临时 fallback。专名、剂量、identifier、精确事实与近似语义 bottleneck 的 failure cost 不同；MedCalcBench 表明统一 score 会系统性牺牲一类 query。","boundary":"这是从 Appendix E 反例推导出的设计判断。论文展示 BM25→InsightEmb rerank，但没有训练或验证一个完整 query router。"},{"label":"State-rich queries amplify goal assumptions","text":"把 goal、recent actions 与 observation 写进 query 会提升方向性；若 goal 本身只是未经验证的推断，同一机制也会把这个假设传播到整条 recall path。query 变得更具体，不等于它变得更真实。","boundary":"这是 architecture-level inference，不是 paper-tested failure；论文没有系统测量 wrong-goal、ambiguous-goal 或 goal-shift perturbation。"}],"openProtocols":[{"title":"Intent-versus-literal routing matrix","status":"proposed-not-run","question":"哪些 query 应由 intent rerank 获益，哪些 query 必须保留 literal recall，错误路由的伤害如何被直接观察？","method":"构造一组公开 synthetic situations，分别要求 operational next-step support、paraphrastic concept match、exact entity / identifier recall 与 harmful near-match rejection；比较 query-only lexical、situation semantic、intent rerank 与 hybrid router。","fixtures":"公开 fixture 为每条 query 提供 gold support、plausible distractor、harmful near-match 与 abstain case；不使用 private memory、内部项目或不可公开的 runtime trace。","controls":"固定 candidate corpus 与 k，分别移除 goal、history、observation，并加入 wrong-goal、stale-observation 与 exact-token ablation。","measures":"公开 support@k、harmful@k、exact recall、route decision、abstention 与 downstream synthetic task outcome；raw rankings 与 derived aggregates 分开。","limitations":"这是尚未执行的通用 protocol，不是 InsightEmb reproduction，也不能证明任何 private 或 production retriever 的效果。"}],"keywords":["action-intent retrieval","agentic insight","hybrid retrieval"],"categories":["可靠性","持续学习"],"failureSurfaces":["retrieval-active-context","abstraction-experience"],"sourceUrl":"https://arxiv.org/abs/2608.04761v2","pdf":{"delivery":"bundled","url":"papers/16-chung-2026-insightemb.pdf","originalUrl":"https://arxiv.org/pdf/2608.04761v2","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/"},"editorialQuestion":"最有用的 partial-trajectory anchors 仍继承 problem-level label，而且每个 insight–problem pair 只验证一次；如果当前 goal 或 state label 本身不可靠，action-intent retrieval 会不会只是更有方向地注入错误？","sourceNote":"arXiv v2；PDF 共 29 页。"},{"number":17,"id":"longmemeval-v2-experienced-colleague","kind":"paper","title":"LongMemEval-V2: Evaluating Long-Term Agent Memory Toward Experienced Colleagues","authors":["Di Wu","Zixiang Ji","Asmi Kawatkar","Bryan Kwan","Jia-Chen Gu","Nanyun Peng","Kai-Wei Chang"],"shortAuthor":"Wu 等","year":2026,"doi":"10.48550/arXiv.2605.12493","noteDepth":"read","readingScope":"完整读了 arXiv v1 的 §§1–6、Appendix A–E、Tables 1–11 与 Figures 1–7，共 32 个 PDF pages；references 只用于 lineage 定位。另检查 official code 的 paper-day release、2026-08-05 benchmark-metadata query-boundary fix 与 2026-08-09 current source，并执行 source-linked CPU-only boundary test、公开 question/tier-map exact-pair census 与 synthetic renderer feasibility audit；没有运行 benchmark、controller、模型、reader、judge 或真实 trajectory resolution。","intro":"LongMemEval-V2 把 agent memory 评价写成 context gathering：memory module 先消费大规模 multimodal trajectory history，再为固定 reader 返回不超过 200K tokens 的 evidence package。它直接测的是 bounded evidence construction，不是 online learning、未来 web-task success 或端到端 agent competence。（§3.3；Appendix E，PDF pp. 5–6、26–27）","whyRead":"这篇把“经验”从一句产品隐喻逼成了一个可定位的 evaluation object：25M–115M token 的历史怎样经过 memory 与 query controller 进入 bounded active context。真正值得保留的也不是 72.5% 单点，而是 paper、paper-day release、August query-boundary fix 与 current source 之间的 protocol drift，以及 current postprocessor 允许 controller prose 在没有有效支持时先进入 built memory context 的事实。它让 retrieval miss、controller assistance、evidence provenance、reader error 与 cost accounting 不再被同一个 memory score 吞掉。","keyPoints":["Evaluation object：451 个问题分别配一份有序 trajectory haystack；memory 经 Insert→Query 返回 context，固定 Qwen3.5-9B reader 在 200K-token cap 内回答。Small 平均 100 trajectories / 25.6M tokens，Medium 约 498 / 114.8M。（§3.2–§3.3；Figure 3，PDF pp. 4–6）","Correlated tiers：Small 在 domain 内共享 haystack；Medium 为 question-specific，却沿用 Small 的 answer seeds 后增加 fillers；zero-support abstention 与 source anchor 复用同一 haystack。两层不是 902 个独立 questions。（Appendix A.2–A.4，PDF pp. 15–17）","Controller-assisted headline：AgentRunbook-C 的 Small / Medium 为 74.9% / 70.1%，equal-tier average 72.5%；Codex 为 69.3%，strongest RAG 为 48.5%。但 C 的 gotcha 两层都低于 Codex，Medium overall gain 没有 paper legend 下的 significance marker。（Table 2，PDF p. 9）","Versioned boundary：paper-day AgentRunbook-R planner 使用 question type 与 original goals；August fix 才把 backend context 改成 opaque invocation ID。paper-day C backend API 可见 raw question item，但 direct-executed release sandbox payload builder 仍只返回 query text/image，不能夸成 gold 或 metadata 已转入 sandbox。（Appendix Tables 9–10；official source history）","Executed contract test：current Codex postprocessing 会在 spans 为空、unknown、越界或只指向 opposite-value decoy 时继续把 answer-like memory_markdown 放进 built memory context；current AgentRunbook-C source 继承并调用这组 methods，optional evidence gate 也不要求 directly_supported 至少有一个 valid span。（public synthetic artifact）"],"argumentMap":[{"step":"01 · 先把经验变成 bounded evidence task","claim":"作者不让 memory system 直接操作网站或生成最终 benchmark answer，而是把它放在 trajectory history 与固定 reader 之间；这样 retrieval / synthesis 与 reader answering 可以被分别观察。","locator":"§1；§3.3，PDF pp. 1–2、5–6"},{"step":"02 · 用稀疏 needles 压测环境知识","claim":"451 个问题覆盖 static、dynamic、workflow、gotcha 与 premise awareness；平均 answer core 只有 1.39 trajectories，却被埋进 100 或约 498 条 web-agent histories。","locator":"§3.1–§3.2；Figures 2–3，PDF pp. 4–5"},{"step":"03 · 比较 retrieval controller 与 file-research controller","claim":"R 从 raw states、events 与 notes 中生成结构化 queries；C 将 trajectories 文件化，让 coding agent 先分类、短列、检索 spans 并写 narrative context，再交固定 reader。","locator":"§4.1；Appendix A.8–A.9，PDF pp. 7–8、21–24"},{"step":"04 · 用 adverse results 与 source lineage 限定 headline","claim":"C 整体领先并更快于 vanilla Codex，但 gotcha 退化、helper ablation 在 Medium 提高 accuracy；paper-facing metadata contract 又与 current source 不同，因此结果属于特定 controller protocol，而不是 method name 的 timeless property。","locator":"§4.2–§4.3；Tables 2、9–11，PDF pp. 8–10、28–30"}],"methodNotes":[{"label":"Question and coverage construction","text":"四名学生 annotators 构造问题；frontier-model no-context failures 被用于过滤、改写或形成 distractors。answer-bearing trajectories 先由 Codex-assisted proposals 找候选，再由人确认 final minimal core；公开说明没有建立 exhaustive-negative coverage audit。","locator":"§3.2；Appendix A.1–A.3，PDF pp. 4–5、14–16"},{"label":"Reader and heterogeneous scoring","text":"固定 Qwen3.5-9B reader 使用 stochastic decoding；structured answers 做 phrase / order matching，gotcha 与 abstention 由 GPT-5.2 medium judge。UNKNOWN 恒错，abstention 的 environment-access disclaimer 也可能得分。","locator":"Appendix A.5–A.6；Tables 4–5，PDF pp. 17–20"},{"label":"Query-stage latency","text":"reported memory latency 包围 query stage；trajectory insertion / index building、context truncation、reader、judge 与 post-query consolidation 不在同一数字内。Medium question-specific workspaces 与 Small shared workspaces 的 amortization 也不同。","locator":"§4.2；Appendix A.7；Table 2，PDF pp. 8–9、20"},{"label":"Source-linked local audit","text":"第一组公开 runner 对三个 exact Git revisions 做 AST/source-locator checks，并用 sentinel metadata 直接执行每个 revision 的 AgentRunbook-C payload builder；随后执行 current output validator / normalizer / context builder。第二组 model-free audit 遍历 451 个公开 question/tier-map rows、生成完整 selection ledger，并用三条 synthetic trajectories 定位 renderer 的真实排序面。","locator":"research/longmemeval-v2-boundary-audit/；research/longmemeval-v2-alias-order-preregistration/"}],"reportedFindings":["Table 2 的 Small / Medium overall：slice RAG 42.8 / 38.1，slice+notes 51.0 / 45.9，AgentRunbook-R 58.6 / 57.0，Codex 69.9 / 68.7，AgentRunbook-C 74.9 / 70.1。（PDF p. 9）","AgentRunbook-C 在 gotchas 低于 Codex：48.3 vs 58.6（Small），44.9 vs 51.7（Medium）；Medium workflow 同为 61.3。C 的 Medium overall 70.1 vs 68.7 在论文表格中没有 significance marker。（Table 2，PDF p. 9）","移除 C helper functions 后 Medium overall 从 70.1 升到 71.8、workflow 从 61.3 升到 68.9，但 latency 增加；helper 的作用是 accuracy–latency trade，不是 uniform accuracy gain。（Table 11，PDF p. 30）","no-context pilot 与 oracle pilot 只用 323 个 non-abstention questions；Codex 的 89.7% oracle-trajectory pilot 直接从 answer-bearing files 写 final answer，不经过 main fixed-reader boundary。（Appendix B，PDF pp. 18–20）","Introduction 报 simple slice RAG average 40.1%，Table 2 的 42.8% 与 38.1% 等权平均为 40.45%；selected paper/source 没有提供能得到 40.1 的 alternative denominator。"],"evidenceLimits":["这是 arXiv v1 work-in-progress preprint。current official code 是 paper 之后持续修改的 successor；没有 paper-era run artifacts、per-question predictions、judge transcripts、seeds 或完整 bootstrap implementation 可独立恢复 Table 2。leaderboard source 把 paper points hard-code，不能代替 reproduction。","paper 只评估 pre-collected browser trajectories 与 fixed-reader context gathering，不评估 live online learning、未来 website task success、sensitive enterprise history、human interruption cost 或行动安全。","Small / Medium 复用同 questions 与 answer seeds，abstention/source pairs 也共享 haystacks；paired bootstrap 的 resampling unit、次数、CI、multiple-comparison 与 cluster handling 未公开。","公开 questions 与 answers 使 current benchmark-metadata query-boundary regression tests 只能防 accidental backend coupling，不能把 public leaderboard 变成 held-out test；exact question text 仍可被 unrestricted custom backend 当 lookup key。","本地 contract test 证明 current postprocessor 允许 unsupported answer-like prose，不证明 controller 实际生成过这种输出、不估计频率、不解释 paper gain，也没有测 sandbox escape。successor census 只证明三组 exact public pairs 与 intervention surface 可构造；full trajectory resolution 和 66-job controller phase 均未执行。","synthetic valid-but-decoy case 使用 exact opaque-token oracle 判断 semantic support；它足以证明没有 semantic alignment enforcement，却不是一般 natural-language entailment evaluator。"],"sourceTensions":[{"label":"Paper method 与 paper-day C code 已分叉","observation":"Appendix Table 10 说 C 的 question.json 含 ID 与 metadata；paper-day release harness/backend context 也可见 raw item，但同 revision 的 C/Codex sandbox payload builder 只序列化 query text/image。","implication":"不能让 paper prose、release API visibility 与 sandbox contents 互相替代；May 72.5% 的 exact operational protocol 仍不能从 current source alone 恢复。","locators":["Appendix Table 10，PDF p. 29","official source c5c552d…"]},{"label":"Accuracy gain 在 gotcha 与 helper 上反向","observation":"C 的 overall average 高于 Codex，但 gotcha 两层都更低；移除 helper functions 又提高 Medium overall 与 workflow accuracy。","implication":"specialized controller 的收益依赖 question family 与 cost budget，不能从 aggregate 推出每个 memory ability 或 helper 都改善。","locators":["Table 2，PDF p. 9","Table 11，PDF p. 30"]},{"label":"Structured output 没有形成 evidence contract","observation":"current output schema 同时允许 answer-like memory_markdown 与 empty spans；normalizer 只删除 unknown / out-of-range spans，context builder 仍先发送 prose。optional evidence gate 只检查 status/policy pairing，而且 evidence_status / answer_policy 没有被渲染进 built memory context。","implication":"structured JSON 提高 addressability，却不能单独证明 built memory context 中的 synthesis 被 cited trajectory 支持；prose admission 与 span provenance 需要额外 contract。","locators":["current memory_modules/codex.py","public boundary audit raw cases"]}],"editorialInferences":[{"label":"A context package is an authored evidence object","text":"query controller 不只是找回旧内容：它决定 query routing、选择 spans、生成 narrative、排列 evidence 并在 token cap 下占据前缀。它产出的 context package 本身需要 provenance、admission 与 truncation semantics，不能继承 raw trajectory 的 authority。","boundary":"这是由 paper method、prefix context order 与 local contract test 推出的 editorial synthesis；论文没有提出完整的 provenance-enforcing context package schema。"},{"label":"Query-boundary isolation and benchmark integrity are different","text":"opaque invocation ID 能消除 honest backend 对 question type、gold row 与 original goals 的 API coupling；公开 question text / answers、question-specific haystack fingerprints 与 unrestricted code execution仍是另一组 leaderboard-integrity问题。","boundary":"current benchmark-metadata query-boundary tests 证明 direct-interface narrowing；它们不是 held-out benchmark、安全 sandbox 或反作弊机制，也没有证据表明 reported methods 做了 answer lookup。"},{"label":"Experienced colleague is a layered claim","text":"trajectory authority、retrieval、controller synthesis、reader comprehension、task execution 与 action authorization 是六个不同层次。LME-V2 对前四层中的 bounded QA path 有价值，但不能用一个 context-gathering score替后两层签字。","boundary":"这是对 evaluation object 与 Appendix E limitations 的 architecture-level interpretation，不是论文声称已经验证 online colleague competence。"}],"openProtocols":[{"title":"Alias × order × prose-admission protocol","status":"proposed-not-run","question":"current-source AgentRunbook-C controller 的 selected evidence 与 prose 会不会随 trajectory identity aliases 或 observable order 改变；这种变化在 exact-haystack answerable/abstention pairs 中是否不同？","method":"选择 locked public files 中全部三组 exact ordered-Medium answerable/abstention classes；六个 questions 各跑 Small / Medium × C00/C10/C01/C11。alias 使用 rank-preserving opaque IDs；direct order treatment 是预生成的 concise/full summary-record order，insertion/index/manifest 只同步为 consistency surfaces。另加每个 question-tier 一个 exact-input repeat 与每个 question 一个 empty-memory control。","fixtures":"三组 web-procedure Medium families、六个 question IDs、共享 web Small haystack 与待一次性解析的 locked trajectories union；预计 48 factorial + 12 repeat + 6 no-memory，共 66 query-method jobs。","controls":"pair 内共享 alias map 与 permutation；所有 Small probes 共享一组 map/permutation；hash-derived ledger 固定 aliases、permutations、repeat cells 与 66-job order；fresh workspace/process；P prose-only、E valid-evidence-only、B unchanged combined、G human provenance-gated packages。没有 replacement class。","measures":"ledger 将 state/trajectory set 固定为 de-aliased Jaccard distance，将 prose 固定为 NFKC/whitespace-normalized character Levenshtein ratio，并固定 evidence-context canonical JSON hash、completion/retry 与 invalid/empty coding；按三组 Medium family 与共享一个 haystack 的六个 Small queries 分开汇总，不给 p-value、CI 或 bootstrap。","limitations":"这是 prospectively specified 但未获 gate release 的 66-job protocol。三组 classes 全部属于 web procedure；full trajectory resolution 未运行，exact intended CLI signing-trust gate 为 HOLD，controller-tool network-isolation preflight 也未通过，controller jobs 为 0。它不能恢复 May run、测 reader/accuracy 或外推到其他 strata。"}],"contributions":[{"type":"public-test","title":"Versioned benchmark-metadata query and answer-evidence boundary audit","byline":"Agent Memory Study editors","date":"2026-08-14","basis":"Paper-facing audit of Appendix Tables 9–10 plus official source at the paper-day release, the 2026-08-05 query-boundary fix, and the 2026-08-09 current revision. Current Codex output behavior is locally executed through the exact validator, normalizer, and context builder; AgentRunbook-C inheritance and call sites are source-inspected.","boundary":"This is a versioned source/payload audit and synthetic built-context contract test, not a LongMemEval-V2 benchmark reproduction. It does not execute the reader, estimate controller behavior frequency, explain Table 2 gains, prove answer lookup or sandbox escape, apply to AgentRunbook-C V2, or validate any deployed memory system.","method":"Run sixteen AST- and payload-level checks across three exact Git revisions, each with blob/function/line/excerpt locators and sentinel metadata; then run 18 standard-library-only AXTree rows with two opaque answer tokens through current CodexMemory output validation, span normalization, and built-context construction.","environment":"macOS 26.5.2 arm64；Python 3.13.3；Python standard library only；targeted Python socket DNS/connect guard；local Git object reads only；no model, reader, judge, tokenizer or embedding calls.","fixture":"Each fresh workspace contains a two-state support trajectory whose final AXTree carries the opaque answer token and a one-state AMBER decoy. Cases cover valid support, evidence-only, empty spans, missing trajectory, out-of-range state, decoy evidence, two evidence-gate inconsistencies, a syntactic policy mismatch and an empty control.","controls":"Supported and evidence-only positives, empty negative, syntactic gate mismatch, independent CERULEAN/MAGENTA token repetitions, exact source revision checks, clean checkout requirement, source-file hashes and checked-in full normalized outputs / built memory contexts.","rawResult":"All sixteen versioned source/payload checks passed. Supported/evidence-only controls passed and the status/policy mismatch was rejected. Six predeclared evidence-binding failure patterns, each replicated with two opaque tokens, left answer-like prose in built memory context without selected token support; twelve rows failed in total.","derivedResult":"The fix/current direct query boundary is narrower than the release boundary. At current source, the Codex postprocessor does not enforce that answer-like memory_markdown included in built memory context is supported by valid selected trajectory spans; current AgentRunbook-C inherits and invokes those methods without another semantic gate.","limitations":"The support oracle is exact-token presence in synthetic AXTree text; the opposite-value decoy is valid for this fixture, not a general entailment judge. Six designed patterns and twelve replicated rows are not population estimates. No reader, benchmark data or model behavior was measured; current regression tests were located in source, not executed by this runner.","links":[{"label":"method, decision rules and limits","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/longmemeval-v2-boundary-audit/README.md"},{"label":"runner","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/longmemeval-v2-boundary-audit/audit.py"},{"label":"raw decision","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/longmemeval-v2-boundary-audit/raw/decision.json"},{"label":"all built memory contexts","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/longmemeval-v2-boundary-audit/raw/reader_contexts.jsonl"}]},{"type":"public-test","title":"Alias/order pre-registration and public exact-pair census","byline":"Agent Memory Study editors","date":"2026-08-14","basis":"Locked public questions, Small and Medium haystack maps, official current-source renderer and AgentRunbook-C/Codex boundary files, plus a bounded preflight of the exact intended Codex CLI candidate.","boundary":"This is a deterministic selection census and intervention-feasibility audit. It does not resolve the full selected trajectory union, run a controller or model, estimate behavior frequency, execute a reader or judge, score the benchmark, attribute Table 2, or reconstruct the May controller run.","method":"Hash every eligible ordered Medium haystack, select every same-domain/base-type class containing answerable and abstention members, retain a complete class ledger, inspect the current renderer contract, and execute forward/reverse filesystem materialization plus rank-preserving and order-reversing alias controls. Then pre-seed reordered official summaries and exercise the exact current ensure/sandbox-link path.","environment":"macOS 26.5.2 arm64；Python 3.13.3 standard library plus Git CLI；locked local public files and clean official source checkout；no network, model, controller, reader, judge, tokenizer or embedding call in the audit.","fixture":"All 451 public question records and both locked tier maps drive selection. Two synthetic trajectories share one renderer tie group; a third differs in start URL and goal.","controls":"Exact source/data hashes, complete eligibility and exclusion ledgers, canonical-array equality behind every shared hash, selected Small equality, forward/reverse materialization, rank-preserving and order-reversing aliases, pre-seeded summary byte preservation, exact checksum file-set verification and a no-bypass exact-runtime stop rule.","rawResult":"The census found 422 eligible text-only questions and excluded 29 image-bearing gotcha items. Exactly three pair-eligible ordered-Medium classes and six selected questions remained; all were web procedure and shared one 100-ID ordered Small array. Filesystem materialization-order reversal produced byte-identical official summaries; alias tie behavior matched the declared controls. Pre-seeded reordered summaries survived the exact ensure path with summary_rendered false and remained byte-identical through the sandbox-linked trajectories surface.","derivedResult":"The renderer's alias tie-order behavior, the need for an explicit post-sort order surface, and the current source's pre-seeded summary-order bypass are reproducibly established. The 66-job controller phase remains HOLD with zero jobs executed because full trajectory resolution and execution gates were not passed.","limitations":"The three classes are a finite census of exact public-pair support, not hidden official provenance or a representative benchmark sample. Runtime fields are an author-recorded bounded local preflight observation not independently replayed by the artifact; they are not a security finding about other releases. No controller output or reader effect exists in this artifact.","links":[{"label":"method, result and boundary","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/longmemeval-v2-alias-order-preregistration/README.md"},{"label":"prospective revised protocol","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/longmemeval-v2-alias-order-preregistration/PREREGISTRATION.md"},{"label":"raw decision","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/longmemeval-v2-alias-order-preregistration/raw/decision.json"},{"label":"selected exact families","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/longmemeval-v2-alias-order-preregistration/raw/selection/selected_families.json"},{"label":"randomization and analysis ledger","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/longmemeval-v2-alias-order-preregistration/raw/protocol_ledger.json"}]}],"keywords":["trajectory memory","context gathering","evidence provenance","query boundary"],"categories":["可靠性","持续学习"],"failureSurfaces":["retrieval-active-context","abstraction-experience"],"sourceUrl":"https://arxiv.org/abs/2605.12493v1","pdf":{"delivery":"bundled","url":"papers/17-wu-2026-longmemeval-v2.pdf","originalUrl":"https://arxiv.org/pdf/2605.12493v1","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/"},"editorialQuestion":"当 query controller 能读取 benchmark-derived routing hints、生成 answer-like narrative、决定 evidence order 并优先占据 token budget 时，什么 contract 才能证明 fixed reader 得到的是 trajectory-supported experience，而不是一个更会写答案的中间层？","sourceNote":"arXiv v1 work-in-progress preprint；PDF 共 32 页。paper-day release、August query-boundary fix 与 current source 分开标注；两组 public tests 分别停在 built-context contract 与 model-free selection/intervention feasibility，不执行 controller、fixed reader 或 benchmark reproduction。"},{"number":18,"id":"statefuse-conflict-preserving-memory","kind":"paper","title":"StateFuse: Deterministic Conflict-Preserving Memory for Multi-Agent Systems","authors":["Sergey Volkov","Yang Li","Ye Luo"],"shortAuthor":"Volkov 等","year":2026,"doi":"10.48550/arXiv.2607.05844","noteDepth":"worked","readingScope":"完整读了 arXiv v1 的 §§1–6、Appendix A.1–A.5、Tables 1–5 与 Figures 1–3，共 18 个 PDF pages；references 只用于 lineage 定位。另检查 official source commit 79a6229f83a7b174a2a9ac8fd0ace267ae30e79b（StateFuse 0.3.0），运行完整 139-test official suite，并执行 preregistered model-free interpretation-contract audit：8 个 synthetic fixtures、17 个 same-contract permutation groups、428 个 raw state/projection rows 与一次 fresh byte reproduction。没有复现论文的 MemoryAgentBench slice、uniform-verification agent loop、correction-handle ablation、模型输出、live connector 或 production trace；repository 中标题不同的 unpublished manuscript 只作为独立 successor source 标注，不向 arXiv v1 反向转移主张。","intro":"StateFuse 把 replicated memory 拆成两个容易被混淆的层：immutable OpSet 负责让 operation set 收敛，predicate registry、conflict detector、resolver 与 query constraints 再把这个集合解释成可行动的 view。本条 worked essay 所附的 synthetic contract audit 在锁定的 StateFuse 0.3.0 source 上显示：在这些 preregistered fixtures 中，byte-identical operations 仍可因 deterministic interpretation contracts 不同而产生不同的 conflict、activity、resolution lifecycle 与 projection；这收窄的是 replay precondition，不构成 OpSet merge law 的反例。","whyRead":"这篇值得做成 worked essay，不是因为它发明了新的 CRDT join——作者反复否认这一点——而是因为它把 agent memory 最常被悄悄吞掉的三件事变成 public contract：分歧是否被显式保留、修正到底指向一个 assertion 还是一个 semantic class、downstream resolver 能否把选择写回历史。close read 与本地测试合在一起后，真正有用的结论更尖锐：merge substrate 的确定性只管同一组 immutable operations；要让 replica 的 semantic view 也可复现，还必须绑定 interpretation contract。","keyPoints":["Contract boundary：StateFuse 以 immutable EvidenceAdded / ClaimAdded / ClaimRetracted / DecisionAdded operations 构成 OpSet；materialization 先计算 effective claim refs、应用 exact / semantic tombstones、过滤 inactive claims，再为 functional keys 生成显式 ConflictSet。projection 可以选择、abstain 或 fail closed，但不能修改 base memory。（§§3.2–3.4；Figure 1，PDF pp. 5–7）","Dual correction handles：arXiv v1 将 claim_id 定义为 assertion-local identity，将 claim_ref 定义为由 claim key 与 predicate-governed value contract 导出的 cross-replica semantic handle。锁定的 0.3.0 official source 进一步显示，default ref payload 包含 key 与 value，仅在 non-default 时包含 kind、在 non-empty 时包含 context；validity、confidence、timestamp、evidence、provenance 与 derivation identity 不进入该 payload。semantic retraction 会使共享该 ref 的 claim instances 失活，包括随后才进入 merged OpSet 的 instances。（arXiv v1 §§3.2–3.3；Appendix A.1、A.3–A.4，printed PDF pp. 5–6、14–15；official source src/statefuse/model.py 与 src/statefuse/materialize.py）","Paper result：在 282-question MemoryAgentBench conflict-bearing slice 上，aggressive StateFuse、flat multi-value、raw log 与 collapsed baselines 同为 97.5% final accuracy；显式 conflict-preserving surfaces 的差异主要是 100% conflict recall。uniform-verification synthetic loop 中 conservative non-collapsing surfaces 同到 100% post-verify success，而 collapsed surface 为 60% 且有 40% post-verify false confidence。（§4.2；Tables 2–4，PDF pp. 9–11）","Executed synthetic result：锁定 0.3.0 source 上的 8 个 exact fixtures、17 个 fixed-contract constructor-permutation groups 与 428 个 raw state/projection rows 满足 preregistered H1/H2 gates。每个 fixed-contract group 各自产生一个 state digest 与一个 projection digest。该结果未测试 merge-tree equivalence、实现内部 replay-path independence 或跨环境重现。（public synthetic contract test）"],"argumentMap":[{"step":"01 · 先把 merge 与 interpretation 拆开","claim":"论文接受标准 OpSet set-union 作为 convergence substrate；它的研究对象不是新的 join，而是 operations 收敛之后，memory 怎样形成 active claims、conflicts 与 task-scoped projection。","locator":"§§1、2.1、3.3；Appendix A.1–A.3，PDF pp. 1–3、6、14–15"},{"step":"02 · 把 disagreement 留在 public surface","claim":"materialization 不以 latest-write 覆盖 functional-key disagreement，而是发出 ConflictSet；resolver 的 authority 被限制在 projection，resolution 失败或 abstention 仍留下 unresolved/surfaced conflict 与 explanation。","locator":"§§3.3–3.4；Figures 1–3，PDF pp. 6–9"},{"step":"03 · 用 matched policy budget 收窄 empirical claim","claim":"strong flat conflict-preserving baselines 在 answer accuracy 与 conservative operating point 上能追平 StateFuse；因此论文把贡献收窄为 contradiction surfacing、abstention 与 auditable semantic correction 的 contract，而不是 universal accuracy gain。","locator":"§§4.2–5.3；Tables 2–5，PDF pp. 9–12"},{"step":"04 · 再问 fixed OpSet 是否已经足够","claim":"论文的 replayability 明示 fixed predicate registry、resolver 与 constraints；本地 audit 进一步显示 current source 没有把 registry/detector implementation identity 写进 shared OpSet。same-contract replay 仍稳定，但 cross-contract replicas 可以对同一 operations 形成不同 semantic views。","locator":"§3.2；Appendix Proposition 6，PDF pp. 5、15；official source 79a6229…；public H1 audit"},{"step":"05 · 把 correction scope 当 ontology 选择","claim":"semantic ref 是故意设计的 broad correction handle。它能解决 missing-ID / unseen-target correction，也会让不同 validity occurrences 在 semantic identity 相同时共享 tombstone；应用必须明确自己要 correction assertion、occurrence 还是 semantic class。","locator":"§§3.2–3.3、4.3；Table 5；Appendix A.1、A.4，PDF pp. 5–6、9–10、12、14–16；public H2 audit"}],"methodNotes":[{"label":"OpSet materialization and projection","text":"Merge 对 immutable op_id 做 set union；materialization 以 sorted traversal 建索引、派生 refs、应用 exact/semantic tombstones、按 ClaimKey 分组并生成 conflicts。build_view 读取 materialized state 与 constraints，由 deterministic conservative resolver 或受 schema 限制的 optional LLM resolver 形成 separate projection。","locator":"§§3.3–3.4；Appendix A.1–A.3，PDF pp. 6–7、14–15"},{"label":"Paper evaluation layers","text":"主 evidence 是 converted official MemoryAgentBench conflict-bearing slice 与每种 surface 共享 verification budget 的 50-task synthetic agent loop；另用 13-task deterministic handle ablation 比较 claim_id / claim_ref。paper tables 报 final accuracy、false certainty、conflict recall、recoverability 与 abstention quality，但本次本站 audit 没有重跑这些 datasets/runs。","locator":"§§3.6、4.1–4.3；Tables 2–5，PDF pp. 7–12"},{"label":"Preregistered interpretation-contract audit","text":"H1 的 equality、semantic-handle normalization 与 detector/lifecycle strata 在 paired treatments 中锁定 canonical operation JSON、OpSet hash、query constraints、resolver、serialization、locale/timezone；H2 使用 Monday/Tuesday disjoint validity claims，比较 no retraction、exact-ID、same-ref、changed-context 与 changed-value controls。每个 fixed-contract OpSet 穷举全部 2、6 或 120 个 constructor permutations。","locator":"research/statefuse-interpretation-contract-audit/PREREGISTRATION.md；raw/cases.jsonl"},{"label":"Source, suite and reproduction receipts","text":"runner 锁定 arXiv PDF hash、official commit、package version、14 个 source/test/manuscript blobs 与自身 source hash；记录 pytest collect/run 全输出，重算 428 rows 的 payload digests 与 H1/H2 decision，再在同一 invocation 内完整执行 second pass，对八个 primary files 做 byte comparison。","locator":"research/statefuse-interpretation-contract-audit/raw/source_manifest.json；raw/environment.json；raw/reproduction.json"}],"reportedFindings":["aggressive official-slice comparison中，StateFuse、flat multi-value、raw log 与 collapsed latest-write 都是 97.5% final accuracy；StateFuse 与 flat conflict-preserving surfaces 为 100% conflict recall，raw log/collapsed 为 0%。这支持 surface distinction，不支持 unique answer-accuracy gain。（§4.2；Table 3，PDF pp. 9、11）","conservative official-slice operating point 中，StateFuse、StateFuse core、MV register 与 provenance surface 都为 64.9% accuracy、100% conflict recall、2.1% false certainty；raw log conservative 同为 64.9% accuracy 但 0% conflict recall。（Tables 2–3，PDF pp. 10–11）","uniform-verification 50-task loop 中，五个 conservative non-collapsing surfaces 都从 80% pre-verify 到 100% post-verify success、0% post-verify false confidence；collapsed surface 从 40% 到 60%，仍有 40% false confidence。该 loop deterministic，paper 因此没有给 confidence intervals。（Tables 2、4，PDF pp. 10–11）","13-task correction-handle ablation 中，claim_ref 为 100% final accuracy / no-resurrection / ID-target match / semantic-target recoverability；claim_id 为 76.9% / 76.9% / 100% / 0%。这是 paper 对 semantic handle expressivity 的主要支持。（§4.3；Table 5，PDF pp. 9–10、12）","本地 H1 中，byte-identical operations 在不同 deterministic equality/ref/detector contracts 下改变 conflict formation、effective refs、inactive sets、candidate membership、resolution lifecycle 与 projection；declared detector v2 control 把 behavior change 移到新的 visible locus。H2 中 same-ref retraction 同时停用 disjoint-validity Monday/Tuesday claims，而 exact-ID、changed-context 与 changed-value controls 保留 Tuesday claim。（public synthetic contract test）"],"evidenceLimits":["论文的 strongest external evidence 是一个 converted MemoryAgentBench conflict-bearing slice；本站没有取得并独立重算这 282 questions 的转换、predictions 或 aggregate，也没有重跑 50-task agent loop 与 13-task handle ablation，因此这些数字保持 paper-reported。","uniform-verification loop 与 handle ablation 是 controlled deterministic evaluations，没有 repeated stochastic runs 或 confidence intervals；论文也没有 large naturally arising trace study、broad benchmark portfolio 或 endpoint-specific live LLM comparison。（§5.5，PDF pp. 12–13）","H1 只证明 exact StateFuse 0.3.0 在四组 newly authored synthetic fixture strata 上允许 cross-contract semantic divergence；它不估计 replica contract drift 的生产频率、损害、攻击可利用性、整体 reliability 或对其他 versions 的适用性。","H2 组合的是 source 已明确的 broad semantic tombstone 与 validity-independent default ref identity。它证明 recurrence consequence，不证明 library bug、data loss 或错误 ontology；需要 occurrence-local correction 的应用可以把 occurrence 编入 key/value/context，或使用 exact-ID handle。","同一 fixed contract 下的 17 个 permutation groups 全部产生单一 state/projection digest；因此当前结果不能被写成 merge-order nondeterminism、OpSet commutativity/associativity/idempotence failure 或论文 Propositions 1–2 的 same-contract counterexample。","repository 的 paper/main.tex 在 locked commit 中是标题和实验叙述均不同的 unpublished successor manuscript。official suite 的 139 passed/0 skipped 是本地 source execution receipt，不能反向替代 arXiv v1 的 paper-reported evidence或被说成 paper reproduction。"],"sourceTensions":[{"label":"Same OpSet 不是完整 replay identity","observation":"Appendix Proposition 1 将 benign-replica convergence 写成 O1 = O2 ⇒ M(O1) = M(O2)，但 Proposition 6 的 projection replayability 明确还要求 fixed predicate registry、resolver 与 constraints；official source 接受 pluggable equality/ref normalization 与 conflict detectors，却没有把一份 shared contract digest 绑定进 OpSet。","implication":"对外引用 convergence 时必须补全 interpretation precondition。可复现 semantic view 的 identity 是 operations 加 contract/query/projection inputs，而不是 operation bytes 单独决定。","locators":["§3.2；Appendix Propositions 1、6，PDF pp. 5、15","official source 79a6229… predicate registry / detector paths","public H1 raw decision"]},{"label":"Semantic correction 的优势与范围来自同一机制","observation":"Paper-reported：arXiv v1 在 contract 层将 claim_ref 描述为由 claim key 与 predicate-governed value contract 导出的 semantic handle，并规定 semantic-handle retraction 的 no-resurrection 语义。Official-source observation：锁定的 0.3.0 default implementation 具体将 key/value、non-default kind 与 non-empty context 纳入 ref payload，同时将 validity 与其他 occurrence metadata 留在 payload 之外。H2 因此属于 exact-source synthetic audit 的 correction-scope observation，不是 arXiv v1 报告的实验结果。","implication":"missing-ID recoverability 与 cross-occurrence tombstone carryover 不能被当作无关特性：handle 的 semantic identity 越宽，correction reach 越强，应用越需要明确 recurrence / occurrence ontology。这只识别一个 locked implementation 与 fixture family 产生的 correction granularity，不证明 paper contradiction、defect、vulnerability 或普遍更优的 occurrence ontology。","locators":["§§3.2–3.3、4.3；Table 5，PDF pp. 5–6、9–10、12","official source model/materialize paths","public H2 raw decision"]},{"label":"arXiv v1 与 repository manuscript 必须分层","observation":"reviewed arXiv v1 题为 StateFuse: Deterministic Conflict-Preserving Memory for Multi-Agent Systems；locked repository 的 paper/main.tex 是题为 StateFuse: Taxonomy-Aware Conflict-Preserving Memory for Heterogeneous Agent Systems 的 unpublished successor manuscript。两者共享 project lineage，但不是同一个 reviewed evidence object，其主张或 test counts 不向 arXiv v1 反向转移。","implication":"essay 只把 PDF pp. locators 归给 arXiv v1；current source/manuscript 用 exact commit 与 unpublished-successor 标签单列，不能用后来的 code/tests/manuscript 修补 paper claim。","locators":["arXiv:2607.05844v1，PDF p. 1","official source 79a6229… paper/main.tex","public source manifest"]}],"editorialInferences":[{"label":"Merge convergence is not view convergence","text":"replicated memory 的一致性至少有两个 axes：operation membership 是否收敛，以及相同 operations 是否在相同 semantic contract 下得到同一 active/conflict/projection view。只给 OpSet hash 只能回答第一问。","boundary":"这是对 paper replay preconditions 与 H1 synthetic result 的 architecture synthesis；不是新 CRDT theorem、形式证明或对 StateFuse merge implementation 的 failure claim。"},{"label":"Interpretation contracts need deployable identity","text":"normalizer、equality、claim-ref derivation、detector behavior 与 detector ID 应形成可比较的 manifest/version，并在 replica handshake、snapshot、migration 与 audit receipt 中共同出现；deterministic source code 仍可能是另一份 deterministic contract。","boundary":"audit 证明 current exact source 不强制 cross-replica contract identity；它没有验证某一种 manifest protocol、rolling upgrade mechanism 或 distributed deployment。"},{"label":"Correction handles are ontology, not only API ergonomics","text":"claim_id、claim_ref 与 occurrence-bearing identity 分别回答“撤回这次 assertion”“撤回这类 semantic assertion”“撤回这个时段/事件实例”。把它们 collapse 成一个 retraction endpoint，会让 correction authority 的范围只能靠 payload accident 决定。","boundary":"H2 展示 current default identity 的 controlled consequence；不同 domain 可以合理选择不同 granularity，本站没有宣布 universal correct ontology。"},{"label":"Surfacing conflict and authorizing action are separate","text":"ConflictSet 让 disagreement 变得可见，但不会替 agent 决定何时 abstain、验证、选择或请求 human review。一个 auditable memory surface 是 action governance 的输入，不是 authorization 本身。","boundary":"paper 的 bounded resolver contract 与 synthetic loop 支持分层阅读；它没有测 human oversight、real-world action cost 或 high-stakes deployment safety。"}],"openProtocols":[{"title":"Replica contract-manifest and rolling-migration protocol","status":"proposed-not-run","question":"当 replicas 在 registry、claim-ref derivation 或 detector version 上滚动升级时，什么 manifest/handshake contract 能让 semantic-view divergence 被拒绝、显式隔离或可审计迁移，而不重写 immutable history？","method":"在 fixed OpSets 上引入 canonical contract manifest，分别执行 same-version replay、silent behavior drift、declared-version change、mixed-version rolling window 与 explicit migration projection；每次 merge/materialize 前比较 manifest identity，并把 reject/quarantine/dual-view/migrate 四种 policy 写成独立 treatments。","fixtures":"复用 H1 equality、ref-normalization 与 detector/lifecycle OpSets，再增加 old-ref/new-ref 并存、old detector resolution 对 new candidate set 失效、semantic tombstone 跨 identity-version 与 snapshot restore cases。","controls":"byte-identical operations、fixed query/resolver/serializer、same-contract positives、manifest-only negative、behavior-different same-ID adversarial control、declared-version control、clean restart 与 two-replica exchange；不使用 model、live connector 或 private trace。","measures":"分别报告 operation-set convergence、manifest agreement、state/projection digest agreement、rejected/quarantined operations、dual-view exposure、resolution carryover、retraction reach 与 migration reversibility；任何 automatic rewrite 都必须保留 old/new provenance。","limitations":"这是 proposed-not-run deployment-contract protocol。它不能从当前 local fixtures 推出 production prevalence、network partition behavior、Byzantine safety、schema-migration policy或最佳 user-facing resolution experience。"}],"contributions":[{"type":"public-test","title":"Interpretation-contract binding and semantic-reference recurrence audit","byline":"Agent Memory Study editors","date":"2026-08-24","basis":"Paper-facing audit of arXiv:2607.05844v1 and official nZiben/statefuse commit 79a6229f83a7b174a2a9ac8fd0ace267ae30e79b (package 0.3.0), with exact source/test blobs, the repository's separately labeled unpublished manuscript, and newly authored synthetic fixtures.","boundary":"This is a preregistered, model-free synthetic interpretation-contract test. It is not a paper benchmark reproduction, model or connector evaluation, CRDT merge-law counterexample, security vulnerability, bug declaration, production frequency/harm estimate, or validation of the repository successor manuscript's experiments.","method":"Lock the paper, source commit, package version, source/test blobs, registry/detector descriptors, resolver, queries and serializers; run the complete official suite; execute all permutations for eight exact fixtures; store 428 schema-versioned state/projection snapshots; recompute every payload digest and derive H1/H2 decisions from raw fields; then repeat the full pass and byte-compare the primary outputs.","environment":"macOS 26.5.2 arm64；CPython 3.13.3；pytest 9.1.1；StateFuse imported from a reader-supplied clean exact checkout；socket network guard around every custom registry/detector invocation；no model, API, credential, benchmark trace, live connector or private data.","fixture":"H1 uses raw/folded equality, raw/folded semantic-handle normalization, detector A/B vs A/B/C under a silent same-ID drift, and a declared detector-v2 control. H2 uses disjoint Monday/Tuesday validity occurrences with none, exact-ID, same-ref, changed-context and changed-value treatments, each queried at Tuesday noon and valid_at=None where applicable.","controls":"Canonical operation JSON and OpSet SHA-256 equality across paired contracts; exact case/group/result matrix; exhaustive 2/6/120 constructor permutations; fixed query, resolver, locale/timezone and serializer; source/paper/blob locks; complete pytest receipts; raw-payload rederivation; same-invocation fresh second pass; checked file-set manifest and clean source checkout.","rawResult":"The official suite collected and passed 139 tests with zero skips. Eight fixtures produced 17 same-contract permutation groups and 428 raw rows; every group had one state digest and one projection digest. H1 equality, ref-normalization, detector/lifecycle and declared-version strata matched their preregistered field-level expectations. H2 same-ref retraction deactivated both disjoint-validity claims; exact-ID and identity-changing controls preserved Tuesday. All eight primary files byte-matched the fresh second pass.","derivedResult":"At the exact 0.3.0 source, byte-identical immutable operations do not alone determine one materialized/projected view across different deterministic interpretation contracts. The tested differences can change conflict formation, effective semantic handles, activity, candidate membership, resolution applicability and projection. Default semantic-ref tombstones also cross validity occurrences that share semantic identity. Every tested fixed-contract constructor-permutation group produced one state digest and one projection digest; merge-tree equivalence and implementation-internal replay-path independence were not tested.","limitations":"The fixtures are deliberately small synthetic contract cases and do not estimate prevalence, harm or performance. The audit does not reproduce paper benchmarks, evaluate models/connectors, exercise distributed networking or concurrency, prove formal properties, label semantic-ref behavior incorrect, or establish that real deployments use mismatched contracts. Same-environment byte reproduction is not cross-platform reproducibility.","links":[{"label":"method, result and claim boundaries","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/statefuse-interpretation-contract-audit/README.md"},{"label":"frozen preregistration","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/statefuse-interpretation-contract-audit/PREREGISTRATION.md"},{"label":"reproducible runner","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/statefuse-interpretation-contract-audit/audit.py"},{"label":"raw-rederived decision","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/statefuse-interpretation-contract-audit/raw/decision.json"},{"label":"evidence-package readiness boundary","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/statefuse-interpretation-contract-audit/raw/readiness.json"},{"label":"fresh reproduction receipt","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/statefuse-interpretation-contract-audit/raw/reproduction.json"},{"label":"exact source manifest","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/statefuse-interpretation-contract-audit/raw/source_manifest.json"}]}],"keywords":["conflict-preserving memory","OpSet","semantic correction","interpretation contract"],"categories":["记忆架构","可靠性","信念修正"],"failureSurfaces":["state-representation","write-consolidation","justification-revision"],"sourceUrl":"https://arxiv.org/abs/2607.05844v1","pdf":{"delivery":"official","url":"https://arxiv.org/pdf/2607.05844v1","accessNote":"本站不重新分发这份 PDF；请从 arXiv official source 阅读 reviewed v1。"},"editorialQuestion":"如果 operations 已经 byte-identical，但 replicas 没有共同绑定 predicate registry、claim-ref derivation 与 detector implementation identity，我们究竟是在复制同一份 memory，还是只复制了同一份待解释的历史？","sourceNote":"arXiv v1，2026-07-07；PDF 共 18 页，essay locators 使用 printed PDF page numbers。official source audit 锁定 commit 79a6229… / StateFuse 0.3.0。repository paper/main.tex 是标题与实验叙述不同的 unpublished successor manuscript，已与 arXiv v1 分层；139-test receipt 与 428-row synthetic audit 只支持 current-source contract claims。"},{"number":19,"id":"fluctlightdb-observation-binding","kind":"paper","title":"FluctlightDB: A Memory Model of Data for AI Agents","authors":["Ganesh S"],"shortAuthor":"Ganesh S","year":2026,"doi":"10.48550/arXiv.2608.12365","noteDepth":"worked","readingScope":"完整读了 arXiv v1 的 abstract、§§1–8、Tables 1–9、Figures 1–5 与 references，共 16 个 PDF pages；另锁定 paper-time official source 593623eea50361e563180c112322e26d0ab4093b、current main d867f3cdbcffcefe4e14473333a78ce33a06ae47 与 official repair descendant f5d51e247b544503f8f47960b9dc6ecd43c2f464。对两条可执行 revision 各运行 unmodified official isolated/shared script 与两次 fresh-process six-treatment matrix，完整 reducer 产生 1,140 个 compact query rows；没有下载或复现 LoCoMo、LongMemEval、BEIR、FAMB corpus/result，没有调用 model、reader、judge、API、remote service、production runtime 或 private data。","intro":"FluctlightDB 把 `experience()` / `activate()` / `checkpoint()` 提成 database-native memory verbs，并把 provenance-aware ranking 放进 read semantics。但它自己的 shared-brain provenance suite 在排序之前已经缺少 query→observation identity：十个 cue classes 各用一个相同 query 对五个 incompatible target IDs 计 exact top-1；在本地复现的 within-store invariance 下，50-row scalar 条件性最多只能命中 10 行。source-linked controls 又露出排序之后的另一条 seam：`agent_id` retain 后，不接收 scope 的 wallet / successor exact helpers 可以重新插入 foreign stored episodes。","whyRead":"这篇值得做成 worked essay，不是因为“brain-native database”这个比喻够新，而是因为它把三个常被压成一个 accuracy 数字的 contract 拆了出来：query 是否指明 intended observation、已识别的 ledger/chat 怎样排序、final output 是否在所有 helper 之后仍满足 scope。official 9/50、45-case identity-bearing control 与 nonexistent-agent negative controls 合在一起，给出的不是一条安全 headline，而是一套能分辨 identification、ranking、candidate truncation 与 late reinjection 的读法。","keyPoints":["Data-model claim：论文把 relational row / predicate、vector embedding / nearest neighbor 与 agent-memory experience / cue activation 区分；write path 负责编码 content、context、salience、provenance 与 graph edges，read path 融合 lexical、semantic、graph 与 provenance scores。`experience()` / `activate()` / `checkpoint()` 是 embedded engine contract，不是对 Mem0、Zep 或 HippoRAG application layer 的直接替代。（Abstract；§§1–3.7；Figure 1，PDF pp. 1–6、15）","Paper evidence：arXiv v1 报告 LoCoMo evidence recall 99.0% @150、LongMemEval-S session recall@8 97.6%、LongMemEval-S E2E 97.4%、BEIR SciFact 0.646 nDCG@10 / 0.792 Recall@10，以及 author-designed FAMB/provenance regressions。metric、retrieval budget、reader/judge 与 harness 不同，不能折成一张 memory-quality 排名。（§§4.1–4.5；Tables 3–8；Figures 2–4，PDF pp. 7–12）","Structural ceiling：official shared fixture 的十个 domain 各有五个 distinct expected ledger IDs，却在同一 frozen store 上重复 byte-identical cue；五次 call 若 top-1 invariant，每类最多命中一个，故上限是 10/50。paper-time 与 repair-descendant unmodified runs 均为 isolated 50/50、shared 9/50，且十类全部 within-store invariant。（paper-time / repair-descendant official-source execution receipt；synthetic audit）","Identity-bearing control：45 个 non-wallet lexical-bound K=128 pairs 在两条 revisions × 两个 fresh repeats 中全部同时返回 intended ledger/chat，configured verified higher-salience ledger 为 45/45 above chat、0 chat-above-ledger、0 foreign-agent rows。该 treatment 同时保留 salience、confidence、context、source、verification 与 wording differences，所以不是 provenance-only causal estimate。（synthetic contract test）","Scope closure：两条 source lines 都在 global activation/sort/top-K 后 retain matching `agent_id`，再运行 unscoped wallet helper；repair/current 又运行 unscoped exact helper。wallet、repair exact-status 与 nonexistent-agent controls 返回 foreign stored `episode.agent_id`，shipping control 不返回 foreign rows。结论只到 exact local `agent_id` output-scope preservation，不扩成 tenant/auth/security/remote/production claim。（official-source + synthetic contract test）"],"argumentMap":[{"step":"01 · 先把 memory 变成 database contract","claim":"论文把 experience encoding、cue activation、provenance ranking、consolidation 与 durability 作为 engine-native primitives，要求 agent memory 不再只是 application 在 vector index 外围拼的隐式 pipeline。","locator":"Abstract；§§1–3.7；Tables 1–2；Figure 1，PDF pp. 1–6"},{"step":"02 · 再问 provenance suite 的 scorer 认识谁","claim":"official shared suite 把五个 incompatible ledger observations 放进一个 store，却对它们使用同一 cue 并轮换 exact-ID gold；在 ranking quality 之前，query 已经无法唯一标识 intended observation。","locator":"§4.3；Table 6，PDF pp. 8–9；official benchmark source"},{"step":"03 · 用 conditional theorem 而不是事后故事读 9/50","claim":"within-frozen-store five-call top-1 invariance 使每个 cue class 最多一行 exact-ID hit；本地 unmodified runs 验证 premise 与 9/50 observation。winner 可跨 fresh brain 改变，不影响 store-local 10/50 ceiling。","locator":"paper-time / repair-descendant official execution；raw/summary.json"},{"step":"04 · 给 pair 加 identity，仍不把 composite treatment 偷换成 provenance-only","claim":"neutral lexical key 让 intended ledger/chat 都进入 K=128 observable set；45/45 ledger-above-chat 排除了‘41 个 official misses 等于 41 个 observed pairwise provenance losses’，但多个 ledger/chat score inputs 同时不同，不能给 provenance field 单独归因。","locator":"public synthetic lexical treatment；raw/posttest-evidence.json"},{"step":"05 · 把 scope 当 pipeline 末端 postcondition","claim":"source 把 agent retain 放在 unscoped helpers 之前；foreign stored `episode.agent_id` 与 nonexistent-agent positives 证明 helper 能在 retain 后重新填充结果。scope 若要成立，所有 add/boost/expand paths 必须共享 scope 或在末端重新 fail closed。","locator":"paper-time/current `crates/fluctlightdb/src/brain.rs`；wallet/exact/shipping synthetic controls"}],"methodNotes":[{"label":"Paper architecture and metric separation","text":"essay 分开读 full episodic engine、index/CHORUS lanes、optional Recall Fabric、retrieval metric、E2E reader/judge 与 author-designed regressions；不把 LoCoMo @150、LongMemEval session@8、E2E QA、BEIR 与 FAMB 当同一个 construct。","locator":"§§3.5–3.7、4.1–4.5、5；PDF pp. 5–12"},{"label":"Exact source/build chain","text":"runner 在 import 前校验 exact commit、clean checkout 与七个 source blobs/hashes。paper-time 0.5.9 exact wheel 可构建；current-main 0.5.10 在 Python crate 调用未从 crate root re-export 的 `sync_once` 处以 Rust E0425 fail closed；official repair descendant 只恢复该 export，并以独立 runtime label 执行。","locator":"research/fluctlightdb-observation-binding-audit/raw/source-manifest.json；raw/current-main-build-receipt.md"},{"label":"Preregistered complete construction","text":"static preflight 固定 10×5 census、五个 distinct labels/class、tokenizer-stable `x000…x049`、wallet/exact router classification；每个 pair 必须取得 non-nil、non-rejected、non-deduplicated IDs，并在 full snapshot 中完整出现且保留 expected agent metadata。","locator":"research/fluctlightdb-observation-binding-audit/PREREGISTRATION.md；audit.py"},{"label":"Fresh-process matrix and logical reducer","text":"每个 treatment 独立 child process；两条 executable revisions 各跑六个 treatments × 两个 fresh repeats，再加四个 official runs。reducer 无条件处理完整 1,140 rows，以 stable aliases 比较 claim-level objects，保留 ambiguous winner、low-K set 与 paper-time ordinary K=1 instability。","locator":"research/fluctlightdb-observation-binding-audit/analyze_results.py；raw/compact-query-rows.json；raw/summary.json"}],"reportedFindings":["paper-reported：LoCoMo evidence recall 99.0% @150、LongMemEval-S session recall@8 97.6%、LongMemEval-S E2E 97.4%；paper 同时报告 LoCoMo 50-question E2E pilot 23.5% F1，并明确 retrieval 与 QA 指标不同。（Abstract；§§4.2、4.4–4.5、5；Tables 4–8，PDF pp. 1、7–12）","paper-reported：provenance-conflict suite isolated 50/50、shared 9/50；作者把 shared drop 归因于 cross-case cue contamination，说明尚无 mitigation，并不把 isolated figure 当 multi-tenant readiness evidence。（§4.3；Table 6；§5–6，PDF pp. 8–12）","official-source execution：paper-time 与 repair descendant 的 unmodified scripts 各自重现 isolated 50/50、shared 9/50；十个 shared cue classes 在各自 frozen store 内均为 single top-ID invariant，满足 conditional 20% ceiling premise。","synthetic contract test：四个 revision/repeat cells 各有 45/45 non-wallet K=128 rows 同时显示 paired observations、ledger above chat、0 chat-above-ledger、0 foreign rows；完整 selected population 是 180 rows，不把 repeats 当 180 个独立样本。","synthetic contract test：两条 revisions 的 50-case scoped wallet 10/10 queries 含 foreign `refund_4:ledger`；two-agent wallet winner 随 tied ingest order 反转，other-agent 与 nonexistent-agent queries 都接到 later-ingested stored ledger，cache repeated logical signatures invariant。","synthetic contract test：repair-descendant exact-status 的 A/B/nonexistent queries 全部含 foreign verified rows，nonexistent K=3 返回两 agents；paper-time nonexistent exact controls 稳定为空；shipping A/B 只返回 own pair、nonexistent 为空。"],"evidenceLimits":["本站没有下载、执行或独立重算 LoCoMo、LongMemEval、BEIR、FAMB result；paper 的 headline、baseline、公平性与 statistics 都保持 paper-reported。","conditional 10/50 theorem 只适用于 locked fixture 的 10×5 geometry 与 within-frozen-store top-1 invariance；它不证明 FluctlightDB 全局 deterministic，也不说明每个 shared-memory query 都需要相同 identity scheme。","45-case control 不是 verified/provenance field 的 matched ablation；ledger/chat 同时改变 salience、confidence、context、source metadata、verification 与 content，不能报告 provenance-only effect size、accuracy 或 reliability。","foreign `episode.agent_id` rows 证明 exact local output scope 不保留；paper/API 没有让本站把 `agent_id` 等同 tenant、authorization 或 security principal，且未测试 HTTP server、remote caller、production deployment、privacy incident、frequency、severity 或 harm。","current main exact source只产生 E0425 compile receipt；所有 successor runtime claims 属于 separately labeled official repair descendant。retrieval blobs matching current main 不把 descendant execution 变成 current-main execution。","K=3→K=128 rescued rows 每次存在但 case set/count 不稳，只与 global candidate top-K before late retain 一致；不能报告 stable low-K rate、universal failure 或唯一 causal stage。","full UUID-bearing raw snapshots/ingest reports保存在研究工作线而不随站分发；public artifact 提供完整 1,140-row normalized compact data、360 claim-selected rows、source/build manifests、runner/reducer 与 checked hashes，允许复算所有 public claims但不重建原始绝对路径/UUID bytes。"],"sourceTensions":[{"label":"Shared 9/50 同时混合 target identification 与 ranking","observation":"paper 把 shared drop 解释成 cross-case cue contamination；exact fixture 又让相同 store/cue 对五个 incompatible exact IDs 计分。本地 run 验证每类 single-winner premise，9/50 因而落在条件性 10/50 ceiling 内。","implication":"paper 的 contamination observation 仍可能成立，但 scalar 不能单独量化 pairwise provenance failure；未来 scorer 至少要分 wrong-ledger、chat-over-ledger、target-absent 与 underidentified query。","locators":["§4.3；Table 6，PDF pp. 8–9","official benchmark source","public official/source-linked audit"]},{"label":"Scope retain 后的 helper 可以改变 returned set","observation":"paper-time/current source 都在 agent retain 后调用 wallet helper；repair/current 又调用 exact helper。helpers 不接收 `agent_id`，而 nonexistent-agent controls 直接返回 stored foreign-agent episodes。","implication":"scope 不能只作为 pipeline 中段 filter；能 insert/boost/expand 的每个 path 都必须继承 scope，或由 final validator 对 actual returned episodes 重新 enforce。","locators":["paper-time/current `crates/fluctlightdb/src/brain.rs`","public wallet/exact/shipping rows"]},{"label":"arXiv 99.0 与 successor 96.8 必须分层","observation":"arXiv v1 headlined 99.0% LoCoMo @150；current official README/docs 后来把它标成 ±3 neighbor-expansion scoring artifact，改报 raw no-expansion 96.8% @150，并强调 @5 72.6%。","implication":"successor correction 提醒 reader 检查 scorer expansion 与 tight-k，但不能静默改写 v1 或被本站冒充独立 reproduction；二者必须分别用 paper-reported / current official-source labels。","locators":["arXiv v1 §4.2、§5，PDF pp. 7–11","current official README / docs/BENCHMARKS.md at d867f3c…"]}],"editorialInferences":[{"label":"Observation binding precedes trust ranking","text":"provenance、confidence 与 salience 只能在 query 已区分的 candidate observations 之间排序；若 scorer 自己轮换 target 而 retrieval input 不变，top-1 首先测的是 target contract 缺失。","boundary":"这是 locked fixture geometry、conditional theorem 与 identity-bearing controls 的 synthesis；不是 FluctlightDB 全局 ranking failure 或 universal query-schema prescription。"},{"label":"Scope is a closure property","text":"scope 的 operational identity 不是‘曾经 retain 过’，而是 pipeline 完成后每个 returned episode 都满足 scope，或者带有 explicit authorized bridge。任何 post-filter insert/boost/expand helper 都属于 scope contract。","boundary":"本地 test 只覆盖两个 helper families 与 Python/native `agent_id` surface；没有验证 tenant/security/remote/production policy。"},{"label":"Nonexistent-scope queries are causal controls","text":"当 requested agent 在 store 中没有任何 row，正确 retain 应为空；若 helper-positive query 仍返回 stored rows，candidate truncation 无法独自解释 reinjection。这个 negative control 比只看 matching-agent miss 更能定位 late add path。","boundary":"它定位 tested pipeline 的 source-supported mechanism，不估计其他 queries/helpers 的发生率。"},{"label":"Metric receipts need transformation lineage","text":"99.0→96.8 的 successor correction 与 shared 9/50 ceiling 都说明 headline 必须携带 raw target、retrieval budget、expansion、reader/judge 与 scoring identity；‘source available’不能替 transformation ledger。","boundary":"这是跨 paper/source tension 的 reporting proposal，不重算 LoCoMo，也不判定其他 benchmark 的 validity。"}],"openProtocols":[{"title":"Target-binding × provenance-only × scope-closure factorial","status":"proposed-not-run","question":"在 uniquely identified observations 上单独改变 provenance/verification 时，ranking effect 是否仍存在；scope 在 candidate generation、late retain 与 final postcondition 三种位置的 recall/foreign-row tradeoff 又怎样？","method":"构造 matched ledger/chat text、salience、confidence、context 与 source，分别只改变 verified/provenance；交叉 anonymous cue、lexical target key、agent scope 与 explicit authorized bridge。对 scope placement 运行 candidate-prefilter、existing late-retain、late-retain+final validator 三个 source-local treatments。","fixtures":"至少覆盖 non-helper numeric fact、wallet helper、exact-status helper、target-absent、nonexistent-agent、two-agent tied order 与 one declared cross-agent bridge；每个 fixture fresh store/process，并保留 actual returned episode metadata。","controls":"byte-identical content/score inputs、provenance-only pair、no-helper shipping、router-positive/negative、K sweep、forward/reverse order、cache repeat、source manifest、clean checkout 与 final returned-scope receipt；不使用 model、remote service 或 private trace。","measures":"分别报告 intended ledger/chat visibility、paired rank, wrong-ledger、foreign-agent、empty result、authorized bridge、K rescue 与 final postcondition；inferential unit 保持 fixture family，不把 repeated rows当独立样本。","limitations":"这是 proposed-not-run successor protocol。它不会从现有 45/45 composite treatment 推出 provenance-only effect，也不能把 `agent_id` 自动升级为 tenant/security authority。"}],"contributions":[{"type":"public-test","title":"Observation-binding ceiling and scoped-recall helper audit","byline":"Agent Memory Study editors","date":"2026-08-27","basis":"Paper-facing audit of arXiv:2608.12365v1, exact paper-time commit 593623eea50361e563180c112322e26d0ab4093b, exact current-main source/build receipt d867f3cdbcffcefe4e14473333a78ce33a06ae47, and separately labeled official repair descendant f5d51e247b544503f8f47960b9dc6ecd43c2f464, with the unmodified official script and newly authored model-free fixtures.","boundary":"This is a preregistered exact-source execution and synthetic output-contract audit. It is not a LoCoMo/LongMemEval/BEIR/FAMB reproduction, provenance-only causal experiment, tenant/authentication/security test, vulnerability finding, remote or production evaluation, privacy incident, or prevalence/severity/harm estimate. Repair-descendant runtime evidence is not current-main runtime evidence.","method":"Verify exact clean checkouts and source blobs; build/install paper-time and repair-descendant native wheels in isolated environments; run both unmodified official conditions; run ambiguous, scoped, lexical, wallet, exact-status and shipping treatments twice per executable revision in fresh child processes; fail incomplete ingest/snapshot/agent metadata; normalize UUIDs to stable aliases; reduce all four matrices without success filtering; and verify the complete compact/selected receipts and source/build identities by hash.","environment":"macOS 26.5.2 arm64；CPython 3.13.3；Rust/Cargo 1.98.0；maturin 1.15.0；paper-time native 0.5.9 and official repair-descendant native 0.5.10 in separate environments；initial child `FLUCTLIGHT_*` cleared, with only registered pre-connection overrides before official SDK mode defaults；no model, API, credential, private data, benchmark corpus, remote service or production runtime.","fixture":"Official 10-domain × five-variant provenance pairs; tokenizer-stable lexical keys x000…x049; agent-tagged 50-pair K=3/K=128 scope matrix; forward/reverse two-agent wallet; router-positive two-agent exact-status plus nonexistent agent; router-negative shipping plus nonexistent agent.","controls":"Exact paper/source/wheel identities; unmodified official scripts; conditional-ceiling premise checked per frozen cue class; full nonnil/nonrejected/nondeduplicated 100-engram construction where applicable; complete snapshot ID/agent metadata equality; wallet pre-exclusion from paired aggregate; K=3/K=128; forward/reverse order; same-store cache repeats; paper-time exact negative revision; shipping negative; complete 1,140-row reduction; 360-row claim selection; public source-delta and byte-reduction receipts.","rawResult":"Both executable revisions returned official isolated 50/50 and shared 9/50; every shared five-call cue class was within-store top-1 invariant. Each of four revision/repeat cells had 45/45 non-wallet lexical K=128 pairs with both rows visible, ledger above chat, no chat-above-ledger and no foreign-agent row. Every scoped wallet query returned foreign refund_4:ledger; two-agent wallet winner reversed with tied ingest order and populated a nonexistent agent. Repair exact-status populated A/B/nonexistent agents with foreign verified rows; paper-time nonexistent exact and both shipping nonexistent controls were empty. The complete reducer emitted 1,140 compact rows and 360 claim-selected rows; checked verification passed.","derivedResult":"The locked official shared exact-ID scalar is conditionally capped at 10/50 under the observed within-store invariance and cannot alone quantify pairwise provenance loss. The 45-case composite control rejects treating 41 official misses as 41 observed chat-over-ledger losses but does not isolate provenance. Stored-agent mismatches and helper-positive nonexistent-agent controls establish bounded post-retain output-scope failures for wallet and repair exact helpers, while negative controls preserve scope.","limitations":"Arbitrary tied winners and low-K rescued case sets vary across fresh brains; no stable low-K rate is reported. The audit does not isolate provenance, reproduce paper benchmarks, execute current main, test tenant/security/remote/production behavior, or estimate real-world prevalence or harm. UUID-bearing raw snapshots remain outside the site; complete normalized compact rows and every public-claim row are checked in.","links":[{"label":"method, result and claim boundaries","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/fluctlightdb-observation-binding-audit/README.md"},{"label":"frozen preregistration","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/fluctlightdb-observation-binding-audit/PREREGISTRATION.md"},{"label":"source-locked runner","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/fluctlightdb-observation-binding-audit/audit.py"},{"label":"complete compact query rows","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/fluctlightdb-observation-binding-audit/raw/compact-query-rows.json"},{"label":"complete normalized summary","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/fluctlightdb-observation-binding-audit/raw/summary.json"},{"label":"all public-claim selected rows","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/fluctlightdb-observation-binding-audit/raw/posttest-evidence.json"},{"label":"exact paper/source/wheel manifest","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/fluctlightdb-observation-binding-audit/raw/source-manifest.json"},{"label":"current-main build boundary","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/fluctlightdb-observation-binding-audit/raw/current-main-build-receipt.md"},{"label":"public reducer reproduction receipt","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/fluctlightdb-observation-binding-audit/raw/reproduction.json"}]}],"keywords":["memory database","observation binding","provenance ranking","scoped recall"],"categories":["记忆架构","可靠性"],"failureSurfaces":["state-representation","retrieval-active-context"],"sourceUrl":"https://arxiv.org/abs/2608.12365v1","pdf":{"delivery":"official","url":"https://arxiv.org/pdf/2608.12365v1","accessNote":"本站不重新分发这份 PDF；请从 arXiv official source 阅读 reviewed v1。"},"editorialQuestion":"如果 query 没有指明 intended observation，而 scope filter 之后的 helper 又能重新插入别的 agent 的 row，那么 provenance-aware top-1 究竟在排序可信证据，还是替 scorer 猜 target、替 pipeline 猜 permission？","sourceNote":"arXiv v1，2026-08-17；PDF 共 16 页。paper-time 0.5.9、current-main source/build failure 与 official repair-descendant 0.5.10 分层标注；paper headline 99.0% 与 successor official correction 96.8% 也保持版本边界。public audit 的 1,140 normalized rows只支持 conditional ceiling、official-format paired control 与 exact local `agent_id` output-scope claims。"},{"number":20,"id":"memora-from-recall-to-forgetting","kind":"paper","title":"From Recall to Forgetting: Benchmarking Long-Term Memory for Personalized Agents","authors":["Md Nayem Uddin","Kumar Shubham","Eduardo Blanco","Chitta Baral","Gengyu Wang"],"shortAuthor":"Uddin 等","year":2026,"doi":"10.48550/arXiv.2604.20006","noteDepth":"worked","readingScope":"完整读了 arXiv v1 的 Abstract、§§1–7、Limitations、Ethical Considerations、Appendix A–E、Tables 1–10、Figures 1–7 与 references，共 28 个 physical PDF pages；references 只用于 lineage 定位。另检查 official source current repair commit a6493188efc836d6511ed5e4163fe3ba87da30ff、它的 pre-repair parent e19ebbd1089465876dca11b09e70256977f9755f、30 份 released evaluation-question files、两条 FAMA implementation、两条 judge paths 与 aggregator，并执行先有本地 pretest freeze、后有明示 post-execution amendments 且按修订协议完成两次 fresh rerun 的 read-only / model-free contract audit。没有调用 model、judge、API 或 memory backend，没有生成 answer/eval report，没有运行四个 LLM 或六个 memory agents，也没有重建 Table 3；current official source 是 post-paper successor，不被称为 paper-time source。","intro":"Memora 把 long-term memory 从“历史里有没有那条信息”推进到“回答是否只服从当前仍有效的 memory state”：每个问题同时携带应出现的 memory-presence criteria 与应消失的 forgetting-absence criteria，再由 FAMA 把 stale-memory reuse 变成显式 penalty。但一条 forgetting-aware headline 仍依赖更长的 evidence chain——criteria 怎样从 trace 生成、三个 judges 是否真的形成三人 quorum、empty forgetting bucket 如何处理、question/task/report 怎样聚合、以及 published table 能否从 released evidence 恢复。本条 worked essay 正是在这些层之间保持边界。","whyRead":"这篇值得精读，不只是因为它给 forgetting 加了一个分数，而是因为它暴露出 memory revision 的评估对象：系统既要写入并 consolidate 多次 add/update/delete，也要在最终回答里不给旧状态继续投票。论文、Appendix rubric、current source 与 released inputs 放在一起读后，FAMA 不再是一个孤立公式，而是一份 end-to-end evaluation contract；任何 criteria、judge cardinality、empty-bucket policy 或 aggregation identity 的漂移，都会改变“忘得对不对”究竟在测什么。","keyPoints":["Benchmark geometry：Memora 用 10 个 professional personas、preference/activity/goal 三类 memory、add/update/delete/neutral sessions 与 explicit before/after traces 构造 weekly、monthly、quarterly histories，并以 Remembering、Reasoning、Recommending 三类问题测试 temporally current memory。Table 1 报告 consolidation 从 weekly 5.3 sessions 平均扩到 quarterly 28.4，mutation 从 2.7 扩到 14.8。（§§1、3.1–3.6；Tables 1–2；Figures 1–2，PDF pp. 1–5）","FAMA contract：每条 criterion 先被独立判定；question-level `MPA` 是 presence criteria 的满足比例，`FAA` 是 obsolete/deleted criteria 的 absence 比例，`lambda = N_forget / (N_presence + N_forget)`，再计算 `max(0, MPA - lambda * (1 - FAA))`。Table 3 对每个 task-duration 取 question-level FAMA aggregate 并归一到 [0,100]；Table 4 与 Table 5 又分别把三个 durations 或三个 tasks 相加，因此其量尺是 [0,300]，不能读成单一 percentage。（§4.2；Tables 3–5，PDF pp. 6–8）","Two validator contracts：construction-side auto-eval 要求三个 LLM 对 conversation grounding 全部同意才接受；evaluation-side 则让 GPT-4.1、Claude Haiku 4.5 与 Gemini 2.5 Flash 对单条 criterion 做 binary judgment，以 2/3 majority 决定结果。前者是 dataset admission gate，后者是 score observation protocol，不能因模型数相同就当作同一个 reliability claim。（§3.3；Figure 2，PDF p. 5；§4.2、Appendix B.5–C.1，PDF pp. 6、15–17）","Human estimand boundary：construction QA 的 5% stratified conversation sample 检查 trace grounding、旧信息重入与 dialogue quality；evaluation calibration 另取 100 条 criteria，刻意平衡为四种 LLM consensus patterns 各 25 条。Table 8 的 88.3% 是这个 balanced diagnostic sample 上三位 annotators 的平均 LLM-majority agreement，不是按 released corpus prevalence 加权的总体 agreement rate。（§3.3；Appendix B.5、C.2；Tables 8–9，PDF pp. 5、16、18）","Paper comparison boundary：Table 3 比较四个 direct-context LLMs 的 standard/reasoning runs 与六个 external-memory agents；memory agents 在 Table 4 的 Remembering aggregate 平均 119.45，高于两组 LLM 的 65.60/65.80，但 Recommending 不占优，Reasoning 仍低。它是 heterogeneous systems 上的 paper-reported criterion/judge aggregate，不是相同 retrieval budget、storage visibility、cost、latency 或 repeated-run uncertainty 下的 causal ranking。（§§4.1、5；Tables 3–5、10，PDF pp. 6–8、28）","Released-contract result：current official release 的 30 个 question files 含 600 questions 与 6,415 criteria（2,947 presence / 3,468 forgetting），少于 paper Table 2 的 7,054；全部 200 个 Reasoning questions 都没有 forgetting criterion，current code 因 `lambda=0` 将其 FAMA 退化为 MPA。release 没有 checked eval reports，因此 source-linked audit 只能验证 released-input geometry、FAMA arithmetic、judge/aggregation behavior 与 source repair，不能恢复 Table 3、模型效应或 paper-run provenance。（current official source / released-input census / public model-free audit）"],"argumentMap":[{"step":"01 · 把 long-term memory 从 recall 改写为 state maintenance","claim":"作者认为真实 personalized interaction 中 information 会被加入、更新、删除；benchmark 因而必须同时提高跨 session consolidation 与 mutation pressure，而不是只问能否找回一个旧 fact。","locator":"§1；Table 1；Figure 1，PDF pp. 1–3"},{"step":"02 · 先生成显式 memory trace，再生成 dialogue 与 questions","claim":"structured persona/memory seeds 驱动 session simulator，持续保存 before/after state；conversation 与 evaluation criteria 都回指这条 trace，并经 automated unanimity gate 与 human verification 才进入 benchmark。","locator":"§§3.1–3.6；Table 2；Figure 2；Appendix A–B，PDF pp. 3–5、13–16"},{"step":"03 · 把正确使用与正确遗忘拆成 criterion buckets","claim":"memory-presence criteria 要求 current valid information 出现，forgetting-absence criteria 要求 invalidated information 不出现；这一拆分使“答案里既有新状态又夹带旧状态”不再被 presence-only metric 当成完全正确。","locator":"§§3.5、4.2；Appendix B.5–C.1，PDF pp. 5–6、16"},{"step":"04 · 用 multi-judge majority 观测每条 criterion","claim":"三个 provider-diverse judges 在 temperature 0 下分别输出 yes/no，再以多数票形成 criterion result；Appendix 报 consensus、pairwise kappa 与 balanced human calibration，作为 judge reliability evidence。","locator":"§4.2；Appendix C.1–C.2；Figures 6–7；Tables 8–9，PDF pp. 6、16–18"},{"step":"05 · 逐层从 criterion 聚合到 question、task-duration 与跨轴总分","claim":"FAMA 用 question-specific forgetting weight 惩罚 absent-memory violation；Table 3 是 task-duration score，Table 4 跨 durations 求和，Table 5 则把三 tasks 的 presence aggregate 与 FAMA reduction 并列。每次聚合都改变 estimand 与量尺。","locator":"§4.2；Tables 3–5，PDF pp. 6–8"},{"step":"06 · 以 task/time asymmetry 反驳单一 memory capability","claim":"paper-reported results 显示 external memory 对 Remembering 更有利、Recommending 容许较宽的 plausible output、Reasoning 普遍低且随缺失 evidence 失败；作者据此把 consolidation、forgetting 与 task-specific retrieval 分开讨论。","locator":"§§5–7；Figures 3–4；Tables 3–5，PDF pp. 7–9"}],"methodNotes":[{"label":"Trace-grounded synthetic benchmark","text":"10 personas 的 preference/activity/goal entities 在 operational/temporal constraints 下经历 add、update、delete 与 neutral sessions。session manager、intent manager、flow manager 与 prompt manager 生成 dialogue；automatic grounding loop、三-validator unanimity 与 5% stratified human check 约束 conversation admission。","locator":"§§3.1–3.6；Figures 1–2；Appendix A–B；Tables 2、6–7，PDF pp. 3–5、13–16"},{"label":"Criterion-to-score pipeline","text":"每个 response 对一组 atomic presence/forgetting criteria 分别接受 yes/no judgments；question-level FAMA 再进入 task-duration macro aggregate。Table 4 与 Table 5 使用跨轴求和，reader 必须保留 per-question、[0,100] cell 与 [0,300] aggregate 三层单位。","locator":"§4.2；Tables 3–5，PDF pp. 6–8"},{"label":"Judge reliability layers","text":"construction gate 用 unanimity；evaluation gate 用 majority。Appendix C 对三位 LLM judges 报 agreement patterns 与 pairwise kappa，再让三位 humans 各自标注一个四-stratum balanced 100-case sample；这不等同于全 corpus human relabel。","locator":"§3.3；Appendix B.5、C.1–C.2；Figures 6–7；Tables 8–9，PDF pp. 5、15–18"},{"label":"Versioned official-source and release census","text":"public audit 把 arXiv v1、current official repair commit a6493188…、pre-repair parent e19ebbd…、30 released question files 与 absent eval reports 分开锁定；source history 只证明 repo 中 judge import fallback 的 defect/repair lineage，不证明 Table 3 使用了任何特定 revision。","locator":"research/memora-forgetting-contract-audit/PREREGISTRATION.md；raw/source_manifest.json；raw/census.json"},{"label":"Model-free contract matrix","text":"audit 运行 current official offline regression tests，并以 synthetic counters/records 独立覆盖 729 个 paper-equation positive-denominator fixtures、55 个 separately labeled source zero-bucket extensions、invalid direct-call boundary、report aggregation、judge initialization 与 runtime valid-quorum matrix；没有生成新的 semantic judgments 或 benchmark outputs。","locator":"research/memora-forgetting-contract-audit/audit.py；raw/fama.json；raw/aggregator.json；raw/judge_binding.json"}],"reportedFindings":["paper-reported：Table 2 给出 weekly/monthly/quarterly 各 150/150/300 questions 与 749/1,421/4,884 criteria；平均 sessions/persona 为 155/615/1,991，平均 memory operations 为 103.2/374.3/1,171.4。（§3.4；Table 2，PDF p. 4）","paper-reported：Table 4 中 memory agents 的 Remembering 三-duration aggregate 平均 119.45，两组 LLM 平均为 65.60 与 65.80；Recommending 则为 138.37 对 144.72/153.34，Reasoning 为 27.55 对 12.37/13.92。这些都是三个 [0,100] cells 的和，量尺 [0,300]。（§5；Tables 3–4，PDF p. 7）","paper-reported：Table 5 显示所有 systems 的 memory-presence aggregate 在 FAMA 下都被下调；monthly setting 中 MemoryOS/A-Mem 的 MPA aggregate 为 112.8/112.0、Nemori 为 105.4，但 forgetting reductions 为 28.4/29.5/15.4，使 Nemori 的 final aggregate 反超二者。（§5；Table 5，PDF p. 8）","paper-reported：75-case manual error analysis 每个 task 检查 25 个 errors；Recommending 中 16/25 被归为 outdated memory、7/25 为 partial preference retrieval，Remembering 中 18/25 为 partial retrieval，Reasoning 25/25 都涉及 incomplete retrieval。它是 selected error taxonomy，不是总体 error prevalence。（§6，PDF p. 9）","paper-reported：balanced 100-criterion human calibration 上，三个 annotators 与 LLM majority 的 agreement 为 88.0%、88.0%、89.0%，平均 88.3%；human-human pairwise agreement 为 93%–95%，kappa 为 0.86–0.90。（Appendix C.2；Tables 8–9，PDF p. 18）"],"evidenceLimits":["Memora 是 explicit-trace synthetic benchmark。论文自己限定 10 个 professional personas 与 preference/activity/goal categories，不覆盖真实 interaction 的 implicit updates、contradictory signals、social relationships、多用户 coordination 或长期 consent/privacy dynamics；“lower bound”是作者论证，不是本站验证的 deployment theorem。（Limitations，PDF p. 10）","Table 3 的四个 LLM、两种 inference settings 与六个 agents 没有共同的 storage/context/retrieval mechanism：direct-context histories 可被 chronological truncation，agents 使用 GPT-4o-mini answer backend 与不同 local/cloud/proprietary stores。论文不报 runtime、latency、cost 或效率，也没有把这些 rows 变成 mechanism-level causal comparison。（§4.1；Appendix E；Table 10，PDF pp. 6、27–28）","current official commit a6493188… 是 post-paper successor。在 fresh controlled、无 ambient `api_client` 的 historical probe 中，parent 的 Track-2 path 指向不存在的目录并把 ImportError 转为 single-judge fallback；current commit 的 fresh exact-helper probe 把 module/class 都解析到 `evals/model_eval/api_client.py`，但 upstream 仍采用 `sys.path.append` 与 unqualified import，存在 pre-cached/earlier-path shadowing。缺少 paper production run 的 exact source revision、raw reports 与 run manifest，因此不能声称 historical defect 进入 Table 3、推翻 paper scores 或改变 model ranking。","paper 的 FAMA 定义没有声明 empty presence/forgetting bucket policy。Appendix D.3 展示的 Reasoning example只有 presence criteria；released inputs 进一步显示全部 200 个 Reasoning questions 都是 zero-forgetting。current source 选择 `lambda=0`，令这些 questions 的 FAMA=MPA；这是 successor implementation policy，不是 paper 明说的 forgetting test。","released inputs 是 6,415 criteria，而 paper Table 2 是 7,054；release 又不含任何 checked eval report。没有 exact paper-run dataset manifest 时，差额不能被归因为 paper error、silent filtering 或 post-paper change，public audit 也不能从 current tree 重算 Table 3。","Appendix C 说明 invalid judge outputs 可在 retry 后被排除、全失败则判 incorrect，却没有完整规定只剩 1/3、2/3 valid judges 或 1–1 tie 时如何维持“三 judge majority”。current source 的 reduced-quorum behavior 因而只能作为 successor executable contract 报告，不向 paper reliability figures反向转移。","Table 8 的四个 consensus strata 被强制各取 25 cases；88.3% 对 disagreement-heavy sample 有诊断价值，但不是按 Figure 6 / released corpus consensus prevalence 加权的 accuracy、也不是 judge unbiasedness 或 human equivalence 证明。","Appendix D.2 的 desired response 直接说用户正在 `leaning away from James Stewart`，相邻 expected-No criterion 却要求 response 不得 `reflect or mention` James Stewart。它是一个明确 rubric tension；单例不能估计 dataset-wide contradiction rate、judge error 或对 Table 3 的影响。"],"sourceTensions":[{"label":"Three judges 不等于固定三人 quorum","observation":"paper 把 evaluation 写成三 judges 的 2/3 majority，并强调 no single judge can decide；current source repair 后 Track 2 在 strict mode 才对 0/3、1/3、2/3 fail closed，默认 runners 仍允许显式 single-judge downgrade。Track 1 接受 1/3 或 2/3 initialization；两 tracks 在 per-criterion errors 后都对剩余 valid judges 投票。","implication":"judge protocol identity 必须同时记录 configured、initialized 与 per-criterion valid quorum。‘multi-judge enabled’或 current offline tests PASS 不足以证明每个 published judgment 经过三人 majority。","locators":["§4.2；Appendix C.1，PDF pp. 6、16–17","official source a6493188… Track 1 / Track 2 evaluator paths","public raw/judge_binding.json"]},{"label":"Empty forgetting bucket 改变 FAMA 的含义","observation":"paper 公式定义 FAA 为 forgetting-absence satisfied fraction，却没有给 N_forget=0 的取值。Appendix D.3 的 Reasoning example没有 forgetting criteria；released census 显示全部 200 个 Reasoning questions N_forget=0。current source 令 FAA=1、lambda=0，于是 FAMA=MPA。","implication":"这些 Reasoning cells 测 consolidation/presence 而不施加 forgetting penalty；跨 task 比较 FAMA 时，应同时公开 zero-forgetting coverage 与 bucket policy，不能把同名 score 自动当成同一 forgetting exposure。","locators":["§4.2，PDF p. 6","Appendix D.3，PDF pp. 24–27","public raw/census.json；raw/fama.json"]},{"label":"Paper inventory 与 current release 不是同一 evidence object","observation":"paper Table 2 报 7,054 criteria；current release census 为 6,415。official tree 有 question inputs 与 headline README table，却没有 eval reports/results，且 source revision 晚于 paper。","implication":"current release 适合 audit input geometry 与 executable contracts，但没有 exact dataset/run provenance 就不能被当作 Table 3 reproduction package；paper number 与 current census 必须并列，而不是择一覆盖。","locators":["Table 2，PDF p. 4","official current data/evals source","public raw/census.json；raw/source_manifest.json"]},{"label":"Desired response 与 expected-No wording 相撞","observation":"Appendix D.2 Session 132 的 desired response 通过‘leaning away from James Stewart’解释为什么推荐 Joan Crawford；相邻 criterion 却问 response 是否 `reflect or mention` James Stewart，expected answer 为 No。","implication":"若 judge 采用 literal mention，oracle-style desired response 会违反 criterion；若采用 semantic alignment，criterion wording 又过宽。criteria 应区分 endorse/use、historical contrast 与 bare mention，而不能把三者压进一个 No。","locators":["Appendix D.2，PDF pp. 23–24"]},{"label":"Balanced human agreement 不是 corpus-weighted reliability","observation":"Table 8 强制从 unanimous yes、majority yes、majority no、unanimous no 各抽 25 条；Figure 6 同时显示真实 consensus patterns 并非等比例。88.3% 是四 strata 等权平均。","implication":"该设计能放大分歧 cases、诊断 ambiguity，但若要陈述部署期总体 agreement，必须按目标 population prevalence 重新加权并给 sampling uncertainty。","locators":["Figures 6–7；Appendix C.2；Tables 8–9，PDF pp. 17–18"]}],"editorialInferences":[{"label":"Forgetting is a pipeline property","text":"一个系统是否‘会忘’不只由 store 删除旧记录决定；criteria construction、answer packet、judge semantics、quorum 与 score aggregation 都能让 obsolete memory 被看见、漏看或错误计权。FAMA 应与整条 observation chain 一起版本化。","boundary":"这是 paper criterion design、source tensions 与 public contract audit 的 architecture synthesis；不是对任何 Table 3 system 的 hidden mechanism 诊断或因果归因。"},{"label":"Negative criteria carry revision authority","text":"presence criterion 说明什么信息应进入回答，forgetting criterion 则决定哪些旧状态已经失去 answer authority。后者不是普通 negative example，而是 benchmark 对 update/delete semantics 的可执行解释。","boundary":"Memora 的 explicit traces 支持这一读法；真实用户 correction、withdrawal、coexisting preferences 与 legally significant erasure 可能需要不同 authority model。"},{"label":"Quorum belongs in every score receipt","text":"每条 criterion 的 receipt 至少要携带 configured judges、initialized judges、valid returned judges、vote split、retry/fallback path 与 criterion identity；只有 aggregate FAMA 无法证明 observed judgment 遵守 advertised majority protocol。","boundary":"current source 显示该 provenance 的必要性，但本站没有 paper-run receipts，不能推断 published rows 实际经历了 reduced quorum。"},{"label":"Same FAMA label can hide different task contracts","text":"当 Reasoning 的 N_forget 全为零时，FAMA 等于 MPA；Remembering/Recommending 则同时受 presence 与 forgetting penalty。task-level FAMA 横向比较前，应先报告 criterion composition、zero-bucket rate 与 aggregation weights。","boundary":"这是 current released-input geometry 下的 metric interpretation；它不否定 Reasoning task，也不证明加入 forgetting criteria 必然改变任何 model ranking。"},{"label":"Release completeness is part of benchmark legibility","text":"code、input questions 与 headline table 仍不足以独立检查一个 judge-based benchmark；最小 evidence package 还需要 exact run/source/data identities、criterion-level verdicts、quorum receipts 与 deterministic aggregation manifest。","boundary":"current release 的缺件只限制 independent reconstruction；它不证明 authors 没有保存内部 runs，也不把 unavailable provenance 等同 fabricated result。"}],"openProtocols":[{"title":"Quorum-bound FAMA and paper-run provenance protocol","status":"proposed-not-run","question":"当每个 criterion 都要求 fixed 3/3 initialized judges 与 at least 2/3 valid majority，并把 empty-bucket policy 和 report identity绑定进 receipt 后，哪些 paper-reported task/duration cells、forgetting reductions 与 rankings仍可由 exact run artifacts恢复？","method":"由 authors 或 future release 提供 exact paper source/data commits、question files、responses、三 judge raw outputs、retry/error states 与 report manifests；先按 declared three-judge quorum fail closed，再独立重算 criterion verdict、question FAMA、task-duration cells、Table 4/5 aggregates，并与 published tables 做 cell-level reconciliation。另行计算 balanced human sample 与 target-population-weighted agreement，禁止用 current source生成替代 paper outputs。","fixtures":"paper-run immutable manifests；全部 criterion-level raw judge responses；zero-forgetting Reasoning questions；有 1/3、2/3、3/3 valid outputs 的 deterministic routing cases；Appendix D.2 James Stewart mention/use contrast；current release 仅作为 versioned comparison object。","controls":"exact source/data/report hashes、one report per declared subject/persona/cell、no duplicate timestamp weighting、3/3 initialization positive、judge-loss fail-closed negatives、literal-mention versus semantic-use rubric controls、question-weight/report-weight reconciliation、paper/current release separation。","measures":"report criteria/questions/personas coverage；quorum-valid fraction；retry/fallback counts；per-question MPA/FAA/FAMA；zero-forgetting rate；Table 3 cell delta；Table 4/5 scale-aware delta；rank stability；balanced 与 population-weighted human agreement及 uncertainty。","limitations":"这是 proposed-not-run provenance/recalculation protocol，需要未随 current release 提供的 paper-run artifacts；它不授权重新调用 judge APIs、不能从 current successor source猜测 historical execution，也不会把任何差异自动解释为 paper invalidation或 real-world memory effect。"}],"contributions":[{"type":"public-test","title":"Judge-protocol binding and forgetting-contract audit","byline":"Agent Memory Study editors","date":"2026-08-29","basis":"Paper-facing audit of arXiv:2604.20006v1, exact current official repair commit a6493188efc836d6511ed5e4163fe3ba87da30ff, its direct pre-repair parent e19ebbd1089465876dca11b09e70256977f9755f, both evaluator tracks, the exact aggregator and all 30 released evaluation-question files.","boundary":"This exact-revision source execution began under a privately held pretest preregistration. The public-safe protocol record was derived after execution and explicitly separates later reviewer-driven amendments; the checked evidence was then rerun twice under the amended protocol. It is not a benchmark reproduction, model or memory-system evaluation, effect/prevalence estimate, paper-production source identification, Table 3 reconstruction, paper-result invalidation, or evidence that the historical fallback occurred in any paper run. Current successor behavior does not retroactively become paper-time behavior. The raw decision is scoped to one complete fresh run; package acceptance additionally requires the two-run reproduction receipt and installed-tree verifier.","method":"Lock the 28-page paper and clean current/direct-parent Git identities; run the five selected official offline tests from a temporary Git-archive export; exercise source-exact historical/current judge initialization and runtime-valid-quorum paths with isolated fake clients; record the current fresh exact-helper module/class origin and the remaining import-shadowing mechanics; AST-extract both FAMA functions and the aggregator; compare the 729 positive-denominator FAMA fixtures against an independent Fraction oracle and separately test 55 source-defined zero-bucket extensions; census every released question/criterion and result path; locate the Appendix D.2 criterion; then repeat all 11 primary outputs in a second fresh root and byte-compare them.","environment":"Darwin arm64；CPython 3.13.3；exact clean official checkout and exact arXiv v1 PDF；official pytest executed from a temporary source export with bytecode/cache disabled；allowlisted child environment with inherited API credentials removed and Python DNS/connect/sendto blocked；no model, LLM judge, memory backend, embedding service, API or network endpoint called.","fixture":"Current and pre-repair evaluator/aggregator source blobs；30 released evaluation files；0/1/2/3 initialized-client matrices under Track-2 strict/non-strict and Track-1 current behavior；0/1/2/3 valid-runtime-judge matrices；729 paper-equation-domain positive-denominator FAMA fixtures plus 55 separately labeled source zero-bucket extensions with totals 0..6, all 156 released counter-pair corners and one separately labeled out-of-domain call；synthetic unequal/duplicate/missing report rows；paper physical-page anchors for formula, Table 2 and Appendix D.2.","controls":"Exact paper/source/tree/blob/file hashes；direct-parent and clean-worktree gates before/after；no ambient `api_client` in the historical path；fresh-process current exact-helper module/class origin receipt；explicit `sys.path.append` plus unqualified-import shadowability ceiling；source-exact AST plus an independent Fraction oracle only where the paper equation has positive denominators, with source zero-bucket conventions tested separately；strict/non-strict paired initialization；runtime judge-loss matrix；file-local/composite identity checks；paper-versus-release census separation；zero checked-result inventory；official export file-set/write/cache receipt；two fresh output roots with 11/11 byte-identical primary receipts；complete artifact checksum coverage and no unlisted build residue.","rawResult":"The five selected official offline tests passed with no export mutation/cache residue. The release contains 30 files, 600 questions and 6,415 criteria: 2,947 presence and 3,468 forgetting-absence, versus paper Table 2's 7,054; all 200 Reasoning questions have zero forgetting criteria. File-local/composite IDs are unique, while bare IDs form 38 question and 178 criterion collision groups. In the isolated no-ambient historical probe, pre-repair Track 2 targeted a nonexistent judge path and converted ImportError to `use_multi_judge=False`. At the current commit, a fresh exact-helper probe resolved both `api_client` and `OpenRouterClient` to `evals/model_eval/api_client.py`; however, upstream still uses `sys.path.append` plus an unqualified import and remains shadowable by a pre-cached or earlier-path module. Initialization matrices used deterministic fake constructors, not real backend clients: non-strict Track 2 downgrades 0/1/2 initialized clients to single-judge while strict accepts only 3/3; Track 1 accepts 1/3 and 2/3, and both tracks vote over 1/2/3 surviving valid judges. Both exact FAMA functions matched an independent Fraction oracle over 729 positive-denominator paper-equation fixtures; 55 source zero-bucket extensions separately matched the released implementations, and all 156 released counter-pair corners matched source behavior. The separately labeled invalid call `(3,2,0,0)` returned 1.5. The tree has zero checked eval-report/result population, and all 11 primary receipts byte-matched across two fresh runs.","derivedResult":"The current repair binds Track-2 initialization cardinality only when strict mode is enabled; Track 1 and both runtime paths still permit reduced valid-judge quorums. FAMA arithmetic matches the reported equation where both denominators are positive and separately matches released-source zero-bucket conventions, which the paper does not define; the standalone functions do not validate the counter domain or upper-clamp invalid inputs. The aggregator is an unweighted mean of report-level task FAMA rows and enforces neither completeness nor deduplication. The 639-criterion paper/release difference is input-census drift, not result invalidation; without exact paper-run data/source/reports, Table 3 and model effects remain unreconstructed. Appendix D.2 contributes one mention-versus-reliance specification tension, not observed judge behavior or corpus prevalence.","limitations":"Synthetic clients/counters/reports test executable contracts, not semantic answer quality or real judge reliability; the initialization matrices use fake constructors and do not construct real backend clients. The pretest freeze is private/local, while the public-safe protocol record and amendments were derived after execution; the public file is not a contemporaneously published preregistration. The current import-origin receipt is a fresh controlled-process observation, while upstream path mutation and unqualified import remain shadowable. The selected five official tests are not a full integration suite. No released response or verdict population exists to recompute Figure 6/7, Table 3, balanced human agreement or rankings. The out-of-domain FAMA probe is not reachable evidence from released call-site counters. Bare-ID collisions matter to cross-file joins but do not show per-file scoring corruption. The raw decision covers single-run completeness; package acceptance depends on the separate two-run reproduction and installed-tree verifier. Same-machine byte identity is not cross-platform reproduction, and current source remains a post-paper successor.","links":[{"label":"method, results and claim ceiling","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memora-forgetting-contract-audit/README.md"},{"label":"public protocol record and dated amendments","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memora-forgetting-contract-audit/PREREGISTRATION.md"},{"label":"source-locked runner","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memora-forgetting-contract-audit/audit.py"},{"label":"single-run bounded decision summary","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memora-forgetting-contract-audit/raw/decision.json"},{"label":"complete released-question census","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memora-forgetting-contract-audit/raw/census.json"},{"label":"judge initialization and runtime quorum matrices","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memora-forgetting-contract-audit/raw/judge_binding.json"},{"label":"FAMA paper-domain, source-extension and boundary matrix","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memora-forgetting-contract-audit/raw/fama.json"},{"label":"aggregation contract fixtures","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memora-forgetting-contract-audit/raw/aggregator.json"},{"label":"exact source manifest","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memora-forgetting-contract-audit/raw/source_manifest.json"},{"label":"two-run byte reproduction receipt","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memora-forgetting-contract-audit/raw/reproduction.json"}]}],"keywords":["long-term memory benchmark","forgetting-aware evaluation","memory mutation","judge quorum","FAMA"],"categories":["可靠性","信念修正"],"failureSurfaces":["write-consolidation","justification-revision"],"sourceUrl":"https://arxiv.org/abs/2604.20006v1","pdf":{"delivery":"official","url":"https://arxiv.org/pdf/2604.20006v1","accessNote":"本站不重新分发这份 PDF；请从 arXiv official source 阅读 v1。"},"editorialQuestion":"如果一个 benchmark 用 forgetting criteria 赋予旧 memory ‘不得再支配回答’的 revision authority，却没有把 empty bucket、judge quorum、criterion wording 与 exact report provenance 一起锁进 score receipt，那么同一个 FAMA 数字究竟证明系统忘掉了什么，还是只证明 evaluator 在某条未完整公开的路径上没有看见它？","sourceNote":"arXiv v1，2026-04-21；ACL 2026 Findings；PDF 共 28 个 physical pages。current official repair commit a6493188… 是 post-paper successor；pre-repair defect/current repair lineage、current tests 与 30-file released-input audit均按 source/release evidence 单列，不被称为 paper-time execution。paper Table 2 的 7,054 criteria 与 current release 的 6,415 并列保留；zero checked eval reports使 Table 3 仍是 paper-reported而非本站重建。"},{"number":21,"id":"memprobe-hidden-user-state-recovery","title":"MEMPROBE: Probing Long-Term Agent Memory via Hidden User-State Recovery","authors":["Enze Ma","Yufan Zhou","Wei-Chieh Huang","Jie Yang","Huanhuan Ma","Zixuan Wang","Chengze Li","Chunyu Miao","Philip S. Yu","Zhen Wang"],"shortAuthor":"Ma 等","year":2026,"kind":"paper","noteDepth":"worked","readingScope":"完整读了 arXiv v1 的 Abstract、§§1–5、Limitations、Broader Impact、Appendix A–J、Tables 1–15、Figures 1–4 与 references，共 32 个 physical PDF pages；references 只用于 lineage 定位。PDF 通过 32-page reader preflight，并对 title page、Tables 2–4、Appendix J polarity case 与最后使用页做了 rendered visual inspection。另检查 official release commit 19bb83644b082489b4e181e59f1cded1a00d0529 的 50-user hidden bank、1,550 registered targets、task/history/final-memory/reconstruction/attribution/aggregate artifacts、scorer、failure-attribution path 与九个 released run identities，并执行 offline、standard-library、fixed released-artifact audit：13,950 target-join rows、13,950 attribution rows、6,200 retrieve-packet rows、30,379 packet-item rows、6,200 paired historical artifact deltas与16份primary receipts。没有运行 simulator、assistant、memory writer、retriever、slot filler、judge、attribution model、OpenAI endpoint 或 Mem-T/vLLM；没有重新生成 trajectory、重发 historical retrieval、重新判断任何 synthetic target 或复现 paper experiment。固定 JSON 中的 prediction、score、reason、disclosure verdict 与 attribution stage 都保留为 historical LLM artifacts。","categories":["可靠性","记忆架构"],"failureSurfaces":["state-representation","retrieval-active-context"],"sourceUrl":"https://arxiv.org/abs/2606.24595v1","pdf":{"delivery":"official","url":"https://arxiv.org/pdf/2606.24595v1","accessNote":"本站不重新分发这份 PDF；请从 arXiv official source 阅读 reviewed v1。"},"doi":"10.48550/arXiv.2606.24595","keywords":["hidden user state","memory recovery","retrieval audit","artifact provenance"],"sourceNote":"arXiv v1，2026-06-23；preprint，PDF 共 32 个 physical pages。official release audit 锁定 commit 19bb83644b082489b4e181e59f1cded1a00d0529；repository 无 tag 或 GitHub Release，故 exact commit 是本站 source identity。paper-reported result、official-source observation、released historical LLM artifact、fixed-artifact recalculation 与 AMS-authored synthetic control 分层标注。top-level code 与 generated benchmark artifacts 的 CC BY 4.0 不覆盖 vendored A-Mem、Mem-T、外部 taxonomy、model weight 或 API service；本站不复制 hidden bank、task、transcript、memory content、prediction/rationale 等 upstream free text。","intro":"MEMPROBE 把长期记忆的评估对象从“agent 后来答得对不对”移到“普通协作结束后，系统究竟留下了什么可恢复的 user state”。论文的 50 个 simulated users、31 个 hidden dimensions 与 full-store / top-k 双 read mode，让 task success、written artifact 与 operational retrieval 被放在同一条 evidence-loss chain 上。它也不能被读得太快：full-store recovery 仍经过 serialization、context budget、slot filler 与 LLM judge；top-k recovery 又叠加 fixed abstract query；failure attribution 则是 stored historical LLM stages 的阈值化 reduction，不是对 write、read 或 causal cause 的直接观测。本站的 fixed released-artifact audit 因此不重新判“记住了什么”，而只检查 exact release 内哪些 joins、score reductions、packet-to-store bindings 与 attribution reductions 可由固定 bytes 机械验证，以及哪些 historical execution edges 仍没有 provenance。","whyRead":"这篇最适合从一次 answer failure 倒推，因为它明确给出三段 loss path：hidden state 是否在 interaction 中 expose、evidence 是否被 collect 成 final store、stored evidence 是否能在 recover 时进入 active context。但 close read 与 source inspection 也暴露出一个更深的 reliability lesson：benchmark 自己同样是一条 observation pipeline。只要 full-store payload、retrieved packet、slot-fill response、judge request 或 attribution input 没有 exact binding，一个低分就不能直接命名为 write failure、retrieval failure 或真实 causal cause。MEMPROBE 最有价值的地方不是替我们完成归因，而是逼 memory evaluation 把每条 inference edge 写清楚。","editorialQuestion":"当一个 hidden user-state target 在 top-k mode 下得分变低时，我们能从 released artifacts 精确确认的是 target join、stored packet membership、historical score arithmetic，还是只能看到一条经过 query、serialization、slot filling、judging 与 attribution 后的终点标签？","keyPoints":["Paper protocol：每个 simulated user 携带一个不向 agent 暴露的 31-dimension user-state bank；普通 assistance tasks 只给相关 dimension 一个自然 disclosure opening。论文把信息路径写成 hidden state u → exposed evidence e → final memory m_final → reconstruction û，并把 task success 与 post-interaction artifact recovery 分开。（§§1、3.1–3.3；Figures 1–2，physical PDF pp. 1–6）","Metric contract：slot filler 在 full-store dump_all 或 system-native top-k=5 packet 上生成 per-dimension prediction，另一个 LLM judge 给出 {0, 0.25, 0.5, 0.75, 1} score；headline B 先在五个 categories 内求均值，再对五个 category means 等权平均，不是 31 dimensions 的 micro mean。（§3.4；Appendix F；Table 9，physical PDF pp. 6、23–24）","Paper result：五个 settings 的 immediate task completion 约为 99.87%–99.94%，连 nomem 也近乎饱和；三个 context-fit systems 的 full-store B 为 0.611–0.624，top-k B 降至 0.473–0.540。Assistance Preference 最容易恢复，Episodic Memory 最难；memt full-store B=0.130 被作者单列为 serialized store 超出 reader context 的 diagnostic auditability outcome。（§§4.2–4.5；Tables 2–4，physical PDF pp. 7–9）","Paper boundary：Appendix J 的 user_022 / pushback_tolerance 表明同一种“欢迎具体纠正”的 behavior 可因 directional label 被写成 high 或 low pushback tolerance 而得到相反 verdict；作者明确把它归为 slot-label polarity boundary，不是 headline memory failure。Appendix G 的 attribution human audit 是 stratified 120-case sample，overall agreement 90/120，原 Memory row 的 exact agreement 20/30；相近 aggregate distribution 不能替代 casewise causal truth。（Appendices G、J；Tables 11–12，physical PDF pp. 24、28）","Fixed-artifact audit：exact release 注册 1,550 个 user/category/dimension targets，并将其投影为九个 runs 的 13,950 target-join rows；另检查 13,950 attribution rows、6,200 retrieve-packet rows、30,379 packet-item rows与6,200 full/retrieve paired historical artifact deltas。raw/decision.json 只记录 single-run fixed-artifact gates全部为true、packet_unique_binding=PASS、stored_output_observability=COMPLETE_TYPED_INVENTORY、attribution_input_observability=PARTIAL、source_replay_material_status=BLOCKED 与 historical_execution_replay=NOT_ATTEMPTED，并明确保留 PENDING_REPEATABILITY_AND_SOURCE_BOUND_REVALIDATION；raw/comparison.json 另行记录两份16-file primary manifests byte-identical、distinct recorded hash seeds 与 runner_repeatability=PASS；再单独执行 source-bound verifier，结果为 PASS: source-bound revalidation; worked_fixed_artifact_audit=PASS。这三种 provenance surface 不能互相冒充，也不能从 paper tables 或手工 reconnaissance 回填。"],"argumentMap":[{"step":"01 · 先把行为成功与 memory artifact 拆开","claim":"task completion 可以来自当前 context、assistant scaffold 或 lucky completion，而不要求 durable user model；MEMPROBE 因此在 trajectory 结束后直接 probe final store 能否重建 hidden dimensions。","locator":"§§1、3.1、4.2；Figure 1；Table 2，physical PDF pp. 1–4、7–8"},{"step":"02 · 再把 artifact loss 分成 expose、collect 与 recover","claim":"论文用 u → e → m_final → û 表示三段可能的信息损失，并以 leak-controlled task、persistent memory rollout 与 reconstruction scorer 分别承接这三段；这比把一次 wrong answer 直接叫作 memory failure 更有诊断力。","locator":"§§3.1–3.5；Figure 2，physical PDF pp. 4–6"},{"step":"03 · 用两个 read operators 暴露 stored 与 reachable 的差别","claim":"dump_all 读取 serialized final store，retrieve 读取系统对 fixed axis query 返回的 top-k=5 packet。两者的 fixed historical score gap 能提示 read-path seam，但因为 slot filler、judge、context budget 与 independent run artifacts仍在链上，它本身不能识别 retrieval path 的 causal contribution。","locator":"§§3.1、3.4、4.3–4.4；Appendix F，physical PDF pp. 5–9、23–24"},{"step":"04 · 把 score 与 attribution 当作有版本的 measurement contracts","claim":"B 是 historical LLM judge quarter-step outputs 的 category-balanced reduction；attribution 又先用 0.75 threshold 决定哪些 cases 进入 Stage 0–2。stored label 可以与 stored stages 机械一致，却仍不能证明 stage judgment 或 final causal category为真。","locator":"§3.5；Appendices A、F–G；Tables 9–12，physical PDF pp. 6、14、23–25"},{"step":"05 · 最后审计 release 能证明哪些 edge","claim":"本站 checker 只把 exact target/task/reconstruction identities、fixed-score arithmetic、stored packet 对 designated final dump 的 typed membership/binding、stored attribution stage reduction 与 replay-material inventory作为 model-free gates；target support、historical prompt payload、semantic correctness、causal cause 与 retriever replay保持 NOT_TESTED、UNVERIFIABLE 或 NOT_ATTEMPTED。","locator":"research/memprobe-recovery-boundary-audit/PROTOCOL.md；raw/decision.json；raw/target_registry.json；raw/target_joins.jsonl；raw/replay_inventory.json"}],"methodNotes":[{"label":"Hidden-bank and task construction","text":"paper 为每个 user 固定 31 个 synthetic target dimensions，按 Skill / Knowledge / Episodic 各 7、Self Model / Assistance Preference 各 5 分布；每个 dimension 配一个 indirect assistance task，并以只看 task statement 的 anti-fishing critic 拒绝直接泄露 target 的设计。hidden bank 是 benchmark scoring target，不是 psychometric claim 或 independently established real-world truth。","locator":"§3.2；Appendices C–E；Table 8，physical PDF pp. 5、16–22"},{"label":"Simulation and memory-conditioned trajectories","text":"N=50、T=31、25-turn cap；task set、simulator prompt、assistant scaffold 与 dialogue protocol across systems 固定，只替换 memory module。memory reads 会改变 assistant replies，因此不同 systems 的 transcripts 可以分叉；paper 将这种分叉视为 memory-conditioned loop 的一部分。","locator":"§§3.3、4.1；Appendices C、E，physical PDF pp. 5–7、16–22"},{"label":"Recovery, aggregation and access modes","text":"每个 dimension 由 slot filler 从 dump_all serialization 或 native search(query,k=5) packet 生成 label/reason，再由 separate recovery judge按五级 rubric评分。每个 user 的 B 是五个 category means 等权平均；Tables 2–3 再对 50 users 报 mean ± sample standard deviation。","locator":"§3.4；Appendix F；Tables 2–3、9，physical PDF pp. 6–8、23–24"},{"label":"Thresholded failure-attribution pipeline","text":"score ≥0.75 直接标 ok；其余依次经过 task-design oracle、transcript disclosure judge 与 elicitation-versus-strictness subclass judge。access mode 改变 threshold-entry population，paper也提醒 retrieve rows 中的 Task/Agent/User counts不能被读成 task或simulator本身发生了变化。","locator":"§3.5；Appendix F；Tables 4、10，physical PDF pp. 6、8、23–24"},{"label":"Frozen fixed released-artifact audit","text":"independently authored standard-library runner拒绝 wrong/dirty source，穷举1,550-target registry与九个run-bound projections，以 exact typed joins、Fraction arithmetic、四套 frozen system adapters、stored-stage truth table 与 historical-provenance inventory生成 public-safe receipts；deny-listed upstream free text仅保留 locator、count、enum 与 SHA-256。complete audit在两个 fresh processes / roots / output dirs及不同 PYTHONHASHSEED下重跑，并由 source-bound verifier重新读取 exact checkout与paper PDF。","locator":"research/memprobe-recovery-boundary-audit/README.md；PROTOCOL.md；raw/input_manifest.json；raw/comparison.json；verify_checked.py"}],"reportedFindings":["Paper-reported：nomem、amem、longctx_full、mem0、memt 的 task completion 为 99.871%–99.935%；nomem 的 B=0，而 amem / longctx_full / mem0 的 full-store B 分别为 0.611、0.624、0.613。near-perfect immediate assistance 因此不能区分 durable memory formation。（§4.2；Table 2，physical PDF pp. 7–8）","Paper-reported：top-k B 为 amem 0.540、longctx_full 0.503、mem0 0.473、memt 0.465；context-fit systems 的 full-store 到 top-k gap 显示 stored artifact 与 operationally reachable packet不是同一个 surface。memt full-store 0.130 是 context-overflow diagnostic，不能与其他 full-store rows直接比较。（§§4.3–4.4；Tables 2–4，physical PDF pp. 7–9）","Paper-reported：Assistance Preference 在所有 comparable rows 中最高，Episodic Memory 最低；作者把 episodic deficit解释为 event、context 与 consequence 的 binding problem，而不只是 isolated fact 没被保存。（§4.5；Table 3，physical PDF pp. 7、9）","Paper-reported human audit：satisfied end state 在 48/50 samples中被判 reasonable；failure attribution 与 human relabel 在 90/120 stratified samples中一致，但 Memory row exact agreement只有 20/30。该 audit支持“broadly reliable”这一有限措辞，不把 individual labels升级为 human gold或 causal truth。（Appendix G；Tables 11–12，physical PDF p. 24）","Fixed-artifact recalculation：formal receipts登记1,550 registered targets与13,950 run-bound target rows；fixed joins、quarter-step arithmetic、aggregate-report comparison、packet membership/binding与stored attribution reduction结果为 11项fixed-artifact gates全部为true；九个runs均INDEPENDENT_RECALCULATION_SUCCEEDED且50-user released-aggregate gates通过；30,379个packet items均adapter schema通过、EXACT_MEMBER且match_count=1；13,950个stored attribution rows均REDUCTION_CONSISTENT，同时input binding均为PARTIALLY_BOUND / HISTORICAL_INPUT_UNVERIFIED。","Replay boundary：source replay materials=BLOCKED；historical execution replay=NOT_ATTEMPTED。这条必须与 fixed-artifact result 并列展示；internal consistency 通过也不能被写成 MEMPROBE rerun。"],"evidenceLimits":["paper 是 2026-06-23 的 arXiv v1 preprint；当前 material没有 peer-reviewed venue claim。实验只覆盖 50 个 U.S.-based DeepPersona synthetic users、固定 assistant scaffold、31 个被挑选为 meaningful/disclosable 的 dimensions与 everyday assistance tasks，不能外推到 multilingual、cross-cultural、privacy-protective、rapidly changing 或 real-user deployment。","hidden bank 是 generated synthetic benchmark target。exact bank/task/reconstruction join只证明 released fields相同，不证明 target真实、稳定、完整、non-stereotyped、psychometrically valid 或适合作为现实用户画像。","所有 recovery scores、slot-fill outputs、disclosure verdicts与 attribution stages 都来自 historical LLM calls。temperature=0 不提供 bit determinism；release缺少足以绑定每次 historical execution 的 exact model snapshot、raw request/response、rendered prompt hash、request ID、retry path 与 usage receipt，current source default不能补写这些 provenance。","dump_all 不是 pure write oracle。它仍经过 system-specific serialization、context window、slot filler 与 recovery judge；尤其 memt wholesale dump溢出 reader context。full-store低分不能单独定位为 evidence未写入，full-store高分也不证明 store形成了compact、authoritative user-state claim。","retrieve artifacts来自独立 released runs，且 historical native retriever state没有完整发布。stored packet-to-final-dump exact matching只建立 released membership或binding，不证明 current retriever会重现该 packet、该 packet就是 exact historical prompt payload、其中内容语义相关或不存在等价 evidence。","`memory_failure` 是 current attribution vocabulary中的 downstream-of-disclosure bucket；source明示该 pipeline不调查 read-side slot filling，并把 write与read loss聚合。stored reduction一致性不能隔离 writing、storage、serialization、retrieval、context construction、slot filling、judging 或 attribution本身。","paper Appendix J cases 是作者选取的 audited illustrations；user_022 polarity case与 user_005 geographic-knowledge case可用于解释 seam，不能估计 prevalence、severity或 system ranking。本地 rule-selected case同样只是机械选出的 illustration，不是随机样本。","本站 audit不复制 hidden bank、task、transcript、final memory、retrieved content、prediction、reason或rationale；public-safe hashes与locators允许检查 identity，但不能让读者在没有 separately obtained rights-compatible exact source checkout时进行 semantic reinspection。"],"sourceTensions":[{"label":"Full-store 与 write-side oracle 之间仍隔着 reader","observation":"paper 在§3.1把 dump_all / retrieve comparison写成区分 write-side与read-side failure的主要诊断，但§3.4、Appendix A和memt footnote也承认 dump_all仍须把完整store序列化给slot filler，并可能因context overflow而退化。source中的 scorer同样在两种mode后继续调用同一个slot-fill与judge path。","implication":"dump_all是forensic access condition，不是直接读取semantic truth。full/retrieve score只能被称为paired historical artifact scores；若没有exact payload与reader provenance，不能把差值直接命名为write loss或read-path causal estimate。","locators":["§§3.1、3.4、4.3；Table 2 footnote，physical PDF pp. 5–8","Appendix A、I，physical PDF pp. 14、25–26","official source 19bb8364… scorer.py"]},{"label":"True cause 措辞强于 stored attribution evidence","observation":"§3.5称pipeline会找出 `exactly what went wrong` 并把low-score case分到 `true cause`；current failure_attribution.py 顶部却明示不调查read side并假定slot-fill正常，`memory_failure`因此聚合写入、读取与后续measurement seams。human audit又显示Memory row只有20/30 exact agreement。","implication":"public material必须把这些字段叫stored attribution labels或historical LLM verdicts。机械stage-to-label consistency可以验证control flow，不能验证causal category或把所有memory_failure计为系统write fault。","locators":["§3.5，physical PDF p. 6","Appendix G；Table 12，physical PDF p. 24","official source 19bb8364… failure_attribution.py"]},{"label":"Paper artifact inventory 与 exact release tree 不完全吻合","observation":"Appendix C / Table 7把 `merge_50u_reports.py` 列为released analysis script，并称scoring artifacts包含slot-fill prompts；exact tree没有该named script，recon JSON保存prediction、slot-fill reason、judge score/reason等字段却没有rendered prompt field。scorer.py仍包含aggregate/save与prompt template代码，所以缺件限制的是exact historical replay，不等于aggregate不可重算。","implication":"source-replay inventory应分别报告 named-path absence、template presence、fixed JSON arithmetic与historical prompt absence；不能用AMS-authored replacement补齐后称official reproduction，也不能因一个named script缺失便夸大为all aggregates unrecomputable。","locators":["Appendix C；Table 7，physical PDF pp. 16–17","official source 19bb8364… scorer.py","official source 19bb8364… output/*/recon_judge/"]},{"label":"Retrieve attribution 的 history identity 没有在 current path 中闭合","observation":"released retrieve outputs位于 `output/<base>_retrieve`，但release只保留五个base-run history directories；current `_load_episode(run, ...)`按传入run ID直接读取 `history/<run>/...`。因此若用retrieve run ID执行current documented attribution path，它不会自动映射回base history。","implication":"released retrieve attribution labels可以做stored reduction audit，却不能仅凭current function path被称为可重放的historical attribution。exact generation route、base-run mapping与prompt/input binding保持unverified。","locators":["official source 19bb8364… failure_attribution.py::_load_episode","official source 19bb8364… history/ and output/ run registries","research/memprobe-recovery-boundary-audit/raw/replay_inventory.json"]},{"label":"Empty retrieve packet 没有保留 failure provenance","observation":"current scorer在 native `agent.search(query,k=5)` 抛出 broad Exception 时把retrieved_memories写成空list，合法zero-hit也使用同一empty representation；release没有为每个packet保留retriever exception/attempt receipt。","implication":"empty或short packet只能作为stored packet cardinality observation。它不能区分valid zero-hit、retriever error、fallback、timeout或historical state absence，也不能自动成为retrieval failure计数。","locators":["official source 19bb8364… scorer.py native-retrieve branch","official source 19bb8364… output/*_retrieve/recon_judge/","research/memprobe-recovery-boundary-audit/raw/packet_rows.jsonl and raw/packet_items.jsonl"]},{"label":"Directional natural-language slots 会让 state label 本身成为 measurement surface","observation":"Appendix J 的 pushback_tolerance case里，底层behavior都指向希望assistant给出具体、坚定的纠正，但 `high pushback tolerance` 与 `low pushback tolerance` 的表述可收到相反judge verdict。paper Limitations明确承认surface form与axis polarity可能翻转score。","implication":"structured state representation需要canonical polarity、definition与counterexample，不应只给一个natural-language slot name。否则benchmark既在测memory，也在测reader与judge如何解释该label。","locators":["Appendix A，physical PDF p. 14","Appendix J Case 3，physical PDF p. 28"]}],"editorialInferences":[{"label":"Recovery is an observation chain, not one score","text":"可恢复性至少包含target identity、disclosure opportunity、write/retain、serialization、candidate generation、retrieval ordering、active-context construction、slot filling与judging。把这些折成一个B方便比较，却会隐藏“看不见”究竟发生在哪条edge。","boundary":"这是对paper protocol、source seams与fixed-artifact audit的architecture synthesis；不是对任何system的unobserved internal cause判定。"},{"label":"Artifact identity must include the reader contract","text":"同一final store在不同serialization、query、k、context budget、slot schema、model snapshot或judge rubric下可以产生不同reconstruction。一个可复核的memory benchmark receipt应同时绑定store bytes与reader/judge contract，而不能只版本化memory backend。","boundary":"release inspection证明若干historical binding缺失；本站没有重跑替代reader，也没有测不同reader contracts对ranking的影响。"},{"label":"The retrieval query is part of the benchmark ontology","text":"axis-only query `What best describes the user's <dimension>?` 把concrete task evidence映射到abstract state label。user_005 geographic_knowledge case说明，query–content mismatch既可能是retriever问题，也可能是benchmark选择的abstraction seam。","boundary":"这是paper case与fixed query design支持的reading；单个case不证明某种query普遍更好，也不把stored packet miss自动归因给system。"},{"label":"Attribution labels need causal humility","text":"一个stored decision tree可以完全自洽，却依赖错误的disclosure verdict、含混slot label或不可见prompt。可靠的attribution receipt应同时公开decision reduction与input observability，并允许`not determined`成为一等结果。","boundary":"本站只检查stored stages如何reduce；没有human re-label、semantic re-judgment或historical prompt replay。"},{"label":"Auditability and profiling risk grow together","text":"能够从长期interaction恢复更丰富user state，有助于检查memory到底保存了什么，也同时提高profiling、unwanted personalization与privacy exposure。inspect、consent、minimization、correction与deletion authority应和recovery objective一起设计。","boundary":"paper Broader Impact支持该治理方向；synthetic benchmark与本站read-only audit没有测试任何real-user consent、deletion或legal-compliance mechanism。"}],"openProtocols":[{"title":"Payload-bound recovery and causal-seam protocol","status":"proposed-not-run","question":"如果每个 target 都绑定 exact final-store snapshot、retriever native state、query、candidate/ranking packet、rendered slot-fill payload、raw model response、judge request/response与attribution input，我们能否在不把historical LLM labels当ground truth的前提下，把低recovery case分成write absence、serialization/context loss、candidate miss、ranking miss、slot interpretation与judge disagreement？","method":"在authors或future release提供的immutable run bundle上，为每个(user, dimension, mode)建立content-addressed edge manifest；先做byte-level completeness与cross-edge identity verification，再由blind human panel在不看system name和headline score的条件下分别标注target support、packet relevance、slot polarity与judge agreement。对同一stored snapshot执行registered query/k/context/slot-schema perturbations，但把这些fresh treatments与historical run完全分开。","fixtures":"exact native memory/retriever snapshots；final dumps；candidate and ranked top-k packets；rendered slot-fill and judge payloads；raw responses与retry logs；paper polarity case、abstract-query/concrete-evidence case、empty-packet strata；newly authored polarity-neutral synthetic controls。","controls":"source/data/model/runtime/prompt hashes；historical-versus-fresh treatment separation；valid zero-hit与forced retriever exception；same packet with alternative serialization；same evidence under canonical/ambiguous polarity labels；judge blinding；human inter-rater agreement；no target text leaked into retrieval query；no synthetic control counted as benchmark result。","measures":"edge-complete fraction；candidate recall与rank-conditioned support；context admission rate；slot-label disagreement；model/human score agreement；attribution abstention rate；full-store/top-k delta按observable edge重新分解后的case counts；uncertainty与unresolved fraction。","limitations":"这是proposed-not-run protocol，需要current release未提供的native state、raw payloads与historical provenance；fresh reruns不会恢复historical execution，也不能从synthetic users外推real-user profiling quality、安全性或deployment benefit。"}],"contributions":[{"type":"public-test","title":"Fixed released-artifact consistency and recovery-boundary audit","byline":"Agent Memory Study editors","date":"2026-08-29","basis":"Paper-facing audit of arXiv:2606.24595v1 and the exact clean official MEMPROBE release at 19bb83644b082489b4e181e59f1cded1a00d0529, covering 1,550 registered hidden-bank/task targets, nine reconstruction and attribution runs, five designated final-memory stores, run reports, scorer and failure-attribution source paths.","boundary":"This is an independently authored, offline fixed released-artifact consistency audit under a frozen, non-blinded protocol. It is not a MEMPROBE benchmark rerun, historical simulator/assistant/memory/retriever/slot-fill/judge/attribution replay, semantic re-judgment, human validation, causal attribution, system-quality ranking, effect or prevalence estimate, paper-result invalidation, real-user study, privacy audit, or production evaluation. The source field `ground_truth` is treated only as a synthetic benchmark hidden target. Historical LLM outputs remain historical artifacts; current source defaults do not establish their exact model or request identity.","method":"Reject a wrong or dirty official checkout; hash the exact 32-page paper and every registered input; register the 1,550 user/category/dimension targets independently of run outputs; exhaustively join bank, task, episode, reconstruction and attribution identities using typed run-bound keys; recompute quarter-step category-balanced per-user and across-user arithmetic with Fraction and sample standard deviation; bind every non-empty retrieve-packet item to its designated released final dump through four frozen system-specific adapters; independently reduce stored attribution stages with a declarative typed truth table; inventory missing/null/blank output states and source-replay provenance; execute isolated mutation falsifiers; run the complete checker twice in fresh processes/roots/output directories with different hash seeds; then perform receipt-only and source-bound checked verification.","environment":"Darwin arm64；CPython 3.13.3；exact clean official commit 19bb83644b082489b4e181e59f1cded1a00d0529 and exact arXiv v1 PDF；Python standard library only；frozen locale/timezone；process-local DNS/socket guard；two fresh output roots and explicit distinct PYTHONHASHSEED values；no upstream environment installation and no simulator, assistant, memory backend, retriever, slot filler, judge, attribution model, OpenAI API, network endpoint or Mem-T/vLLM service called。","fixture":"50 synthetic hidden banks and 50 matched 31-task files；1,550 independently registered user/category/dimension targets；five 7/7/7/5/5 category groups per user；nine registered run identities with full-store/retrieve mode binding；five base histories/final stores；all per-user reconstruction, attribution and candidate aggregate reports；four frozen packet/store adapters；stored quarter-step scores and attribution stages；three preregistered public-safe illustration strata；AMS-authored deep-copy mutations for identity, typed equality, packet schema/membership, arithmetic and attribution-threshold controls。","controls":"Exact paper/source/tree/input hashes；clean-worktree pre/post gates；registered target/run/user/category/dimension sets；Boolean-number and integer-decimal type separation；attribution-copy recursive equality；full 7/7/7/5/5 arithmetic oracle；multiple/partial aggregate-report inventory；wrong designated-store mapping；missing, modified and duplicate packet items；required/extra packet fields；all legal and malformed attribution-stage sequences including exactly 0.75；deep-copy immutability receipts；network-attempt receipt；deny-listed upstream free-text scanner；two-run byte comparison over 16 primary receipts；complete checksum coverage；receipt-only versus source-bound verifier distinction。","rawResult":"Formal checked package records 1,550 registered targets, 13,950 target-join rows, 13,950 attribution rows, 6,200 retrieve-packet rows, 30,379 packet-item rows, 6,200 paired historical artifact deltas and 16 primary receipts. The installed decision, arithmetic, packet, attribution, observability, replay, mutation, safety and comparison receipts report: 11项fixed-artifact gates全部为true；九个runs的quarter-step per-user/across-user arithmetic均独立重算成功且canonical 50-user aggregate reports matched；Table 2的九个display cross-check中8个mean/std pairs按三位小数相符，memt full-store fixed mean=0.13054285714285715因四舍五入应为0.131而非paper显示的0.130，fixed std=0.250832166019839与0.251相符；30,379个packet items均EXACT_MEMBER且唯一绑定；13,950个stored attribution reductions均consistent但historical inputs仅partial-bound；57个mutation controls全部caught expected gate；两次16-file primary manifests byte-identical、environment/source identity bound且network attempts为0；public-safety receipt扫描其余15份primary files并记录0 local paths、secret patterns与upstream continuous eight-token spans. The registered-input manifest contains 8,980 exact paper/source inputs；mutation controls report 57 expected gates caught；source-bound verifier result is PASS: source-bound revalidation; worked_fixed_artifact_audit=PASS. These values come from checked receipts and the executed verifier, not from paper tables or reconnaissance notes.","derivedResult":"At exact revision 19bb83644b082489b4e181e59f1cded1a00d0529, the independently authored offline checker verified the 1,550-target registry and 13,950 run-bound joins, recomputed category-balanced and across-user arithmetic from stored historical quarter-step judge outputs, established exact unique binding for all 30,379 stored retrieve-packet items under frozen system-specific adapters, and checked only the deterministic reduction of stored attribution stages to stored labels. Two fresh executions produced byte-identical 16-file primary manifests and source-bound revalidation passed. This establishes fixed released-artifact consistency at one revision while source replay materials remain BLOCKED and historical execution replay remains NOT_ATTEMPTED. The strongest permitted interpretation remains exact-revision released-artifact consistency: run-bound joins, arithmetic over stored historical quarter-step judge outputs, packet-to-designated-dump matching under frozen adapters, and deterministic reduction of stored attribution stages. Only a formal packet_unique_binding PASS permits unqualified `lineage`. Neither a passing package nor same-machine byte identity establishes semantic support, historical prompt admission, replayed retrieval, causal memory failure, benchmark validity, end-to-end reproduction, cross-platform portability or real-user generalization.","limitations":"The protocol was frozen after paper/source/schema reconnaissance and Oracle review, so it is preregistered relative to runner execution but not blinded to the release. Exact membership does not establish semantic support, sufficiency or historical prompt admission. Historical native retriever state, raw model requests/responses, rendered prompt hashes, exact model snapshots and per-call receipts are incomplete or absent. Synthetic mutation controls test the checker, not the benchmark. Public receipts intentionally omit upstream free text. Two-run same-machine byte identity establishes checker repeatability only, not correctness or cross-platform reproduction. Top-level CC BY 4.0 does not relicense vendored systems, taxonomies, weights or services, and AMS-authored code/editorial prose receives no new public license grant.","links":[{"label":"method, results and claim ceiling","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/README.md"},{"label":"frozen pre-execution protocol","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/PROTOCOL.md"},{"label":"source-locked offline runner","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/audit.py"},{"label":"bounded gate decision","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/decision.json"},{"label":"independent 1,550-target registry","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/target_registry.json"},{"label":"exhaustive run-bound target joins","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/target_joins.jsonl"},{"label":"store and history census","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/store_census.json"},{"label":"fixed historical-score arithmetic","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/arithmetic.json"},{"label":"retrieve-packet cardinalities","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/packet_rows.jsonl"},{"label":"packet-item to final-dump bindings","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/packet_items.jsonl"},{"label":"stored attribution reductions and input observability","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/attribution_rows.jsonl"},{"label":"stored-output observability inventory","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/observability.json"},{"label":"paired historical artifact deltas","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/paired_deltas.jsonl"},{"label":"source replay-material and historical-provenance inventory","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/replay_inventory.json"},{"label":"complete registered-input manifest","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/input_manifest.json"},{"label":"mutation-control receipts","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/mutation_controls.json"},{"label":"public projection safety receipt","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/public_safety.json"},{"label":"two-run byte comparison receipt","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/raw/comparison.json"},{"label":"checked receipt and source-bound verifier","url":"https://github.com/IndelibleVivi/agent-memory-study/blob/main/research/memprobe-recovery-boundary-audit/verify_checked.py"}]}]}]};
